const DATA_RESTANTES = [{"id":"pen-lei-11343-pdf14-q001","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 1º","number":"Art. 1º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 1º Esta Lei institui o Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas e define crimes."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006 é a atual Lei sobre drogas. Tendo por base os ditames do citado diploma, é correto afirmar que o referido diploma legal institui o Sistema Nacional de Políticas Públicas sobre Drogas.","answer":true,"explanation":"Art. 1º Esta Lei institui o Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas e define crimes.","source":"14.pdf · questão 1 · Art. 1º, Lei 11.343/2006","meta":"FUNDATEC 2018 - Escrivão de Polícia (PC-RS) - Adaptada","bank":"FUNDATEC","year":2018,"role":"Escrivão de Polícia (PC-RS) - Adaptada","origin":"real"}},{"id":"pen-lei-11343-pdf14-q004","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 1º, § único","number":"Art. 1º, § único","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 1º. [...] Parágrafo único. Para fins desta Lei, consideram-se como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006 prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e define crimes relacionados a essa questão, entre outras prescrições. Para fins dessa Lei, o artigo 1º (parágrafo único) considera como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União.","answer":true,"explanation":"Art. 1º. [...] Parágrafo único. Para fins desta Lei, consideram-se como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União.","source":"14.pdf · questão 4 · Art. 1º, § único, Lei 11.343/2006","meta":"VUNESP 2025 - Cuidador Social (Prefeitura de Sertãozinho - SP)","bank":"VUNESP","year":2025,"role":"Cuidador Social (Prefeitura de Sertãozinho - SP)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q007","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 2º","number":"Art. 2º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso."],"origin":"real","question":{"statement":"Julgue o item subsecutivo, com relação ao Sistema Nacional de Políticas Públicas sobre Drogas. No Brasil, há proibição de plantio, cultura, colheita e exploração de vegetais dos quais possam ser extraídas drogas, salvo na hipótese, por exemplo, do previsto na Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971.","answer":true,"explanation":"Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso.","source":"14.pdf · questão 7 · Art. 2º, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2022 – Assistente Social (FUB)","bank":"CESPE/CEBRASPE","year":2022,"role":"Assistente Social (FUB)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q012","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 2º, § único","number":"Art. 2º, § único","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso. Parágrafo único. Pode a União autorizar o plantio, a cultura e a colheita dos vegetais referidos no caput deste artigo, exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização, respeitadas as ressalvas supramencionadas."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas; define crimes e dá outras providências. Essa lei, “proíbe em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar e pela União, respectivamente, em situações estritamente ritualístico-religioso e exclusivamente para fins medicinais ou científicos.","answer":true,"explanation":"Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso. Parágrafo único. Pode a União autorizar o plantio, a cultura e a colheita dos vegetais referidos no caput deste artigo, exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização, respeitadas as ressalvas supramencionadas.","source":"14.pdf · questão 12 · Art. 2º, § único, Lei 11.343/2006","meta":"VUNESP 2025 - Cuidador Social (Prefeitura de Itapevi - SP)","bank":"VUNESP","year":2025,"role":"Cuidador Social (Prefeitura de Itapevi - SP)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q014","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º","number":"Art. 3º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas; II - a repressão da produção não autorizada e do tráfico ilícito de drogas."],"origin":"real","question":{"statement":"Considerando o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), instituído pela Lei n.º 11.343/2006, julgue o item que se segue. O SISNAD tem como finalidade articular, integrar, organizar e coordenar as atividades relacionadas com a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas, assim como a repressão da produção não autorizada e do tráfico ilícito de drogas.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas; II - a repressão da produção não autorizada e do tráfico ilícito de drogas.","source":"14.pdf · questão 14 · Art. 3º, Lei 11.343/2006","meta":"CESPE 2018 - Analista Judiciário - Serviço Social (STM)","bank":"CESPE","year":2018,"role":"Analista Judiciário - Serviço Social (STM)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q016","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º, I","number":"Art. 3º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas;"],"origin":"real","question":{"statement":"O Sistema Nacional de Políticas Públicas sobre Drogas prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas. De acordo com a Lei nº 11.343, de 23 de agosto de 2006, é correto afirmar que o SISNAD articula, integra, organiza e coordena as atividades relacionadas com a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas;","source":"14.pdf · questão 16 · Art. 3º, I, Lei 11.343/2006","meta":"FGV 2023 - Técnico de Gestão Administrativa (ALEMA)","bank":"FGV","year":2023,"role":"Técnico de Gestão Administrativa (ALEMA)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q019","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º, § 2º","number":"Art. 3º, § 2º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: [...] § 2º O Sisnad atuará em articulação com o Sistema Único de Saúde - SUS, e com o Sistema Único de Assistência Social - SUAS."],"origin":"real","question":{"statement":"Criado em 2006, o Sistema Nacional de Políticas sobre Drogas (SISNAD) é responsável por elaborar medidas de atenção reinserção social de usuários e dependentes de drogas, medidas de prevenção do uso indevido e as normas para repressão ao tráfico ilícito de drogas. Esse sistema, de acordo com a lei, está articulado com o Sistema Único de Saúde e o Sistema Único de Assistência Social.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: [...] § 2º O Sisnad atuará em articulação com o Sistema Único de Saúde - SUS, e com o Sistema Único de Assistência Social - SUAS.","source":"14.pdf · questão 19 · Art. 3º, § 2º, Lei 11.343/2006","meta":"FCC 2023 - Analista Judiciário (TJ-BA)","bank":"FCC","year":2023,"role":"Analista Judiciário (TJ-BA)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q022","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º","number":"Art. 4º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: […] VII - a integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito;"],"origin":"real","question":{"statement":"A Lei no 11.343, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas - SISNAD, prescrevendo medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, bem como estabelecendo normas para repressão à produção não autorizada e ao tráfico ilícito de drogas. Sobre isso, considere: A integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, diz respeito a um dos princípios estabelecidos na Lei.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: […] VII - a integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito;","source":"14.pdf · questão 22 · Art. 4º, Lei 11.343/2006","meta":"FCC 2015 - Analista Judiciário - Serviço Social (TRT - 3ª Região)","bank":"FCC","year":2015,"role":"Analista Judiciário - Serviço Social (TRT - 3ª Região)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q023","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, I","number":"Art. 4º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: I - o respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade;"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. O respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: I - o respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade;","source":"14.pdf · questão 23 · Art. 4º, I, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q026","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, III","number":"Art. 4º, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] III - a promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados;"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. A promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: [...] III - a promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados;","source":"14.pdf · questão 26 · Art. 4º, III, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q027","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, II","number":"Art. 4º, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] II - o respeito à diversidade e às especificidades populacionais existentes; [...]"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. O respeito à diversidade e às especificidades populacionais existentes.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: [...] II - o respeito à diversidade e às especificidades populacionais existentes; [...]","source":"14.pdf · questão 27 · Art. 4º, II, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q029","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, V","number":"Art. 4º, V","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] V - a promoção da responsabilidade compartilhada entre Estado e Sociedade, reconhecendo a importância da participação social nas atividades do Sisnad;"],"origin":"real","question":{"statement":"A Lei n.º 11.343/2006, que instituiu o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), reconhece, entre os princípios desse sistema, a supremacia do Estado nas questões do enfretamento ao uso indevido de drogas.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] V - a promoção da responsabilidade compartilhada entre Estado e Sociedade, reconhecendo a importância da participação social nas atividades do Sisnad;","source":"14.pdf · questão 29 · Art. 4º, V, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2021 - Analista Ministerial (MPEAP)","bank":"CESPE/CEBRASPE","year":2021,"role":"Analista Ministerial (MPEAP)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q031","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, VIII","number":"Art. 4º, VIII","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] VIII - a articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad;"],"origin":"real","question":{"statement":"A Lei Federal nº 11.343 de 23 de agosto de 2006 institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad e disciplina, no artigo 5º como objetivos do referido sistema aqueles que: A articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] VIII - a articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad;","source":"14.pdf · questão 31 · Art. 4º, VIII, Lei 11.343/2006","meta":"IBFC 2022 - Analista Judiciário (TJ-MG)","bank":"IBFC","year":2022,"role":"Analista Judiciário (TJ-MG)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q032","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, IX","number":"Art. 4º, IX","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: […] IX - a adoção de abordagem multidisciplinar que reconheça a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas;"],"origin":"real","question":{"statement":"A Lei n 11.343, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas - SISNAD, prescrevendo medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, bem como estabelecendo normas para repressão à produção não autorizada e ao tráfico ilícito de drogas. Sobre isso, considere: A adoção de abordagem interdisciplinar que reconhece a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas é uma das premissas da legislação vigente.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: […] IX - a adoção de abordagem multidisciplinar que reconheça a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas;","source":"14.pdf · questão 32 · Art. 4º, IX, Lei 11.343/2006","meta":"FCC 2015 - Analista Judiciário - Serviço Social (TRT - 3ª Região)","bank":"FCC","year":2015,"role":"Analista Judiciário - Serviço Social (TRT - 3ª Região)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q033","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, X","number":"Art. 4º, X","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] X - a observância do equilíbrio entre as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, visando a garantir a estabilidade e o bem-estar social;"],"origin":"real","question":{"statement":"A Lei n.º 11.343/2006, que instituiu o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), reconhece, entre os princípios desse sistema, a priorização das políticas de prevenção do uso indevido de drogas, de atenção e de reinserção social de usuários em detrimento da política de repressão à produção não autorizada dessas substâncias.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] X - a observância do equilíbrio entre as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, visando a garantir a estabilidade e o bem-estar social;","source":"14.pdf · questão 33 · Art. 4º, X, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2021 - Analista Ministerial (MPEAP)","bank":"CESPE/CEBRASPE","year":2021,"role":"Analista Ministerial (MPEAP)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q034","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, I","number":"Art. 5º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: I - contribuir para a inclusão social do cidadão, visando a torná-lo menos vulnerável a assumir comportamentos de risco para o uso indevido de drogas, seu tráfico ilícito e outros comportamentos correlacionados;"],"origin":"real","question":{"statement":"Julgue o item a seguir, relativos ao Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD). O SISNAD visa, principalmente, contribuir para a inclusão social da família, de modo a torná-la menos vulnerável a assumir comportamentos de risco que contribuam para o uso indevido de drogas.","answer":false,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: I - contribuir para a inclusão social do cidadão, visando a torná-lo menos vulnerável a assumir comportamentos de risco para o uso indevido de drogas, seu tráfico ilícito e outros comportamentos correlacionados;","source":"14.pdf · questão 34 · Art. 5º, I, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2025 – Assistente Social (Polícia Federal)","bank":"CESPE/CEBRASPE","year":2025,"role":"Assistente Social (Polícia Federal)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q036","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, II","number":"Art. 5º, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: [...] II - promover a construção e a socialização do conhecimento sobre drogas no país;"],"origin":"real","question":{"statement":"Sobre a Lei de Drogas (Lei nº 11.343/2006), julgue o item. Promover a construção e a socialização do conhecimento sobre drogas no país é um dos princípios do Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad.","answer":false,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: [...] II - promover a construção e a socialização do conhecimento sobre drogas no país;","source":"14.pdf · questão 36 · Art. 5º, II, Lei 11.343/2006","meta":"Instituto AOCP 2024 - Soldado (PM-PE)","bank":"Instituto AOCP","year":2024,"role":"Soldado (PM-PE)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q039","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, III","number":"Art. 5º, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: [...] III - promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios;"],"origin":"real","question":{"statement":"A Lei Federal nº 11.343 de 23 de agosto de 2006 destaca em seu artigo 5º que o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD) possui como objetivo: Promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios.","answer":true,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: [...] III - promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios;","source":"14.pdf · questão 39 · Art. 5º, III, Lei 11.343/2006","meta":"IBFC 2022 - Orientador Social (Prefeitura de Dourados - MS)","bank":"IBFC","year":2022,"role":"Orientador Social (Prefeitura de Dourados - MS)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q040","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º, § 1º","number":"Art. 8º, § 1º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: [...] § 1º O plano de que trata o caput terá duração de 5 (cinco) anos a contar de sua aprovação."],"origin":"real","question":{"statement":"O Plano Nacional de Políticas sobre Drogas terá duração de 15 anos a contar de sua aprovação.","answer":false,"explanation":"Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: [...] § 1º O plano de que trata o caput terá duração de 5 (cinco) anos a contar de sua aprovação.","source":"14.pdf · questão 40 · Art. 8º, § 1º, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC) - Adaptada","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC) - Adaptada","origin":"real"}},{"id":"pen-lei-11343-pdf14-q041","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, I","number":"Art. 8º-A, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A Compete à União: I - formular e coordenar a execução da Política Nacional sobre Drogas; *O inciso NÃO menciona a parceria da União com Estados, Distrito Federal, Municípios e Sociedade!"],"origin":"real","question":{"statement":"Compete à União, em parceria com Estados, Distrito Federal, Municípios e a sociedade, formular e coordenar a execução da Política Nacional sobre Drogas.","answer":false,"explanation":"Art. 8º-A Compete à União: I - formular e coordenar a execução da Política Nacional sobre Drogas; *O inciso NÃO menciona a parceria da União com Estados, Distrito Federal, Municípios e Sociedade!","source":"14.pdf · questão 41 · Art. 8º-A, I, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q042","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, II","number":"Art. 8º-A, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A. Compete à União: [...] II - elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade;"],"origin":"real","question":{"statement":"Compete à União elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade.","answer":true,"explanation":"Art. 8º-A. Compete à União: [...] II - elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade;","source":"14.pdf · questão 42 · Art. 8º-A, II, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q043","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, III","number":"Art. 8º-A, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A Compete à União: [...] III - coordenar o Sisnad;"],"origin":"real","question":{"statement":"Compete à União, com Estados, Distrito Federal e Municípios, coordenar o Sisnad.","answer":false,"explanation":"Art. 8º-A Compete à União: [...] III - coordenar o Sisnad;","source":"14.pdf · questão 43 · Art. 8º-A, III, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q044","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, IX","number":"Art. 8º-A, IX","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A. Compete à União: [...] IX - financiar, com Estados, Distrito Federal e Municípios, a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad;"],"origin":"real","question":{"statement":"Compete exclusivamente à União financiar a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad.","answer":false,"explanation":"Art. 8º-A. Compete à União: [...] IX - financiar, com Estados, Distrito Federal e Municípios, a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad;","source":"14.pdf · questão 44 · Art. 8º-A, IX, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"pen-lei-11343-pdf14-q048","discipline":"penal","topicId":"pen-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-D, IV","number":"Art. 8º-D, IV","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: I - promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer, visando à prevenção do uso de drogas, atenção e reinserção social dos usuários ou dependentes de drogas;"],"origin":"real","question":{"statement":"A Lei nº 13.840 de 5 de junho de 2019, trata do Sistema Nacional de Políticas Públicas sobre Drogas, definindo as condições de atenção aos usuários ou dependentes de drogas e trata do financiamento das políticas sobre drogas. O Plano Nacional de Políticas sobre Drogas propõe certos objetivos. A partir disso, julgue o item levando em consideração os objetivos propostos pela Lei. Um dos objetivos é promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas.","answer":true,"explanation":"Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: I - promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer, visando à prevenção do uso de drogas, atenção e reinserção social dos usuários ou dependentes de drogas;","source":"14.pdf · questão 48 · Art. 8º-D, IV, Lei 11.343/2006","meta":"IBFC 2022 - Analista (DPE-MT)","bank":"IBFC","year":2022,"role":"Analista (DPE-MT)","origin":"real"}},{"id":"pen-lei-12850-pdf23-q022","discipline":"penal","topicId":"pen-lei-12850","subtopic":"Lei 12.850/2013 · Art. 1º, § 1º","number":"Art. 1º, § 1º","title":"Lei 12.850/2013 — Organizações Criminosas","parts":["Art. 1º. […] § 1º Considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas máximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional."],"origin":"real","question":{"statement":"No julgamento da ADI 5.567, o STF pontuou que \"a criminalidade organizada é, hoje, um dos maiores problemas do mundo moderno. Apesar de não se tratar de fenômeno recente, o crescimento das organizações criminosas representa uma grave ameaça à sociedade, especialmente pelo grau de lesividade dos crimes por ela praticados e pela influência negativa que exercem dentro do próprio Estado. Dentro desse contexto de criminalidade organizada, a implementação de instrumentos processuais penais modernos, com mecanismos de ação controlada, punições mais severas e isolamento de lideranças criminosas são medidas para que o Estado equilibre forças com as referidas organizações criminosas, sob pena de tornar inócua grande parte das investigações criminais, principalmente no que tange à obtenção de provas\". (Fonte: https://portal.stf.jus.br/processos/downloadPeca.asp?id= 15364039995&ext=.pdf) Quanto ao conceito de organizações criminosas e os instrumentos processuais penais, no contexto da Lei nº 12.850, de 2 de agosto de 2013, é correto afirmar que considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas mãximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional.","answer":true,"explanation":"Art. 1º. […] § 1º Considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas máximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional.","source":"23.pdf · questão 22 · Art. 1º, § 1º, Lei 12.850/2013","meta":"CETAP 2025 - Guarda Civil Municipal (Prefeitura de Marituba-PA)","bank":"CETAP","year":2025,"role":"Guarda Civil Municipal (Prefeitura de Marituba-PA)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q001","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Ementa da Lei 11.340/2006","number":"Ementa da Lei 11.340/2006","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["LEI Nº 11.340, DE 7 DE AGOSTO DE 2006 Cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências."],"origin":"real","question":{"statement":"A Lei Federal nº 11.340, de 7 de agosto de 2006, cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências.","answer":true,"explanation":"LEI Nº 11.340, DE 7 DE AGOSTO DE 2006 Cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências.","source":"13.pdf · questão 1 · Lei 11.340/2006","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PC-BA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PC-BA)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q004","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 1º","number":"Art. 1º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 1º - Esta Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher e de outros tratados internacionais ratificados pela República Federativa do Brasil; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; e estabelece medidas de assistência e proteção às mulheres em situação de violência doméstica e familiar."],"origin":"real","question":{"statement":"Sobre a Lei Maria da Penha, Lei nº 11.340/2006, que completou 18 anos em agosto de 2024, julgue o item a seguir. A legislação combate somente a violência doméstica e não a familiar.","answer":false,"explanation":"Art. 1º - Esta Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher e de outros tratados internacionais ratificados pela República Federativa do Brasil; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; e estabelece medidas de assistência e proteção às mulheres em situação de violência doméstica e familiar.","source":"13.pdf · questão 4 · Art. 1º, Lei 11.340/2006","meta":"Instituto Consulplan 2025 - Auxiliar - Serviços Públicos (Prefeitura de Carangola - MG)","bank":"Instituto Consulplan","year":2025,"role":"Auxiliar - Serviços Públicos (Prefeitura de Carangola - MG)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q006","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 2º","number":"Art. 2º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 2º - Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social."],"origin":"real","question":{"statement":"Conforme o art. 2º da Lei nº 11.340/2006, julgue o item a seguir sobre os direitos garantidos às mulheres. Toda mulher, independentemente de sua orientação sexual ou religião, tem direito a viver sem violência.","answer":true,"explanation":"Art. 2º - Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social.","source":"13.pdf · questão 6 · Art. 2º, Lei 11.340/2006","meta":"IGEDUC 2025 - Assistente Social (Prefeitura de Japaratinga - AL)","bank":"IGEDUC","year":2025,"role":"Assistente Social (Prefeitura de Japaratinga - AL)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q008","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 3º","number":"Art. 3º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 3º - Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, representa um marco legal no combate à violência doméstica e familiar contra a mulher no Brasil. Ela se fundamenta em normas para assegurar proteção efetiva. No que se refere as disposições preliminares da Lei Maria da Penha, julgue o item a seguir. Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária.","answer":true,"explanation":"Art. 3º - Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária.","source":"13.pdf · questão 8 · Art. 3º, Lei 11.340/2006","meta":"AMEOSC 2025 - Assistente Social (Prefeitura de Guaraciaba - SC)","bank":"AMEOSC","year":2025,"role":"Assistente Social (Prefeitura de Guaraciaba - SC)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q009","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 3º, § 1º","number":"Art. 3º, § 1º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 3º, § 1º - O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares no sentido de resguardá-las de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão."],"origin":"real","question":{"statement":"Com base na Lei n.º 11.340/2006, relativa aos mecanismos para coibir a violência doméstica e familiar contra a mulher, julgue o item a seguir. Cabe ao poder público o desenvolvimento de políticas públicas voltadas à garantia dos direitos humanos da mulher no âmbito das relações domésticas e familiares, com o intuito de resguardá-la de todas as formas de violência, discriminação e opressão.","answer":true,"explanation":"Art. 3º, § 1º - O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares no sentido de resguardá-las de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.","source":"13.pdf · questão 9 · Art. 3º, § 1º, Lei 11.340/2006","meta":"CESPE/CEBRASPE 2023 - Analista - Apoio Jurídico (CNMP)","bank":"CESPE/CEBRASPE","year":2023,"role":"Analista - Apoio Jurídico (CNMP)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q010","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 4º","number":"Art. 4º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 4º - Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, representa um marco legal no combate à violência doméstica e familiar contra a mulher no Brasil. Ela se fundamenta em normas para assegurar proteção efetiva. No que se refere as disposições preliminares da Lei Maria da Penha, julgue o item a seguir. Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar.","answer":true,"explanation":"Art. 4º - Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar.","source":"13.pdf · questão 10 · Art. 4º, Lei 11.340/2006","meta":"AMEOSC 2025 - Assistente Social (Prefeitura de Guaraciaba - SC)","bank":"AMEOSC","year":2025,"role":"Assistente Social (Prefeitura de Guaraciaba - SC)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q015","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º","number":"Art. 5º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação."],"origin":"real","question":{"statement":"Julgue o item a seguir, considerando as disposições da Lei Maria da Penha (Lei n.º 11.340/2006). Configura violência doméstica e familiar contra a mulher ação baseada no gênero que lhe cause dano patrimonial em relação íntima de afeto na qual o agressor tenha convivido com a ofendida, independentemente de coabitação.","answer":true,"explanation":"Art. 5º Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação.","source":"13.pdf · questão 15 · Art. 5º, Lei 11.340/2006","meta":"CESPE/CEBRASPE 2025 - Agente Administrativo (PCDF)","bank":"CESPE/CEBRASPE","year":2025,"role":"Agente Administrativo (PCDF)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q019","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, I","number":"Art. 5º, I","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340, de 7 de agosto de 2006, conhecida como Lei Maria da Penha, institui, em seu Art. 5º, que a violência doméstica e familiar contra a mulher é qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial. Avalie se este artigo se aplica à seguinte situação: No âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas.","answer":true,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; [...]","source":"13.pdf · questão 19 · Art. 5º, I, Lei 11.340/2006","meta":"FGV 2023 - Analista de Promotoria - Assistente Social (MPE-SP)","bank":"FGV","year":2023,"role":"Analista de Promotoria - Assistente Social (MPE-SP)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q021","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, II","number":"Art. 5º, II","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340, de 7 de agosto de 2006, conhecida como Lei Maria da Penha, institui, em seu Art. 5º, que a violência doméstica e familiar contra a mulher é qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial. Avalie se este artigo se aplica à seguinte situação: No âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa.","answer":true,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; [...]","source":"13.pdf · questão 21 · Art. 5º, II, Lei 11.340/2006","meta":"FGV 2023 - Analista de Promotoria - Assistente Social (MPE-SP)","bank":"FGV","year":2023,"role":"Analista de Promotoria - Assistente Social (MPE-SP)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q027","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, III","number":"Art. 5º, III","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação. [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340/2006 leva o nome da farmacêutica Maria da Penha Maia Fernandes, vítima de duas tentativas de feminicídio e que tornou-se símbolo da luta contra a violência de gênero. Quanto à essa norma é correto afirmar que a incidência da Lei Maria da Penha exige convivência doméstica atual entre agressor e vítima, sendo inviável a sua aplicação quando a relação afetiva tiver cessado antes do fato.","answer":false,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação. [...]","source":"13.pdf · questão 27 · Art. 5º, III, Lei 11.340/2006","meta":"MPDFT 2025 - Promotor de Justiça (MP-DFT)","bank":"MPDFT","year":2025,"role":"Promotor de Justiça (MP-DFT)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q033","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, § único","number":"Art. 5º, § único","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] Parágrafo único - As relações pessoais enunciadas neste artigo independem de orientação sexual."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, estabelece: Configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial, desde que constatado que as relações entre os envolvidos são de natureza exclusivamente heterossexual.","answer":false,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] Parágrafo único - As relações pessoais enunciadas neste artigo independem de orientação sexual.","source":"13.pdf · questão 33 · Art. 5º, § único, Lei 11.340/2006","meta":"FCC 2023 - Técnico Ministerial (MPE-PB)","bank":"FCC","year":2023,"role":"Técnico Ministerial (MPE-PB)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q039","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 6º","number":"Art. 6º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 6º - A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos."],"origin":"real","question":{"statement":"A respeito da Lei nº 11.340/2006, mais conhecida como Lei Maria da Penha, julgue o item a seguir. A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos.","answer":true,"explanation":"Art. 6º - A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos.","source":"13.pdf · questão 39 · Art. 6º, Lei 11.340/2006","meta":"FAFIPA 2025 - Guarda Municipal (Prefeitura de Araucária - PR)","bank":"FAFIPA","year":2025,"role":"Guarda Municipal (Prefeitura de Araucária - PR)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q040","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 7º, I","number":"Art. 7º, I","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 7º São formas de violência doméstica e familiar contra a mulher, entre outras: I - a violência física, entendida como qualquer conduta que ofenda sua integridade ou saúde corporal; […]"],"origin":"real","question":{"statement":"A Lei Maria da Penha é uma legislação brasileira que cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, estabelecendo medidas protetivas de urgência, como afastamento do agressor e proibição de contato, além de punições mais severas para agressores. Conforme a referida Lei, é correto afirmar que a conduta que ofenda a integridade ou a saúde corporal da mulher é classificada como violência física.","answer":true,"explanation":"Art. 7º São formas de violência doméstica e familiar contra a mulher, entre outras: I - a violência física, entendida como qualquer conduta que ofenda sua integridade ou saúde corporal; […]","source":"13.pdf · questão 40 · Art. 7º, I, Lei 11.340/2006","meta":"FUNDATEC 2026 - Auditor Fiscal de Tributos (Prefeitura de Três Passos-RS)","bank":"FUNDATEC","year":2026,"role":"Auditor Fiscal de Tributos (Prefeitura de Três Passos-RS)","origin":"real"}},{"id":"pen-lei-11340-pdf13-q044","discipline":"penal","topicId":"pen-lei-11340","subtopic":"Lei 11.340/2006 · Art. 7º, II","number":"Art. 7º, II","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 7º - São formas de violência doméstica e familiar contra a mulher, entre outras: [...] II - a violência psicológica, entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação; [...]"],"origin":"real","question":{"statement":"Com base na Lei 11.340/2006, em relação à mulher, a violência entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação denominase violência psicológica.","answer":true,"explanation":"Art. 7º - São formas de violência doméstica e familiar contra a mulher, entre outras: [...] II - a violência psicológica, entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação; [...]","source":"13.pdf · questão 44 · Art. 7º, II, Lei 11.340/2006","meta":"Instituto ACCESS 2023 - Guarda Civil Metropolitano (Prefeitura de Ribeirão Preto - SP)","bank":"Instituto ACCESS","year":2023,"role":"Guarda Civil Metropolitano (Prefeitura de Ribeirão Preto - SP)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q001","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º","number":"Art. 1º","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no CP, consumados ou tentados: […]"],"origin":"real","question":{"statement":"A respeito da Lei dos Crimes Hediondos, julgue o seguinte item. São considerados hediondos apenas os crimes consumados, excluídos os tentados.","answer":false,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no CP, consumados ou tentados: […]","source":"52.pdf · questão 1 · Art. 1º, Lei 8.072/90","meta":"VUNESP 2022 - Investigador de Polícia (PC-SP)","bank":"VUNESP","year":2022,"role":"Investigador de Polícia (PC-SP)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q010","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, I","number":"Art. 1º, I","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: I - homicídio (art. 121), quando praticado em atividade típica de grupo de extermínio, ainda que cometido por 1 (um) só agente, e homicídio qualificado (art. 121, § 2º); (Redação dada pela Lei nº 15.159, de 2025)"],"origin":"real","question":{"statement":"A respeito da Lei dos Crimes Hediondos, julgue o seguinte item. O homicídio, previsto no “caput” do art. 121 do Código Penal, se praticado em atividade típica de grupo de extermínio, ainda que cometido por um único agente, é considerado crime hediondo.","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: I - homicídio (art. 121), quando praticado em atividade típica de grupo de extermínio, ainda que cometido por 1 (um) só agente, e homicídio qualificado (art. 121, § 2º); (Redação dada pela Lei nº 15.159, de 2025)","source":"52.pdf · questão 10 · Art. 1º, I, Lei 8.072/90","meta":"VUNESP 2022 - Investigador de Polícia (PC-SP)","bank":"VUNESP","year":2022,"role":"Investigador de Polícia (PC-SP)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q013","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, I-A, c","number":"Art. 1º, I-A, c","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: (Redação dada pela Lei nº 15.159, de 2025) c) nas dependências de instituição de ensino; (Incluído pela Lei nº 15.159, de 2025)"],"origin":"authorial","question":{"statement":"De acordo com a Lei 8.072/90 (Crimes hediondos), é correto afirmar que é considerado hediondo o seguinte crimes, tipificado no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumado ou tentado: lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas nas dependências de instituição de ensino.","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: (Redação dada pela Lei nº 15.159, de 2025) c) nas dependências de instituição de ensino; (Incluído pela Lei nº 15.159, de 2025)","source":"52.pdf · questão 13 · Art. 1º, I-A, c, Lei 8.072/90","meta":"Exercício importado · Lei 8.072/1990","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-8072-pdf52-q014","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, I-A, “b”","number":"Art. 1º, I-A, “b”","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados:´ [...] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: [...] b) contra membro do Poder Judiciário, do Ministério Público, da Defensoria Pública ou da Advocacia Pública, de que tratam os arts. 131 e 132 da Constituição Federal, ou oficial de justiça, no exercício da função ou em decorrência dela, ou contra seu cônjuge, companheiro ou parente, inclusive por afinidade, até o terceiro grau, em razão dessa condição; ou (Redação dada pela Lei nº 15.159, de 2025)"],"origin":"real","question":{"statement":"Em março de 2026, Lucas, oficial de justiça no âmbito do Tribunal de Justiça do Estado de Santa Catarina, sofreu lesão corporal dolosa, de natureza gravíssima, enquanto exercia regularmente as suas funções. Após trabalho investigativo, a Polícia Civil, com autorização judicial, logrou êxito em prender preventivamente João, responsável pela conduta ilícita. Nesse cenário, considerando as disposições da Lei nº 8.072/1990, é correto afirmar que João não praticou crime hediondo, pois a lesão corporal dolosa gravíssima não tem previsão dentre os delitos de natureza hedionda.","answer":false,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados:´ [...] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: [...] b) contra membro do Poder Judiciário, do Ministério Público, da Defensoria Pública ou da Advocacia Pública, de que tratam os arts. 131 e 132 da Constituição Federal, ou oficial de justiça, no exercício da função ou em decorrência dela, ou contra seu cônjuge, companheiro ou parente, inclusive por afinidade, até o terceiro grau, em razão dessa condição; ou (Redação dada pela Lei nº 15.159, de 2025)","source":"52.pdf · questão 14 · Art. 1º, I-A, “b”, Lei 8.072/90","meta":"FGV 2026 - Técnico Judiciário (TJ-SC)","bank":"FGV","year":2026,"role":"Técnico Judiciário (TJ-SC)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q015","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, I-A, § único, III","number":"Art. 1º, I-A, § único, III","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: (Redação dada pela Lei nº 15.159, de 2025) [...] Parágrafo único. Consideram-se também hediondos, tentados ou consumados: [...] III - o crime de comércio ilegal de armas de fogo, previsto no art. 17 da Lei nº 10.826, de 22 de dezembro de 2003;"],"origin":"real","question":{"statement":"José, empresário, em negociação para adquirir uma linda casa localizada no litoral do Estado do Espírito Santo, buscou informações sobre os antecedentes criminais do vendedor Caio, descobrindo que este tem condenações definitivas pela prática dos seguintes delitos: i) comércio ilegal de armas de fogo; ii) lesão corporal gravíssima contra policial militar no exercício da função; e iii) corrupção ativa. Nesse cenário, considerando as disposições da Lei nº 8.072/1990, é correto afirmar que Caio foi condenado, definitivamente, pela prática dos seguintes crimes hediondos: comércio ilegal de armas de fogo e lesão corporal gravíssima contra policial militar no exercício da função, apenas;","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] I-A - lesão corporal dolosa de natureza gravíssima (art. 129, § 2º) e lesão corporal seguida de morte (art. 129, § 3º), quando praticadas: (Redação dada pela Lei nº 15.159, de 2025) [...] Parágrafo único. Consideram-se também hediondos, tentados ou consumados: [...] III - o crime de comércio ilegal de armas de fogo, previsto no art. 17 da Lei nº 10.826, de 22 de dezembro de 2003;","source":"52.pdf · questão 15 · Art. 1º, I-A, § único, III, Lei 8.072/90","meta":"FGV 2025 - Tabelião / Oficial de Registros - Provimento (TJ-ES)","bank":"FGV","year":2025,"role":"Tabelião / Oficial de Registros - Provimento (TJ-ES)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q020","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art 1º, II","number":"Art 1º, II","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: (Redação dada pela Lei nº 13.964, de 2019) [...] b) circunstanciado pelo emprego de arma de fogo (art. 157, § 2º-A, inciso I) ou pelo emprego de arma de fogo de uso proibido ou restrito (art. 157, § 2º-B); (Incluído pela Lei nº 13.964, de 2019) [...]"],"origin":"real","question":{"statement":"NÃO é considerado como crime hediondo o crime de roubo circunstanciado pelo emprego de arma de fogo.","answer":false,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: (Redação dada pela Lei nº 13.964, de 2019) [...] b) circunstanciado pelo emprego de arma de fogo (art. 157, § 2º-A, inciso I) ou pelo emprego de arma de fogo de uso proibido ou restrito (art. 157, § 2º-B); (Incluído pela Lei nº 13.964, de 2019) [...]","source":"52.pdf · questão 20 · Art 1º, II, Lei 8.072/90","meta":"FGV 2022 - Juiz de Direito (TJ-SC)","bank":"FGV","year":2022,"role":"Juiz de Direito (TJ-SC)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q025","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, II, \"a\"","number":"Art. 1º, II, \"a\"","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º - São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: a) circunstanciado pela restrição de liberdade da vítima (art. 157, § 2º, inciso V); [...]"],"origin":"real","question":{"statement":"Quanto ao crime de roubo, é correto afirmar que o roubo circunstanciado pela restrição de liberdade da vítima é considerado crime hediondo.","answer":true,"explanation":"Art. 1º - São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: a) circunstanciado pela restrição de liberdade da vítima (art. 157, § 2º, inciso V); [...]","source":"52.pdf · questão 25 · Art. 1º, II, \"a\", Lei 8.072/90","meta":"VUNESP 2025 - Juiz de Direito (TJ-SP)","bank":"VUNESP","year":2025,"role":"Juiz de Direito (TJ-SP)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q026","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, II, “b”","number":"Art. 1º, II, “b”","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: [...] b) circunstanciado pelo emprego de arma de fogo (art. 157, § 2º-A, inciso I) ou pelo emprego de arma de fogo de uso proibido ou restrito (art. 157, § 2º-B);"],"origin":"real","question":{"statement":"É considerado como crime hediondo, regulado pela Lei nº 8.072/1990: O roubo circunstanciado pelo emprego de arma de fogo.","answer":true,"explanation":"Art. 1o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] II - roubo: [...] b) circunstanciado pelo emprego de arma de fogo (art. 157, § 2º-A, inciso I) ou pelo emprego de arma de fogo de uso proibido ou restrito (art. 157, § 2º-B);","source":"52.pdf · questão 26 · Art. 1º, II, “b”, Lei 8.072/90","meta":"FUNDATEC 2022 – Analista da Polícia Penal (PP-RS)","bank":"FUNDATEC","year":2022,"role":"Analista da Polícia Penal (PP-RS)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q027","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, II, c","number":"Art. 1º, II, c","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [..] II - roubo: […] c) qualificado pelo resultado lesão corporal grave ou morte (art. 157, § 3º);"],"origin":"real","question":{"statement":"É considerado hediondo o roubo, qualificado pelo resultado lesão corporal grave, qualquer que seja a idade da vítima.","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [..] II - roubo: […] c) qualificado pelo resultado lesão corporal grave ou morte (art. 157, § 3º);","source":"52.pdf · questão 27 · Art. 1º, II, c, Lei 8.072/90","meta":"VUNESP 2025 - Analista Jurídico (MPE-SP)","bank":"VUNESP","year":2025,"role":"Analista Jurídico (MPE-SP)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q030","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, IV","number":"Art. 1º, IV","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1 o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] IV - extorsão mediante seqüestro e na forma qualificada (art. 159, caput, e §§ l o , 2 o e 3o );"],"origin":"real","question":{"statement":"A Lei dos crimes hediondos (Lei n° 8.072/90), embora não forneça o conceito de crime hediondo, apresenta um rol dos crimes que se enquadram em seus dispositivos, entre os quais se pode destacar extorsão mediante sequestro.","answer":true,"explanation":"Art. 1 o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] IV - extorsão mediante seqüestro e na forma qualificada (art. 159, caput, e §§ l o , 2 o e 3o );","source":"52.pdf · questão 30 · Art. 1º, IV, Lei 8.072/90","meta":"VUNESP 2018 - Delegado de Polícia (PC-BA)","bank":"VUNESP","year":2018,"role":"Delegado de Polícia (PC-BA)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q031","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, V","number":"Art. 1º, V","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] V - estupro (art. 213, caput e §§ 1o e 2o);"],"origin":"real","question":{"statement":"É considerado como crime hediondo, regulado pela Lei nº 8.072/1990: O estupro.","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] V - estupro (art. 213, caput e §§ 1o e 2o);","source":"52.pdf · questão 31 · Art. 1º, V, Lei 8.072/90","meta":"FUNDATEC 2022 – Analista da Polícia Penal (PP-RS)","bank":"FUNDATEC","year":2022,"role":"Analista da Polícia Penal (PP-RS)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q033","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, VI","number":"Art. 1º, VI","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VI - estupro de vulnerável (art. 217-A, caput e §§ 1o, 2o, 3o e 4o);"],"origin":"real","question":{"statement":"É considerado como crime hediondo, regulado pela Lei nº 8.072/1990: O estupro de vulnerável.","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VI - estupro de vulnerável (art. 217-A, caput e §§ 1o, 2o, 3o e 4o);","source":"52.pdf · questão 33 · Art. 1º, VI, Lei 8.072/90","meta":"FUNDATEC 2022 – Analista da Polícia Penal (PP-RS)","bank":"FUNDATEC","year":2022,"role":"Analista da Polícia Penal (PP-RS)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q040","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, VII","number":"Art. 1º, VII","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1 o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VII - epidemia com resultado morte (art. 267, § 1 o ). [...]"],"origin":"real","question":{"statement":"Nos termos da Lei de Crimes Hediondos, o crime de epidemia com resultado morte não é considerado hediondo.","answer":false,"explanation":"Art. 1 o São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VII - epidemia com resultado morte (art. 267, § 1 o ). [...]","source":"52.pdf · questão 40 · Art. 1º, VII, Lei 8.072/90","meta":"CESPE/CEBRASPE 2022 - Defensor Público (DPE-PI) - Redação Adaptada","bank":"CESPE/CEBRASPE","year":2022,"role":"Defensor Público (DPE-PI) - Redação Adaptada","origin":"real"}},{"id":"pen-lei-8072-pdf52-q043","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, VIII","number":"Art. 1º, VIII","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no DecretoLei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VIII - favorecimento da prostituição ou de outra forma de exploração sexual de criança ou adolescente ou de vulnerável (art. 218-B, caput, e §§ 1º e 2º)."],"origin":"real","question":{"statement":"São considerados hediondos, de acordo com a Lei 8.072/90 e suas alterações: favorecimento da prostituição ou de outra forma de exploração sexual de criança ou adolescente ou de vulnerável (art. 218-B, caput, e §§ 1º e 2º).","answer":true,"explanation":"Art. 1º São considerados hediondos os seguintes crimes, todos tipificados no DecretoLei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: [...] VIII - favorecimento da prostituição ou de outra forma de exploração sexual de criança ou adolescente ou de vulnerável (art. 218-B, caput, e §§ 1º e 2º).","source":"52.pdf · questão 43 · Art. 1º, VIII, Lei 8.072/90","meta":"FAPEC 2021 - Perito Papiloscopista (PC-MS)","bank":"FAPEC","year":2021,"role":"Perito Papiloscopista (PC-MS)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q047","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, IX","number":"Art. 1º, IX","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1 o - São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] IX - furto qualificado pelo emprego de explosivo ou de artefato análogo que cause perigo comum (art. 155, § 4º-A). […]"],"origin":"real","question":{"statement":"Catarina, Promotora de Justiça com atuação na Vara de Execuções Penais do Estado do Rio de Janeiro, foi instada a se manifestar sobre a progressão de regime de João, condenado de altíssima periculosidade, atualmente em cumprimento de pena pela prática de determinado crime hediondo. Em razão da inobservância dos requisitos previstos em lei, a representante do Parquet foi contrária ao pedido formulado pela defesa técnica. Nesse cenário, considerando as disposições da Lei nº 8.072/1990, é correto afirmar que João está cumprindo pena pela prática do crime de furto qualificado pelo emprego de explosivo.","answer":true,"explanation":"Art. 1 o - São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei n o 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: […] IX - furto qualificado pelo emprego de explosivo ou de artefato análogo que cause perigo comum (art. 155, § 4º-A). […]","source":"52.pdf · questão 47 · Art. 1º, IX, Lei 8.072/90","meta":"FGV 2025 - Analista do Ministério Público - Área Processual (MPE-RJ)","bank":"FGV","year":2025,"role":"Analista do Ministério Público - Área Processual (MPE-RJ)","origin":"real"}},{"id":"pen-lei-8072-pdf52-q050","discipline":"penal","topicId":"pen-lei-8072","subtopic":"Lei 8.072/1990 · Art. 1º, § único","number":"Art. 1º, § único","title":"Lei 8.072/1990 — Crimes Hediondos","parts":["Art. 1º [...] Parágrafo único. Consideram-se também hediondos, tentados ou consumados: [...] II - o crime de posse ou porte ilegal de arma de fogo de uso proibido, previsto no art. 16 da Lei nº 10.826, de 22 de dezembro de 2003; [...] Súmula 668, STJ - Não é hediondo o delito de porte ou posse de arma de fogo de uso permitido, ainda que com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado."],"origin":"real","question":{"statement":"NÃO é considerado como crime hediondo o crime de porte ilegal de arma de fogo de uso proibido.","answer":false,"explanation":"Art. 1º [...] Parágrafo único. Consideram-se também hediondos, tentados ou consumados: [...] II - o crime de posse ou porte ilegal de arma de fogo de uso proibido, previsto no art. 16 da Lei nº 10.826, de 22 de dezembro de 2003; [...] Súmula 668, STJ - Não é hediondo o delito de porte ou posse de arma de fogo de uso permitido, ainda que com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado.","source":"52.pdf · questão 50 · Art. 1º, § único, Lei 8.072/90 c/c Súm. 668, STJ","meta":"FGV 2022 - Juiz de Direito (TJSC)","bank":"FGV","year":2022,"role":"Juiz de Direito (TJSC)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q001","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Ementa da Lei 9.455/1997","number":"Ementa da Lei 9.455/1997","title":"Lei 9.455/1997 — Tortura","parts":["LEI Nº 9.455, DE 7 DE ABRIL DE 1997. Define os crimes de tortura e dá outras providências."],"origin":"real","question":{"statement":"A Lei Federal nº 9.455, de 7 de abril de 1997, define os crimes de tortura e dá outras providências.","answer":true,"explanation":"LEI Nº 9.455, DE 7 DE ABRIL DE 1997. Define os crimes de tortura e dá outras providências.","source":"63.pdf · questão 1 · Lei 9.455/97","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PC-BA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PC-BA)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q008","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º","number":"Art. 1º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: [...] c) em razão de discriminação racial ou religiosa;"],"origin":"real","question":{"statement":"Uma das hipóteses do crime de tortura consiste em constranger alguém, com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental em razão de discriminação racial ou religiosa.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: [...] c) em razão de discriminação racial ou religiosa;","source":"63.pdf · questão 8 · Art. 1º, Lei 9.455/1997","meta":"INSTITUTO CONSULPLAN 2026 - Juiz de Direito (TJ-MG)","bank":"INSTITUTO CONSULPLAN","year":2026,"role":"Juiz de Direito (TJ-MG)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q009","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, I","number":"Art. 1º, I","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: a) com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa;"],"origin":"real","question":{"statement":"Quanto à legislação a respeito do crime de tortura, é correto afirmar que pratica crime de tortura a autoridade policial que constrange alguém, mediante emprego de grave ameaça e causando-lhe sofrimento mental, com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: a) com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa;","source":"63.pdf · questão 9 · Art. 1º, I, Lei 9.455/97","meta":"CESPE 2009 - Delegado de Polícia (PC-PB)","bank":"CESPE","year":2009,"role":"Delegado de Polícia (PC-PB)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q010","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, I, a, § 2º","number":"Art. 1º, I, a, § 2º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º - Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: a) com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa; [...] § 2º - Aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las, incorre na pena de detenção de um a quatro anos."],"origin":"real","question":{"statement":"Durante operação noturna em bairro periférico, uma equipe policial composta por um superior e seu subordinado abordou um suspeito de integrar quadrilha de roubos. Conduzido à base comunitária, o subordinado, com o objetivo de obter a confissão e o endereço do cofre do grupo, passou a aplicar choques com dispositivo elétrico improvisado (taser artesanal) e cobriu parcialmente a cabeça do custodiado com uma capa, causando-lhe intenso sofrimento físico e mental. O superior permaneceu presente, assistindo aos atos por cerca de dez minutos, sem tocar no suspeito e nem ordenar tais condutas. Considerando a situação narrada, é correto afirmar que tanto o subordinado quanto seu superior praticaram o crime de tortura.","answer":true,"explanation":"Art. 1º - Constitui crime de tortura: I - constranger alguém com emprego de violência ou grave ameaça, causando-lhe sofrimento físico ou mental: a) com o fim de obter informação, declaração ou confissão da vítima ou de terceira pessoa; [...] § 2º - Aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las, incorre na pena de detenção de um a quatro anos.","source":"63.pdf · questão 10 · Art. 1º, I, a, § 2º, Lei 9.455/97","meta":"Instituto AOCP 2026 - Policial Penal (SEJUSP-MG)","bank":"Instituto AOCP","year":2026,"role":"Policial Penal (SEJUSP-MG)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q011","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, II","number":"Art. 1º, II","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: […] II - submeter alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo. Pena - reclusão, de dois a oito anos. Art. 61, CP - São circunstâncias que sempre agravam a pena, quando não constituem ou qualificam o crime: […] II - ter o agente cometido o crime: […] e) contra ascendente, descendente, irmão ou cônjuge; Na dúvida se é possível cumular, temos o aval da jurisprudência: \"A incidência da circunstância agravante do art. 61, inciso II, e, do Código Penal no crime de tortura, previsto no art. 1°, inciso II, da Lei n. 9.455/1997 [tortura-castigo], não configura bis in idem\" (STJ. Informativo 799)."],"origin":"real","question":{"statement":"Tendo em conta as situações hipotéticas e considerando a jurisprudência dos Tribunais Superiores, julgue o item a seguir. Tícia, por submeter a filha a intenso sofrimento físico como forma de castigo, incide no crime de tortura-castigo, previsto no artigo 1, do inciso II, da Lei n° 9.455/97, agravado pela circunstância de ter sido praticado em detrimento de descendente.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: […] II - submeter alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo. Pena - reclusão, de dois a oito anos. Art. 61, CP - São circunstâncias que sempre agravam a pena, quando não constituem ou qualificam o crime: […] II - ter o agente cometido o crime: […] e) contra ascendente, descendente, irmão ou cônjuge; Na dúvida se é possível cumular, temos o aval da jurisprudência: \"A incidência da circunstância agravante do art. 61, inciso II, e, do Código Penal no crime de tortura, previsto no art. 1°, inciso II, da Lei n. 9.455/1997 [tortura-castigo], não configura bis in idem\" (STJ. Informativo 799).","source":"63.pdf · questão 11 · Art. 1º, II, Lei 9.455/97","meta":"VUNESP 2025 - Juiz de Direito (TJ-RJ)","bank":"VUNESP","year":2025,"role":"Juiz de Direito (TJ-RJ)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q015","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, III","number":"Art. 1º, III","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: […] III – submeter mulher, reiteradamente, a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar, sem prejuízo da aplicação das penas correspondentes a outras infrações penais. (Incluído pela Lei nº 15.410, de 2026)"],"origin":"authorial","question":{"statement":"De acordo com a Lei de Tortura, de nº 9.455 de 1997, constitui crime de tortura submeter mulher, reiteradamente, a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar, sem prejuízo da aplicação das penas correspondentes a outras infrações penais.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: […] III – submeter mulher, reiteradamente, a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar, sem prejuízo da aplicação das penas correspondentes a outras infrações penais. (Incluído pela Lei nº 15.410, de 2026)","source":"63.pdf · questão 15 · Art. 1º, III, Lei 9.455/97","meta":"Exercício importado · Lei 9.455/1997","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-9455-pdf63-q016","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 2º","number":"Art. 1º, § 2º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: [...] § 2º Aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las, incorre na pena de detenção de um a quatro anos."],"origin":"real","question":{"statement":"Com base na Lei nº 9.455/1997, que define os crimes de tortura, julgue o item. Aquele que se omite em face das condutas descritas na lei de tortura, quando tinha o dever de evitá-las ou apurá-las incorre em crime.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: [...] § 2º Aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las, incorre na pena de detenção de um a quatro anos.","source":"63.pdf · questão 16 · Art. 1º, § 2º, Lei 9.455/97","meta":"FUNDATEC 2022 – Policial Penal (PP-RS)","bank":"FUNDATEC","year":2022,"role":"Policial Penal (PP-RS)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q019","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 3º","number":"Art. 1º, § 3º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º, § 3º Se resulta lesão corporal de natureza grave ou gravíssima, a pena é de reclusão de quatro a dez anos; se resulta morte, a reclusão é de oito a dezesseis anos."],"origin":"real","question":{"statement":"Se no crime de tortura o resultado é a lesão corporal de natureza grave ou gravíssima, a pena é de reclusão de seis a doze anos; se resulta morte, a reclusão é de oito a dezesseis anos.","answer":false,"explanation":"Art. 1º, § 3º Se resulta lesão corporal de natureza grave ou gravíssima, a pena é de reclusão de quatro a dez anos; se resulta morte, a reclusão é de oito a dezesseis anos.","source":"63.pdf · questão 19 · Art. 1º, § 3º, Lei 9.455/97","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PCBA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PCBA)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q029","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 4º","number":"Art. 1º, § 4º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º, § 4º Aumenta-se a pena de um sexto até um terço: I - se o crime é cometido por agente público; II – se o crime é cometido contra criança, gestante, portador de deficiência, adolescente ou maior de 60 (sessenta) anos; '(Redação dada pela Lei nº 10.741, de 2003) III - se o crime é cometido mediante seqüestro."],"origin":"real","question":{"statement":"A pena para o crime de tortura é aumentada de um sexto a um terço, se o crime é cometido por agente público ou se é cometido contra criança, gestante, portador de deficiência, adolescente ou mais de sessenta anos, ou ainda, se o crime é cometido mediante sequestro.","answer":true,"explanation":"Art. 1º, § 4º Aumenta-se a pena de um sexto até um terço: I - se o crime é cometido por agente público; II – se o crime é cometido contra criança, gestante, portador de deficiência, adolescente ou maior de 60 (sessenta) anos; '(Redação dada pela Lei nº 10.741, de 2003) III - se o crime é cometido mediante seqüestro.","source":"63.pdf · questão 29 · Art. 1º, § 4º, Lei 9.455/97","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PCBA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PCBA)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q031","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 4º, II","number":"Art. 1º, § 4º, II","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º. [...] § 4º Aumenta-se a pena de um sexto até um terço: [...] II - se o crime é cometido contra criança, gestante, portador de deficiência, adolescente ou maior de 60 (sessenta) anos;"],"origin":"real","question":{"statement":"Uma das hipóteses de aumento da pena no crime de tortura ocorre se o delito é cometido contra gestante ou maior de 65 anos.","answer":false,"explanation":"Art. 1º. [...] § 4º Aumenta-se a pena de um sexto até um terço: [...] II - se o crime é cometido contra criança, gestante, portador de deficiência, adolescente ou maior de 60 (sessenta) anos;","source":"63.pdf · questão 31 · Art. 1º, § 4º, II, Lei 9.455/1997","meta":"INSTITUTO CONSULPLAN 2026 - Juiz de Direito (TJ-MG)","bank":"INSTITUTO CONSULPLAN","year":2026,"role":"Juiz de Direito (TJ-MG)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q033","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 5º","number":"Art. 1º, § 5º","title":"Lei 9.455/1997 — Tortura","parts":["Art.1º, § 5º - A condenação acarretará a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada."],"origin":"real","question":{"statement":"Julgue o item a seguir. A condenação por delito previsto na Lei de Tortura acarreta, como efeito extrapenal automático da sentença condenatória, a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.","answer":true,"explanation":"Art.1º, § 5º - A condenação acarretará a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.","source":"63.pdf · questão 33 · Art. 1º, § 5º, Lei 9.455/97","meta":"FAPEC 2024 - Promotor de Justiça Substituto (MPEMS)","bank":"FAPEC","year":2024,"role":"Promotor de Justiça Substituto (MPEMS)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q045","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 6º","number":"Art. 1º, § 6º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º Constitui crime de tortura: [...] § 6º O crime de tortura é inafiançável e insuscetível de graça ou anistia."],"origin":"real","question":{"statement":"Com base na Lei nº 9.455/1997, que define os crimes de tortura, julgue o item. O crime de tortura é inafiançável.","answer":true,"explanation":"Art. 1º Constitui crime de tortura: [...] § 6º O crime de tortura é inafiançável e insuscetível de graça ou anistia.","source":"63.pdf · questão 45 · Art. 1º, § 6º, Lei 9.455/97","meta":"FUNDATEC 2022 – Policial Penal (PP-RS)","bank":"FUNDATEC","year":2022,"role":"Policial Penal (PP-RS)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q047","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 1º, § 7º","number":"Art. 1º, § 7º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 1º […] § 7º O condenado por crime previsto nesta Lei, salvo a hipótese do § 2º, iniciará o cumprimento da pena em regime fechado. Complementando: RECURSO ORDINÁRIO EM HABEAS CORPUS. CRIME DE TORTURA. REGIME INICIAL FECHADO FIXADO EXCLUSIVAMENTE COM BASE NO ART. 1º, § 7º, DA LEI 9.455/97. INCONSTITUCIONALIDADE DECLARADA. RECONHECIMENTO DA ILEGALIDADE PELO TRIBUNAL DE ORIGEM. ALTERAÇÃO DO REGIME PARA O SEMIABERTO, COM FULCRO NO ART. 33 E PARÁGRAFOS DO CÓDIGO PENAL. REFORMATIO IN PEJUS. AUSÊNCIA. REPRIMENDA FINAL INFERIOR A 4 ANOS DE RECLUSÃO. REGIME INICIAL SEMIABERTO. CIRCUNSTÂNCIA JUDICIAL. AUSÊNCIA DE CONSTRANGIMENTO ILEGAL. RECURSO A QUE SE NEGA PROVIMENTO. 1. A obrigatoriedade do regime inicial fechado prevista na Lei do Crime de Tortura foi superada pela Suprema Corte, de modo que a mera natureza do crime não configura fundamentação idônea a justificar a fixação do regime mais gravoso para os condenados pela prática de crimes hediondos e equiparados. Para estabelecer o regime prisional, deve o magistrado avaliar o caso concreto, seguindo os parâmetros estabelecidos pelo artigo 33 e parágrafos do Código Penal. 2. O regime inicial fechado foi fixado pelo Magistrado de primeiro grau com base, exclusivamente, no disposto pelo art. 1°, § 7°, da Lei n° 9.455/97, em manifesta contrariedade ao hodierno entendimento dos Tribunais Superiores. A Corte de origem, por sua vez, ao reconhecer a existência de flagrante ilegalidade na imposição do regime inicial fechado - diante da mera alusão ao § 7° do art. 1° da Lei n° 9.455/97 -, alterou o regime inicial para o semiaberto à luz do art. 33, §§ 2º e 3º, do Código Penal, o que não evidencia reformatio in pejus. 3. Nos termos do artigo 33 e 59 do Código Penal, fixada a pena em patamar inferior a 4 anos de reclusão, a estipulação do regime inicial semiaberto é apropriada, eis que existe circunstância judicial desfavorável, tanto que a pena-base foi fixada acima do mínimo legal. 4. Recurso ordinário em habeas corpus a que se nega provimento. (RHC 76.642/RN, Rel. Ministra MARIA THEREZA DE ASSIS MOURA, SEXTA TURMA, julgado em 11/10/2016, DJe 28/10/2016)"],"origin":"real","question":{"statement":"Com base na Lei nº 9.455/1997, que define os crimes de tortura, é correto afirmar que o condenado por crime previsto na lei de tortura iniciará o cumprimento da pena em regime fechado.","answer":true,"explanation":"Art. 1º […] § 7º O condenado por crime previsto nesta Lei, salvo a hipótese do § 2º, iniciará o cumprimento da pena em regime fechado. Complementando: RECURSO ORDINÁRIO EM HABEAS CORPUS. CRIME DE TORTURA. REGIME INICIAL FECHADO FIXADO EXCLUSIVAMENTE COM BASE NO ART. 1º, § 7º, DA LEI 9.455/97. INCONSTITUCIONALIDADE DECLARADA. RECONHECIMENTO DA ILEGALIDADE PELO TRIBUNAL DE ORIGEM. ALTERAÇÃO DO REGIME PARA O SEMIABERTO, COM FULCRO NO ART. 33 E PARÁGRAFOS DO CÓDIGO PENAL. REFORMATIO IN PEJUS. AUSÊNCIA. REPRIMENDA FINAL INFERIOR A 4 ANOS DE RECLUSÃO. REGIME INICIAL SEMIABERTO. CIRCUNSTÂNCIA JUDICIAL. AUSÊNCIA DE CONSTRANGIMENTO ILEGAL. RECURSO A QUE SE NEGA PROVIMENTO. 1. A obrigatoriedade do regime inicial fechado prevista na Lei do Crime de Tortura foi superada pela Suprema Corte, de modo que a mera natureza do crime não configura fundamentação idônea a justificar a fixação do regime mais gravoso para os condenados pela prática de crimes hediondos e equiparados. Para estabelecer o regime prisional, deve o magistrado avaliar o caso concreto, seguindo os parâmetros estabelecidos pelo artigo 33 e parágrafos do Código Penal. 2. O regime inicial fechado foi fixado pelo Magistrado de primeiro grau com base, exclusivamente, no disposto pelo art. 1°, § 7°, da Lei n° 9.455/97, em manifesta contrariedade ao hodierno entendimento dos Tribunais Superiores. A Corte de origem, por sua vez, ao reconhecer a existência de flagrante ilegalidade na imposição do regime inicial fechado - diante da mera alusão ao § 7° do art. 1° da Lei n° 9.455/97 -, alterou o regime inicial para o semiaberto à luz do art. 33, §§ 2º e 3º, do Código Penal, o que não evidencia reformatio in pejus. 3. Nos termos do artigo 33 e 59 do Código Penal, fixada a pena em patamar inferior a 4 anos de reclusão, a estipulação do regime inicial semiaberto é apropriada, eis que existe circunstância judicial desfavorável, tanto que a pena-base foi fixada acima do mínimo legal. 4. Recurso ordinário em habeas corpus a que se nega provimento. (RHC 76.642/RN, Rel. Ministra MARIA THEREZA DE ASSIS MOURA, SEXTA TURMA, julgado em 11/10/2016, DJe 28/10/2016)","source":"63.pdf · questão 47 · Art. 1º, § 7º, Lei 9.455/97","meta":"FUNDATEC 2022 - Agente Penitenciário (SUSEPE-RS)","bank":"FUNDATEC","year":2022,"role":"Agente Penitenciário (SUSEPE-RS)","origin":"real"}},{"id":"pen-lei-9455-pdf63-q049","discipline":"penal","topicId":"pen-lei-9455","subtopic":"Lei 9.455/1997 · Art. 2º","number":"Art. 2º","title":"Lei 9.455/1997 — Tortura","parts":["Art. 2º O disposto nesta Lei aplica-se ainda quando o crime não tenha sido cometido em território nacional, sendo a vítima brasileira ou encontrando-se o agente em local sob jurisdição brasileira."],"origin":"real","question":{"statement":"A Lei de Tortura aplica-se ainda quando o crime não tenha sido cometido em território nacional, sendo a vítima brasileira ou encontrando-se o agente em local sob jurisdição brasileira.","answer":true,"explanation":"Art. 2º O disposto nesta Lei aplica-se ainda quando o crime não tenha sido cometido em território nacional, sendo a vítima brasileira ou encontrando-se o agente em local sob jurisdição brasileira.","source":"63.pdf · questão 49 · Art. 2º, Lei 9.455/1997","meta":"INSTITUTO CONSULPLAN 2026 - Juiz de Direito (TJ-MG)","bank":"INSTITUTO CONSULPLAN","year":2026,"role":"Juiz de Direito (TJ-MG)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q001","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Ementa da Lei 7.716/1989","number":"Ementa da Lei 7.716/1989","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["LEI Nº 7.716, DE 5 DE JANEIRO DE 1989. Mensagem de veto Vide Lei nº 12.735, de 2012 Define os crimes resultantes de preconceito de raça ou de cor. Texto compilado (Vide ADO Nº 26)"],"origin":"real","question":{"statement":"A Lei Federal nº 7.716, de 5 de janeiro de 1989, define os crimes resultantes de preconceito de raça ou de cor.","answer":true,"explanation":"LEI Nº 7.716, DE 5 DE JANEIRO DE 1989. Mensagem de veto Vide Lei nº 12.735, de 2012 Define os crimes resultantes de preconceito de raça ou de cor. Texto compilado (Vide ADO Nº 26)","source":"48.pdf · questão 1 · Lei 7.716/1989","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PC-BA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PC-BA)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q002","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 1º","number":"Art. 1º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 1º - Serão punidos, na forma desta Lei, os crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional."],"origin":"real","question":{"statement":"A Lei n.º 7.716/1989, conhecida popularmente como Lei de Combate ao Racismo, prevê punição para as atitudes discriminatórias ou preconceituosas relacionadas a aspectos como religião e procedência nacional.","answer":true,"explanation":"Art. 1º - Serão punidos, na forma desta Lei, os crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional.","source":"48.pdf · questão 2 · Art. 1º, Lei 7.716/89","meta":"CESPE/CEBRASPE 2025 - Delegado de Polícia (PC-CE)","bank":"CESPE/CEBRASPE","year":2025,"role":"Delegado de Polícia (PC-CE)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q006","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 2º-A","number":"Art. 2º-A","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 2º-A Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. (Incluído pela Lei nº 14.532, de 2023) Pena: reclusão, de 2 (dois) a 5 (cinco) anos, e multa. (Incluído pela Lei nº 14.532, de 2023)"],"origin":"authorial","question":{"statement":"Quem injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional, estará sujeito à pena de reclusão, de 3 (três) a 8 (oito) anos, ou multa.","answer":false,"explanation":"Art. 2º-A Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. (Incluído pela Lei nº 14.532, de 2023) Pena: reclusão, de 2 (dois) a 5 (cinco) anos, e multa. (Incluído pela Lei nº 14.532, de 2023)","source":"48.pdf · questão 6 · Art. 2º-A, Lei 7.716/89","meta":"Exercício importado · Lei 7.716/1989","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-7716-pdf48-q009","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 2º-A, § único","number":"Art. 2º-A, § único","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 2º-A Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. Pena: reclusão, de 2 (dois) a 5 (cinco) anos, e multa. Parágrafo único. A pena é aumentada de metade se o crime for cometido mediante concurso de 2 (duas) ou mais pessoas."],"origin":"real","question":{"statement":"Suponha que Tício e Caio, funcionários de um restaurante, durante uma discussão com Mévio, cliente do estabelecimento, e sem qualquer contexto de brincadeira, recreação ou descontração, passaram a ofendê-lo. Agindo em conjunto e com o objetivo de discriminar Mévio, injuriaram-no, ofendendo-lhe a dignidade em razão de sua procedência nacional. Nessa situação, considerando apenas as informações fornecidas, de acordo com a Lei nº 7.716/1989, Tício e Caio serão punidos por crime resultante de discriminação em razão de procedência nacional, cuja pena prevista é a de reclusão, de dois a cinco anos, e multa, sendo que, no caso apresentado, a pena será aumentada de metade.","answer":true,"explanation":"Art. 2º-A Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. Pena: reclusão, de 2 (dois) a 5 (cinco) anos, e multa. Parágrafo único. A pena é aumentada de metade se o crime for cometido mediante concurso de 2 (duas) ou mais pessoas.","source":"48.pdf · questão 9 · Art. 2º-A, § único, Lei 7.716/89","meta":"FCC 2026 - Auditor Fiscal da Receita Estadual - Gestão Fazendária (SEFAZ-CE)","bank":"FCC","year":2026,"role":"Auditor Fiscal da Receita Estadual - Gestão Fazendária (SEFAZ-CE)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q011","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 3º","number":"Art. 3º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 3º Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos. Pena: reclusão de dois a cinco anos."],"origin":"real","question":{"statement":"Segundo a Lei nº 7.716/1989, é crime resultante de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional, impedir o acesso de pessoa habilitada, a qualquer cargo da administração pública, bem como das concessionárias de serviços públicos.","answer":true,"explanation":"Art. 3º Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos. Pena: reclusão de dois a cinco anos.","source":"48.pdf · questão 11 · Art. 3º, Lei 7.716/89","meta":"CS-UFG 2018 - Guarda Civil (Prefeitura de Jataí - GO)","bank":"CS-UFG","year":2018,"role":"Guarda Civil (Prefeitura de Jataí - GO)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q014","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 3º, § único","number":"Art. 3º, § único","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 3º Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos. Pena: reclusão de dois a cinco anos. Parágrafo único. Incorre na mesma pena quem, por motivo de discriminação de raça, cor, etnia, religião ou procedência nacional, obstar a promoção funcional."],"origin":"real","question":{"statement":"De acordo com a Lei n.º 7.716/1989, aquele que, em razão de raça, cor, etnia, religião ou procedência nacional, impedir o acesso de alguém, devidamente habilitado, a qualquer cargo da administração direta, incorre na mesma pena de quem, por motivo de discriminação de raça, cor, etnia, religião ou procedência nacional, obstar a promoção funcional.","answer":true,"explanation":"Art. 3º Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos. Pena: reclusão de dois a cinco anos. Parágrafo único. Incorre na mesma pena quem, por motivo de discriminação de raça, cor, etnia, religião ou procedência nacional, obstar a promoção funcional.","source":"48.pdf · questão 14 · Art. 3º, parágrafo único, Lei 7.716/89","meta":"CESPE/CEBRASPE 2023 - Procurador do Estado do Pará (PGE-PA)","bank":"CESPE/CEBRASPE","year":2023,"role":"Procurador do Estado do Pará (PGE-PA)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q015","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 4º","number":"Art. 4º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 4º Negar ou obstar emprego em empresa privada. Pena: reclusão de dois a cinco anos."],"origin":"real","question":{"statement":"Constitui crime resultante de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional negar ou obstar emprego em empresa privada.","answer":true,"explanation":"Art. 4º Negar ou obstar emprego em empresa privada. Pena: reclusão de dois a cinco anos.","source":"48.pdf · questão 15 · Art. 4º, Lei 7.716/89","meta":"AOCP 2018 - Analista Universitário - Administração (UEFS) - Adaptada","bank":"AOCP","year":2018,"role":"Analista Universitário - Administração (UEFS) - Adaptada","origin":"real"}},{"id":"pen-lei-7716-pdf48-q019","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 4º, § 2º","number":"Art. 4º, § 2º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 4º Negar ou obstar emprego em empresa privada. Pena: reclusão de dois a cinco anos. […] § 2º Ficará sujeito às penas de multa e de prestação de serviços à comunidade, incluindo atividades de promoção da igualdade racial, quem, em anúncios ou qualquer outra forma de recrutamento de trabalhadores, exigir aspectos de aparência próprios de raça ou etnia para emprego cujas atividades não justifiquem essas exigências."],"origin":"real","question":{"statement":"A Lei nº 7.716/89 define os crimes resultantes de discriminação racial. Com base nessa legislação e nas alterações posteriores, é correto afirmar que o agente que, em anúncios para recrutamento de trabalhadores, exigir aspectos de aparência próprios de raça ou etnia para emprego cujas atividades não justifiquem essas exigências, caberá exclusivamente a aplicação das penas de multa e de prestação de serviços comunitários.","answer":true,"explanation":"Art. 4º Negar ou obstar emprego em empresa privada. Pena: reclusão de dois a cinco anos. […] § 2º Ficará sujeito às penas de multa e de prestação de serviços à comunidade, incluindo atividades de promoção da igualdade racial, quem, em anúncios ou qualquer outra forma de recrutamento de trabalhadores, exigir aspectos de aparência próprios de raça ou etnia para emprego cujas atividades não justifiquem essas exigências.","source":"48.pdf · questão 19 · Art. 4º, § 2º, Lei 7.716/89","meta":"VUNESP 2023 - Promotor de Justiça Substituto (MPESP)","bank":"VUNESP","year":2023,"role":"Promotor de Justiça Substituto (MPESP)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q021","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 5º","number":"Art. 5º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 5º - Recusar ou impedir acesso a estabelecimento comercial, negando-se a servir, atender ou receber cliente ou comprador. Pena: reclusão de um a três anos."],"origin":"real","question":{"statement":"Julgue o item a seguir. A retirada compulsória de visitante de estabelecimento de entretenimento por motivo de raça é mera contravenção penal, pois a exclusão forçada não se confunde com a negação de acesso, que constitui núcleo exclusivo do tipo previsto na Lei nº 7.716/1989.","answer":false,"explanation":"Art. 5º - Recusar ou impedir acesso a estabelecimento comercial, negando-se a servir, atender ou receber cliente ou comprador. Pena: reclusão de um a três anos.","source":"48.pdf · questão 21 · Art. 5º, Lei 7.716/89","meta":"MPDFT 2025 - Promotor de Justiça (MP-DFT)","bank":"MPDFT","year":2025,"role":"Promotor de Justiça (MP-DFT)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q025","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 6º","number":"Art. 6º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 6º - Recusar, negar ou impedir a inscrição ou ingresso de aluno em estabelecimento de ensino público ou privado de qualquer grau."],"origin":"real","question":{"statement":"Julgue o item a seguir. O impedimento de matrícula em estabelecimento educacional por motivo de raça ou etnia configura discriminação administrativa sem caráter penal, pois a Lei nº 7.716/1989 pune exclusivamente atos de acesso a serviços comerciais e profissionais, não alcançando instituições de ensino.","answer":false,"explanation":"Art. 6º - Recusar, negar ou impedir a inscrição ou ingresso de aluno em estabelecimento de ensino público ou privado de qualquer grau.","source":"48.pdf · questão 25 · Art. 6º, Lei 7.716/89","meta":"MPDFT 2025 - Promotor de Justiça (MP-DFT)","bank":"MPDFT","year":2025,"role":"Promotor de Justiça (MP-DFT)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q026","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 7º","number":"Art. 7º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 7º Impedir o acesso ou recusar hospedagem em hotel, pensão, estalagem, ou qualquer estabelecimento similar. Pena: reclusão de três a cinco anos."],"origin":"real","question":{"statement":"Constitui crime resultante de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional impedir o acesso ou recusar hospedagem em hotel, pensão, estalagem, ou qualquer estabelecimento similar.","answer":true,"explanation":"Art. 7º Impedir o acesso ou recusar hospedagem em hotel, pensão, estalagem, ou qualquer estabelecimento similar. Pena: reclusão de três a cinco anos.","source":"48.pdf · questão 26 · Art. 7º, Lei 7.716/89","meta":"AOCP 2018 - Analista Universitário - Administração (UEFS) - Adaptada","bank":"AOCP","year":2018,"role":"Analista Universitário - Administração (UEFS) - Adaptada","origin":"real"}},{"id":"pen-lei-7716-pdf48-q028","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 8º","number":"Art. 8º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 8º Impedir o acesso ou recusar atendimento em restaurantes, bares, confeitarias, ou locais semelhantes abertos ao público. Pena: reclusão de um a três anos."],"origin":"real","question":{"statement":"Trata-se de crime de preconceito de raça ou de cor previsto na Lei nº 7.716/1989 impedir o acesso ou recusar atendimento em restaurantes, bares, confeitarias, ou locais semelhantes abertos ao público, em razão de raça, cor ou etnia.","answer":true,"explanation":"Art. 8º Impedir o acesso ou recusar atendimento em restaurantes, bares, confeitarias, ou locais semelhantes abertos ao público. Pena: reclusão de um a três anos.","source":"48.pdf · questão 28 · Art. 8º, Lei 7.716/89","meta":"INSTITUTO AOCP 2018 - Técnico Judiciário - Segurança (TRT - 1ª Região)","bank":"INSTITUTO AOCP","year":2018,"role":"Técnico Judiciário - Segurança (TRT - 1ª Região)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q029","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 14","number":"Art. 14","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 14. Impedir ou obstar, por qualquer meio ou forma, o casamento ou convivência familiar e social. Pena: reclusão de dois a quatro anos."],"origin":"real","question":{"statement":"Configura crime de preconceito de raça ou cor impedir a convivência familiar.","answer":true,"explanation":"Art. 14. Impedir ou obstar, por qualquer meio ou forma, o casamento ou convivência familiar e social. Pena: reclusão de dois a quatro anos.","source":"48.pdf · questão 29 · Art. 14, Lei 7.716/89","meta":"FCC 2017 - Juiz Substituto (TJ-SC)","bank":"FCC","year":2017,"role":"Juiz Substituto (TJ-SC)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q030","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 16","number":"Art. 16","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 16. Constitui efeito da condenação a perda do cargo ou função pública, para o servidor público, e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses."],"origin":"real","question":{"statement":"A Lei n. 7.716, de 05 de janeiro de 1989, é conhecida por definir os crimes resultantes de preconceitos de raça ou de cor. Nesse contexto, as penas impostas por essa lei alcançam somente os agentes privados, pois o agente público está sujeito a outro ordenamento jurídico específico, que caracteriza o abuso de poder.","answer":false,"explanation":"Art. 16. Constitui efeito da condenação a perda do cargo ou função pública, para o servidor público, e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses.","source":"48.pdf · questão 30 · Art. 16, Lei 7.716/89","meta":"UFGD 2014 - Guarda Municipal (Prefeitura de Senador Canedo - GO)","bank":"UFGD","year":2014,"role":"Guarda Municipal (Prefeitura de Senador Canedo - GO)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q037","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 20","number":"Art. 20","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 20. Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. Pena: reclusão de um a três anos e multa."],"origin":"real","question":{"statement":"Configura crime de preconceito de raça ou cor incitar a discriminação por procedência nacional.","answer":true,"explanation":"Art. 20. Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. Pena: reclusão de um a três anos e multa.","source":"48.pdf · questão 37 · Art. 20, Lei 7.716/89","meta":"FCC 2017 - Juiz Substituto (TJ-SC)","bank":"FCC","year":2017,"role":"Juiz Substituto (TJ-SC)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q043","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 20-C","number":"Art. 20-C","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 20-C - Na interpretação desta Lei, o juiz deve considerar como discriminatória qualquer atitude ou tratamento dado à pessoa ou a grupos minoritários que cause constrangimento, humilhação, vergonha, medo ou exposição indevida, e que usualmente não se dispensaria a outros grupos em razão da cor, etnia, religião ou procedência."],"origin":"real","question":{"statement":"O crime de injúria racial, que, até a promulgação da Lei no 14.532/2023, estava inscrito no artigo 140, § 3°, do Código Penal, foi inserido no artigo 2° - A da Lei no 7.716/1989, descrevendo a conduta nos seguintes termos: “Injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional”. Levando em consideração o exposto no enunciado, bem como as disposições contidas na Lei n° 7.716/1989, com as demais alterações trazidas pela Lei n° 14.532/2023, julgue o item a seguir. Nos termos do que passou a dispor a Lei n°7.716/1989, o juiz deve, na sua interpretação, considerar como discriminatória qualquer atitude ou tratamento dado à pessoa ou a grupos minoritários que cause constrangimento, humilhação, vergonha, medo ou exposição indevida, e que usualmente não se dispensaria a outros grupos em razão da cor, etnia, religião ou procedência.","answer":true,"explanation":"Art. 20-C - Na interpretação desta Lei, o juiz deve considerar como discriminatória qualquer atitude ou tratamento dado à pessoa ou a grupos minoritários que cause constrangimento, humilhação, vergonha, medo ou exposição indevida, e que usualmente não se dispensaria a outros grupos em razão da cor, etnia, religião ou procedência.","source":"48.pdf · questão 43 · Art. 20-C, Lei 7.716/89","meta":"MPE-SP 2025 - Promotor de Justiça","bank":"MPE-SP","year":2025,"role":"Promotor de Justiça","origin":"real"}},{"id":"pen-lei-7716-pdf48-q044","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 20, § 1º","number":"Art. 20, § 1º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 20. Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. (Redação dada pela Lei nº 9.459, de 15/05/97) Pena: reclusão de um a três anos e multa.(Redação dada pela Lei nº 9.459, de 15/05/97) § 1º Fabricar, comercializar, distribuir ou veicular símbolos, emblemas, ornamentos, distintivos ou propaganda que utilizem a cruz suástica ou gamada, para fins de divulgação do nazismo. Pena: reclusão de dois a cinco anos e multa."],"origin":"real","question":{"statement":"À luz da Lei no 7.716/1989 (Lei de Preconceito de Raça ou de Cor), bem como da legislação e da jurisprudência constitucional aplicáveis, julgue o item a seguir. A Lei no 7.716/1989 criminaliza, de forma específica, a divulgação do nazismo, abrangendo a fabricação, comercialização, distribuição ou veiculação de símbolos, emblemas, ornamentos ou propaganda com esse conteúdo ideológico.","answer":true,"explanation":"Art. 20. Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. (Redação dada pela Lei nº 9.459, de 15/05/97) Pena: reclusão de um a três anos e multa.(Redação dada pela Lei nº 9.459, de 15/05/97) § 1º Fabricar, comercializar, distribuir ou veicular símbolos, emblemas, ornamentos, distintivos ou propaganda que utilizem a cruz suástica ou gamada, para fins de divulgação do nazismo. Pena: reclusão de dois a cinco anos e multa.","source":"48.pdf · questão 44 · Art. 20, § 1º, Lei 7.716/89","meta":"VUNESP 2026 - Juiz de Direito (TJ-RJ)","bank":"VUNESP","year":2026,"role":"Juiz de Direito (TJ-RJ)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q045","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 20-A","number":"Art. 20-A","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 20-A. Os crimes previstos nesta Lei terão as penas aumentadas de 1/3 (um terço) até a metade, quando ocorrerem em contexto ou com intuito de descontração, diversão ou recreação."],"origin":"real","question":{"statement":"À luz da Lei no 7.716/1989 (Lei de Preconceito de Raça ou de Cor), bem como da legislação e da jurisprudência constitucional aplicáveis, julgue o item a seguir. As condutas tipificadas na Lei nº 7.716/1989 tornam-se penalmente irrelevantes quando praticadas em contexto de humor, recreação ou descontração, desde que ausente animus discriminandi explícito.","answer":false,"explanation":"Art. 20-A. Os crimes previstos nesta Lei terão as penas aumentadas de 1/3 (um terço) até a metade, quando ocorrerem em contexto ou com intuito de descontração, diversão ou recreação.","source":"48.pdf · questão 45 · Art. 20-A, Lei 7.716/89","meta":"VUNESP 2026 - Juiz de Direito (TJ-RJ)","bank":"VUNESP","year":2026,"role":"Juiz de Direito (TJ-RJ)","origin":"real"}},{"id":"pen-lei-7716-pdf48-q046","discipline":"penal","topicId":"pen-lei-7716","subtopic":"Lei 7.716/1989 · Art. 20, § 2º","number":"Art. 20, § 2º","title":"Lei 7.716/1989 — Crimes de Racismo","parts":["Art. 20 - Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. Pena: reclusão de um a três anos e multa. § 2º - Se qualquer dos crimes previstos neste artigo for cometido por intermédio dos meios de comunicação social, de publicação em redes sociais, da rede mundial de computadores ou de publicação de qualquer natureza: Pena: reclusão de dois a cinco anos e multa."],"origin":"real","question":{"statement":"Em relação aos crimes raciais e de preconceito previstos na Lei nº 7.716/1989, com as alterações promovidas pela Lei nº 14.532/2023, julgue a assertiva abaixo. O crime de racismo pode ser praticado mediante condutas de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional, incluindo-se expressamente a discriminação praticada por meio da internet ou redes sociais.","answer":true,"explanation":"Art. 20 - Praticar, induzir ou incitar a discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional. Pena: reclusão de um a três anos e multa. § 2º - Se qualquer dos crimes previstos neste artigo for cometido por intermédio dos meios de comunicação social, de publicação em redes sociais, da rede mundial de computadores ou de publicação de qualquer natureza: Pena: reclusão de dois a cinco anos e multa.","source":"48.pdf · questão 46 · Art. 20, § 2º, Lei 7.716/89","meta":"FUNDATEC 2025 - Delegado de Polícia (PC-RS)","bank":"FUNDATEC","year":2025,"role":"Delegado de Polícia (PC-RS)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q001","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 2º","number":"Art. 2º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 2º Quem, de qualquer forma, concorre para a prática dos crimes previstos nesta Lei, incide nas penas a estes cominadas, na medida da sua culpabilidade, bem como o diretor, o administrador, o membro de conselho e de órgão técnico, o auditor, o gerente, o preposto ou mandatário de pessoa jurídica, que, sabendo da conduta criminosa de outrem, deixar de impedir a sua prática, quando podia agir para evitá-la."],"origin":"real","question":{"statement":"A Lei nº 9.605, de 12 de fevereiro de 1998, dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente. À luz de suas disposições, julgue o item. Incorre nas mesmas penas quem, de qualquer forma, tendo conhecimento da prática criminosa de outrem, deixa de impedir o delito quando podia agir para evitá-lo.","answer":true,"explanation":"Art. 2º Quem, de qualquer forma, concorre para a prática dos crimes previstos nesta Lei, incide nas penas a estes cominadas, na medida da sua culpabilidade, bem como o diretor, o administrador, o membro de conselho e de órgão técnico, o auditor, o gerente, o preposto ou mandatário de pessoa jurídica, que, sabendo da conduta criminosa de outrem, deixar de impedir a sua prática, quando podia agir para evitá-la.","source":"65.pdf · questão 1 · Art. 2º, Lei 9.605/98","meta":"FGV 2026 - Especialista em Desenvolvimento de Tecnologia Nuclear e Defesa (AMAZUL)","bank":"FGV","year":2026,"role":"Especialista em Desenvolvimento de Tecnologia Nuclear e Defesa (AMAZUL)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q004","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 3º","number":"Art. 3º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 3º As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade."],"origin":"real","question":{"statement":"De acordo com a Lei nº 9.605/1998, a responsabilidade penal ambiental aplica-se às pessoas jurídicas, quando houver benefício para a entidade.","answer":true,"explanation":"Art. 3º As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade.","source":"65.pdf · questão 4 · Art. 3º, Lei 9.605/98","meta":"FUNDATEC 2026 - Guarda Municipal (Prefeitura de Gravataí - RS)","bank":"FUNDATEC","year":2026,"role":"Guarda Municipal (Prefeitura de Gravataí - RS)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q016","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 3º, § único","number":"Art. 3º, § único","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 3º As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade. Parágrafo único. A responsabilidade das pessoas jurídicas não exclui a das pessoas físicas, autoras, co-autoras ou partícipes do mesmo fato."],"origin":"real","question":{"statement":"No que tange aos crimes contra a fauna e às disposições gerais da Lei de Crimes Ambientais (Lei Federal nº 9.605/1998) e suas alterações posteriores, as pessoas jurídicas podem ser responsabilizadas administrativa, civil e penalmente conforme a Lei nº 9.605/98, sendo a responsabilidade penal da entidade excluída caso a responsabilidade das pessoas físicas autoras ou coautoras do mesmo fato não seja comprovada.","answer":false,"explanation":"Art. 3º As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade. Parágrafo único. A responsabilidade das pessoas jurídicas não exclui a das pessoas físicas, autoras, co-autoras ou partícipes do mesmo fato.","source":"65.pdf · questão 16 · Art. 3º, § único, Lei 9.605/98","meta":"Unifil 2026 – Médico Veterinário (Prefeitura Centenário Sul - RS)","bank":"Unifil","year":2026,"role":"Médico Veterinário (Prefeitura Centenário Sul - RS)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q027","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 4º","number":"Art. 4º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 4º Poderá ser desconsiderada a pessoa jurídica sempre que sua personalidade for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente."],"origin":"real","question":{"statement":"A Lei de Crimes Ambientais (Lei nº 9.605/1998) dispõe sobre as sanções penais e administrativas derivadas de condutas lesivas ao meio ambiente. Considerando os dispositivos legais sobre a responsabilização da pessoa jurídica (PJ), julgue o item. A desconsideração da personalidade jurídica da sociedade poderá ser decretada quando sua personalidade for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente, independentemente da comprovação de fraude ou abuso de direito.","answer":true,"explanation":"Art. 4º Poderá ser desconsiderada a pessoa jurídica sempre que sua personalidade for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente.","source":"65.pdf · questão 27 · Art. 4º, Lei 9.605/98","meta":"Instituto ACCESS 2026 - Fiscal (Prefeitura de Planaltina - GO)","bank":"Instituto ACCESS","year":2026,"role":"Fiscal (Prefeitura de Planaltina - GO)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q028","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 5º, § 1º","number":"Art. 5º, § 1º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 32. Praticar ato de abuso, maus-tratos, ferir ou mutilar animais silvestres, domésticos ou domesticados, nativos ou exóticos: (Vide ADPF 640) Pena - detenção, de três meses a um ano, e multa. […] § 1º-B. Incorre nas mesmas penas quem realiza ou permite a realização de tatuagens e a colocação de piercings em cães e gatos, com fins estéticos. (Incluído pela Lei nº 15.150, de 2025)"],"origin":"authorial","question":{"statement":"De acordo com a Lei 9.605/98, que dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, é correto afirmar que incorre nas penas de detenção, de seis meses a um ano, e multa, quem realiza ou permite a realização de tatuagens e a colocação de piercings em cães e gatos, com fins estéticos.","answer":false,"explanation":"Art. 32. Praticar ato de abuso, maus-tratos, ferir ou mutilar animais silvestres, domésticos ou domesticados, nativos ou exóticos: (Vide ADPF 640) Pena - detenção, de três meses a um ano, e multa. […] § 1º-B. Incorre nas mesmas penas quem realiza ou permite a realização de tatuagens e a colocação de piercings em cães e gatos, com fins estéticos. (Incluído pela Lei nº 15.150, de 2025)","source":"65.pdf · questão 28 · Art. 5º, § 1º, Lei 9.605/98","meta":"Exercício importado · Lei 9.605/1998","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-9605-pdf65-q029","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 6º","number":"Art. 6º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 6º Para imposição e gradação da penalidade, a autoridade competente observará: I - a gravidade do fato, tendo em vista os motivos da infração e suas conseqüências para a saúde pública e para o meio ambiente; II - os antecedentes do infrator quanto ao cumprimento da legislação de interesse ambiental; III - a situação econômica do infrator, no caso de multa."],"origin":"real","question":{"statement":"A situação econômica do infrator de crime ambiental deverá ser observada pela autoridade competente na gradação da penalidade de multa.","answer":true,"explanation":"Art. 6º Para imposição e gradação da penalidade, a autoridade competente observará: I - a gravidade do fato, tendo em vista os motivos da infração e suas conseqüências para a saúde pública e para o meio ambiente; II - os antecedentes do infrator quanto ao cumprimento da legislação de interesse ambiental; III - a situação econômica do infrator, no caso de multa.","source":"65.pdf · questão 29 · Art. 6º, Lei 9.605 / 98","meta":"CESPE / CEBRASPE 2020 - Analista Ministerial - Direito (MPE-CE)","bank":"CESPE / CEBRASPE","year":2020,"role":"Analista Ministerial - Direito (MPE-CE)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q031","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 6º, I","number":"Art. 6º, I","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: I - a gravidade do fato, tendo em vista os motivos da infração e suas conseqüências para a saúde pública e para o meio ambiente; [...]"],"origin":"real","question":{"statement":"A aplicação de penas, regulamentada pela Lei de Crimes Ambientais – Lei no 9.605/1998, deve ser exemplar, de modo a punir os infratores e a desencorajar, de maneira explícita, a ação de novas infrações. Cabe à autoridade competente, na aplicação da pena, avaliar a gravidade do fato, sem considerar de imediato os motivos da infração e suas consequências para a saúde pública e para o meio ambiente.","answer":false,"explanation":"Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: I - a gravidade do fato, tendo em vista os motivos da infração e suas conseqüências para a saúde pública e para o meio ambiente; [...]","source":"65.pdf · questão 31 · Art. 6º, I, Lei 9.605/98","meta":"VUNESP 2023 - Biólogo (Prefeitura de Guarulhos - SP)","bank":"VUNESP","year":2023,"role":"Biólogo (Prefeitura de Guarulhos - SP)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q032","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 6º, II","number":"Art. 6º, II","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: [...] II - os antecedentes do infrator quanto ao cumprimento da legislação de interesse ambiental; [...]"],"origin":"real","question":{"statement":"A aplicação de penas, regulamentada pela Lei de Crimes Ambientais – Lei no 9.605/1998, deve ser exemplar, de modo a punir os infratores e a desencorajar, de maneira explícita, a ação de novas infrações. Cabe à autoridade competente, na aplicação da pena, avaliar os antecedentes criminais do infrator, minimizando ao máximo a pena, em casos primários de infração.","answer":false,"explanation":"Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: [...] II - os antecedentes do infrator quanto ao cumprimento da legislação de interesse ambiental; [...]","source":"65.pdf · questão 32 · Art. 6º, II, Lei 9.605/98","meta":"VUNESP 2023 - Biólogo (Prefeitura de Guarulhos - SP)","bank":"VUNESP","year":2023,"role":"Biólogo (Prefeitura de Guarulhos - SP)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q034","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 6º, III","number":"Art. 6º, III","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: [...] III - a situação econômica do infrator, no caso de multa."],"origin":"real","question":{"statement":"A aplicação de penas, regulamentada pela Lei de Crimes Ambientais – Lei no 9.605/1998, deve ser exemplar, de modo a punir os infratores e a desencorajar, de maneira explícita, a ação de novas infrações. Cabe à autoridade competente, na aplicação da pena, avaliar a situação econômica do infrator, no caso de multa.","answer":true,"explanation":"Art. 6º - Para imposição e gradação da penalidade, a autoridade competente observará: [...] III - a situação econômica do infrator, no caso de multa.","source":"65.pdf · questão 34 · Art. 6º, III, Lei 9.605/98","meta":"VUNESP 2023 - Biólogo (Prefeitura de Guarulhos - SP)","bank":"VUNESP","year":2023,"role":"Biólogo (Prefeitura de Guarulhos - SP)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q036","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 7º","number":"Art. 7º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 7º - As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando: [...]"],"origin":"real","question":{"statement":"A respeito da aplicação da pena no sistema da Lei n.º 9.605/1998, julgue o item a seguir. As penas restritivas de direitos são autônomas e não admitem substituírem as privativas de liberdade.","answer":false,"explanation":"Art. 7º - As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando: [...]","source":"65.pdf · questão 36 · Art. 7º, Lei 9.605/98","meta":"CESPE/CEBRASPE 2022 - Geógrafo (Prefeitura de Maringá - PR)","bank":"CESPE/CEBRASPE","year":2022,"role":"Geógrafo (Prefeitura de Maringá - PR)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q037","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 7º, I","number":"Art. 7º, I","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 7º - As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando: I - tratar-se de crime culposo ou for aplicada a pena privativa de liberdade inferior a quatro anos; [...]"],"origin":"real","question":{"statement":"Considerando-se as sanções penais e administrativas cabíveis em razão de condutas e atividades lesivas ao meio ambiente, é correto afirmar que a pena privativa de liberdade poderá ser substituída por pena restritiva de direitos em função da duração da pena, quando inferior a quatro anos.","answer":true,"explanation":"Art. 7º - As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando: I - tratar-se de crime culposo ou for aplicada a pena privativa de liberdade inferior a quatro anos; [...]","source":"65.pdf · questão 37 · Art. 7º, I, Lei 9.605/98","meta":"CESPE/CEBRASPE 2025 - Delegado de Polícia (PC-CE)","bank":"CESPE/CEBRASPE","year":2025,"role":"Delegado de Polícia (PC-CE)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q042","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 7º, § único","number":"Art. 7º, § único","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 7º, Parágrafo único - As penas restritivas de direitos a que se refere este artigo terão a mesma duração da pena privativa de liberdade substituída."],"origin":"real","question":{"statement":"Julgue o item que se segue com base na Lei n.º 9.605/1998, que dispõe sobre as sanções penais e administrativas derivadas de condutas e atividade lesivas ao meio ambiente. A pena restritiva de direitos deve ter a mesma duração da pena privativa de liberdade substituída.","answer":true,"explanation":"Art. 7º, Parágrafo único - As penas restritivas de direitos a que se refere este artigo terão a mesma duração da pena privativa de liberdade substituída.","source":"65.pdf · questão 42 · Art. 7º, § único, Lei 9.605/98","meta":"CESPE/CEBRASPE 2023 - Analista Fazendário Municipal (Prefeitura de Fortaleza - CE)","bank":"CESPE/CEBRASPE","year":2023,"role":"Analista Fazendário Municipal (Prefeitura de Fortaleza - CE)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q043","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 8º, I","number":"Art. 8º, I","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 8º As penas restritivas de direito são: I - prestação de serviços à comunidade;"],"origin":"real","question":{"statement":"A Lei nº 9.605, de 12 de fevereiro de 1998, dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente. À luz de suas disposições, julgue o item. As penas restritivas de direitos previstas na legislação incluem a prestação pecuniária, mas não a prestação de serviços à comunidade.","answer":false,"explanation":"Art. 8º As penas restritivas de direito são: I - prestação de serviços à comunidade;","source":"65.pdf · questão 43 · Art. 8º, I, Lei 9.605/98","meta":"FGV 2026 - Especialista em Desenvolvimento de Tecnologia Nuclear e Defesa (AMAZUL)","bank":"FGV","year":2026,"role":"Especialista em Desenvolvimento de Tecnologia Nuclear e Defesa (AMAZUL)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q046","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 8º, III","number":"Art. 8º, III","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 8º - As penas restritivas de direito são: [...] III - suspensão parcial ou total de atividades; [...]"],"origin":"real","question":{"statement":"Nos termos da Lei de Crimes Ambientais, Lei Federal nº 9.605/1998, enquadra-se em sanção restritiva de direito a suspensão parcial ou total das atividades.","answer":true,"explanation":"Art. 8º - As penas restritivas de direito são: [...] III - suspensão parcial ou total de atividades; [...]","source":"65.pdf · questão 46 · Art. 8º, III, Lei 9.605/98","meta":"VUNESP 2021 - Engenheiro - Química (CODEN)","bank":"VUNESP","year":2021,"role":"Engenheiro - Química (CODEN)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q047","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 8º, II","number":"Art. 8º, II","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 8º - As penas restritivas de direito são: [...] II - interdição temporária de direitos; [...]"],"origin":"real","question":{"statement":"Julgue o item que se segue com base na Lei n.º 9.605/1998, que dispõe sobre as sanções penais e administrativas derivadas de condutas e atividade lesivas ao meio ambiente. A interdição permanente de direitos inclui-se entre as penas restritivas de direitos.","answer":false,"explanation":"Art. 8º - As penas restritivas de direito são: [...] II - interdição temporária de direitos; [...]","source":"65.pdf · questão 47 · Art. 8º, II, Lei 9.605/98","meta":"CESPE/CEBRASPE 2023 - Analista Fazendário Municipal (Prefeitura de Fortaleza - CE)","bank":"CESPE/CEBRASPE","year":2023,"role":"Analista Fazendário Municipal (Prefeitura de Fortaleza - CE)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q048","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 8º, V","number":"Art. 8º, V","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 8º - As penas restritivas de direito são: [...] V - recolhimento domiciliar."],"origin":"real","question":{"statement":"Julgue o item a seguir a respeito da disciplina legal dos crimes contra o meio ambiente. O recolhimento domiciliar é espécie de pena restritiva de direitos prevista na Lei de Crimes Ambientais.","answer":true,"explanation":"Art. 8º - As penas restritivas de direito são: [...] V - recolhimento domiciliar.","source":"65.pdf · questão 48 · Art. 8º, V, Lei 9.605/98","meta":"CESPE/CEBRASPE 2022 - Delegado de Polícia (PC-PB)","bank":"CESPE/CEBRASPE","year":2022,"role":"Delegado de Polícia (PC-PB)","origin":"real"}},{"id":"pen-lei-9605-pdf65-q050","discipline":"penal","topicId":"pen-lei-9605","subtopic":"Lei 9.605/1998 · Art. 9º","number":"Art. 9º","title":"Lei 9.605/1998 — Crimes Ambientais","parts":["Art. 9º - A prestação de serviços à comunidade consiste na atribuição ao condenado de tarefas gratuitas junto a parques e jardins públicos e unidades de conservação, e, no caso de dano da coisa particular, pública ou tombada, na restauração desta, se possível."],"origin":"real","question":{"statement":"Julgue o item a seguir a respeito a Lei de Crimes Ambientais. A prestação pecuniária consiste na atribuição ao condenado de tarefas gratuitas junto a parques e jardins públicos e unidades de conservação.","answer":false,"explanation":"Art. 9º - A prestação de serviços à comunidade consiste na atribuição ao condenado de tarefas gratuitas junto a parques e jardins públicos e unidades de conservação, e, no caso de dano da coisa particular, pública ou tombada, na restauração desta, se possível.","source":"65.pdf · questão 50 · Art. 9º, Lei 9.605/98","meta":"VUNESP 2023 - Analista de Regulação de Serviços Públicos - Meio Ambiente (SP Regula)","bank":"VUNESP","year":2023,"role":"Analista de Regulação de Serviços Públicos - Meio Ambiente (SP Regula)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q001","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 1º","number":"Art. 1º","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: […]"],"origin":"real","question":{"statement":"Constitui crime contra a ordem tributária suprimir ou reduzir tributo ou contribuição social, não prevendo a Lei n° 8.137/1990, contudo, a tipificação das mesmas condutas quanto aos acessórios.","answer":false,"explanation":"Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: […]","source":"54.pdf · questão 1 · Art. 1º, Lei 8.137/90","meta":"FCC 2019 - Promotor de Justiça (MPE-MT)","bank":"FCC","year":2019,"role":"Promotor de Justiça (MPE-MT)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q003","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 1º, I","number":"Art. 1º, I","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: I - omitir informação, ou prestar declaração falsa às autoridades fazendárias;"],"origin":"real","question":{"statement":"Omitir informação ou prestar declaração falsa às autoridades fazendárias constitui crime contra a ordem tributária.","answer":true,"explanation":"Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: I - omitir informação, ou prestar declaração falsa às autoridades fazendárias;","source":"54.pdf · questão 3 · Art. 1º, I, Lei 8.137/90","meta":"CEV UECE 2025 - Oficial Investigador de Polícia (PC-CE)","bank":"CEV UECE","year":2025,"role":"Oficial Investigador de Polícia (PC-CE)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q005","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 1º, III","number":"Art. 1º, III","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: (Vide Lei nº 9.964, de 10.4.2000) […] III - falsificar ou alterar nota fiscal, fatura, duplicata, nota de venda, ou qualquer outro documento relativo à operação tributável; […] Pena - reclusão de 2 (dois) a 5 (cinco) anos, e multa."],"origin":"real","question":{"statement":"A respeito de crimes contra a ordem tributária, ações processuais e penas que lhe são correlatas, julgue o próximo item, de acordo com a Lei n.º 8.137/1990 e alterações. A pena privativa de liberdade aplicável ao crime de falsificação de nota fiscal é de seis meses a dois anos, podendo ser convertida em multa pecuniária.","answer":false,"explanation":"Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: (Vide Lei nº 9.964, de 10.4.2000) […] III - falsificar ou alterar nota fiscal, fatura, duplicata, nota de venda, ou qualquer outro documento relativo à operação tributável; […] Pena - reclusão de 2 (dois) a 5 (cinco) anos, e multa.","source":"54.pdf · questão 5 · Art. 1º, III, Lei 8.137/90","meta":"CESPE 2018 - Delegado de Polícia (PC-SE)","bank":"CESPE","year":2018,"role":"Delegado de Polícia (PC-SE)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q007","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 1º, IV","number":"Art. 1º, IV","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: (Vide Lei nº 9.964, de 10.4.2000) [...] IV - elaborar, distribuir, fornecer, emitir ou utilizar documento que saiba ou deva saber falso ou inexato; [...]"],"origin":"real","question":{"statement":"Com exceção do crime previsto no inciso IV, do art. 1 o , da Lei n o 8.137/90 (elaborar, distribuir, fornecer, emitir ou utilizar documento que saiba ou deva saber falso ou inexato), todos os demais delitos previstos em referida legislação são praticados mediante dolo.","answer":false,"explanation":"Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: (Vide Lei nº 9.964, de 10.4.2000) [...] IV - elaborar, distribuir, fornecer, emitir ou utilizar documento que saiba ou deva saber falso ou inexato; [...]","source":"54.pdf · questão 7 · Art. 1º, IV, Lei 8.137/90","meta":"VUNESP 2024 - Promotor de Justiça (MPE-RJ)","bank":"VUNESP","year":2024,"role":"Promotor de Justiça (MPE-RJ)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q010","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 1º, V","number":"Art. 1º, V","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: […] V - negar ou deixar de fornecer, quando obrigatório, nota fiscal ou documento equivalente, relativa a venda de mercadoria ou prestação de serviço, efetivamente realizada, ou fornecê-la em desacordo com a legislação. Súmula Vinculante 24: Não se tipifica crime material contra a ordem tributária, previsto no artigo 1º, incisos I a IV, da Lei nº 8.137/90, antes do lançamento definitivo do tributo."],"origin":"real","question":{"statement":"Acerca da representação penal para fins fiscais, a jurisprudência exige, em regra, a constituição definitiva do crédito tributário, admitindo, todavia, quando se tratar de crime material, a instauração de inquérito como medida imprescindível para a própria apuração do tributo devido. Entre as previsões da Lei no 8.137/1990, a jurisprudência, contudo, não exige a prévia constituição definitiva do crédito, quando a conduta do agente for a de negar ou deixar de fornecer, quando obrigatório, nota fiscal ou documento equivalente, relativo a venda de mercadoria ou prestação de serviço, efetivamente realizada, ou fornecê-lo em desacordo com a legislação.","answer":true,"explanation":"Art. 1° Constitui crime contra a ordem tributária suprimir ou reduzir tributo, ou contribuição social e qualquer acessório, mediante as seguintes condutas: […] V - negar ou deixar de fornecer, quando obrigatório, nota fiscal ou documento equivalente, relativa a venda de mercadoria ou prestação de serviço, efetivamente realizada, ou fornecê-la em desacordo com a legislação. Súmula Vinculante 24: Não se tipifica crime material contra a ordem tributária, previsto no artigo 1º, incisos I a IV, da Lei nº 8.137/90, antes do lançamento definitivo do tributo.","source":"54.pdf · questão 10 · Art. 1º, V, Lei 8.137/90 c/c SV 24","meta":"VUNESP 2024 - Promotor de Justiça Substituto (MPE-RO)","bank":"VUNESP","year":2024,"role":"Promotor de Justiça Substituto (MPE-RO)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q012","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 2º","number":"Art. 2º","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 2° Constitui crime da mesma natureza: […] II - deixar de recolher, no prazo legal, valor de tributo ou de contribuição social, descontado ou cobrado, na qualidade de sujeito passivo de obrigação e que deveria recolher aos cofres públicos; […]"],"origin":"real","question":{"statement":"Um contribuinte, por falta de capital de giro e sabendo dos altos juros cobrados por instituições financeiras, adotou a prática de registrar, nos livros contábeis e fiscais, todas as transações comerciais sobre as quais incide o ICMS, declarando ao fisco os referidos tributos como devidos. Entretanto, mesmo já tendo cobrado os valores do consumidor final, não realizou, entre os anos de 2013 a 2015, os recolhimentos na data devida. Considerando essa situação hipotética e as legislações pertinentes, julgue o item subsequente. É correto afirmar que o contribuinte em questão praticou crime contra a ordem tributária, previsto na Lei n.º 8.137/1990.","answer":true,"explanation":"Art. 2° Constitui crime da mesma natureza: […] II - deixar de recolher, no prazo legal, valor de tributo ou de contribuição social, descontado ou cobrado, na qualidade de sujeito passivo de obrigação e que deveria recolher aos cofres públicos; […]","source":"54.pdf · questão 12 · Art. 2º, Lei 8.137/1990","meta":"CESPE/CEBRASPE 2023 - Promotor de Justiça Substituto (MPE-SC)","bank":"CESPE/CEBRASPE","year":2023,"role":"Promotor de Justiça Substituto (MPE-SC)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q013","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 2º, I","number":"Art. 2º, I","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Justificativa da banca: A pena é a mesma, pois o tipo penal é um só, previsto no art. 2º da Lei nº 8.137: Art. 2° Constitui crime da mesma natureza: I - fazer declaração falsa ou omitir declaração sobre rendas, bens ou fatos, ou empregar outra fraude, para eximir-se, total ou parcialmente, de pagamento de tributo; [...]"],"origin":"real","question":{"statement":"As penas previstas para o crime de fazer declaração falsa ou omitir declaração sobre rendas para eximir-se do pagamento integral do imposto de renda se diferenciam do caso em que o contribuinte procura deixar de pagar apenas parcialmente o referido imposto.","answer":false,"explanation":"Justificativa da banca: A pena é a mesma, pois o tipo penal é um só, previsto no art. 2º da Lei nº 8.137: Art. 2° Constitui crime da mesma natureza: I - fazer declaração falsa ou omitir declaração sobre rendas, bens ou fatos, ou empregar outra fraude, para eximir-se, total ou parcialmente, de pagamento de tributo; [...]","source":"54.pdf · questão 13 · Art. 2º, I, Lei 8.137/90","meta":"CESPE/CEBRASPE 2022 - Procurador do Distrito Federal (PG-DF)","bank":"CESPE/CEBRASPE","year":2022,"role":"Procurador do Distrito Federal (PG-DF)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q016","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 2º, II","number":"Art. 2º, II","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 2° Constitui crime da mesma natureza: (Vide Lei nº 9.964, de 10.4.2000) [...] II - deixar de recolher, no prazo legal, valor de tributo ou de contribuição social, descontado ou cobrado, na qualidade de sujeito passivo de obrigação e que deveria recolher aos cofres públicos; [...]"],"origin":"real","question":{"statement":"Mauro, na condição de sujeito passivo da obrigação, deixou de recolher, no prazo legal, valor de contribuição social descontado que deveria ter sido recolhido aos cofres públicos. Nessa situação, a conduta praticada por Mauro configura crime contra a ordem tributária, previsto na Lei n.º 8.137/1990.","answer":true,"explanation":"Art. 2° Constitui crime da mesma natureza: (Vide Lei nº 9.964, de 10.4.2000) [...] II - deixar de recolher, no prazo legal, valor de tributo ou de contribuição social, descontado ou cobrado, na qualidade de sujeito passivo de obrigação e que deveria recolher aos cofres públicos; [...]","source":"54.pdf · questão 16 · Art. 2º, II, Lei 8.137/90","meta":"CESPE/CEBRASPE 2024 - Tabelião / Oficial de Registros - Provimento (TJ-PE)","bank":"CESPE/CEBRASPE","year":2024,"role":"Tabelião / Oficial de Registros - Provimento (TJ-PE)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q018","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 2º, IV","number":"Art. 2º, IV","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["CAPÍTULO I - Dos Crimes Contra a Ordem Tributária Seção I - Dos crimes praticados por particulares […] Art. 2° Constitui crime da mesma natureza: […] IV - deixar de aplicar, ou aplicar em desacordo com o estatuído, incentivo fiscal ou parcelas de imposto liberadas por órgão ou entidade de desenvolvimento;"],"origin":"real","question":{"statement":"De acordo com o que dispõe a Lei nº 8.137/1990, que define crimes contra a ordem tributária, econômica e contra as relações de consumo, constitui crime contra a ordem econômica deixar de aplicar incentivo fiscal ou parcelas de imposto liberadas por órgão ou entidade de desenvolvimento.","answer":false,"explanation":"CAPÍTULO I - Dos Crimes Contra a Ordem Tributária Seção I - Dos crimes praticados por particulares […] Art. 2° Constitui crime da mesma natureza: […] IV - deixar de aplicar, ou aplicar em desacordo com o estatuído, incentivo fiscal ou parcelas de imposto liberadas por órgão ou entidade de desenvolvimento;","source":"54.pdf · questão 18 · Art. 2º, IV, Lei 8.137/90","meta":"FCC 2018 - Auditor Fiscal (SEFAZ-SC)","bank":"FCC","year":2018,"role":"Auditor Fiscal (SEFAZ-SC)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q020","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 2º, V","number":"Art. 2º, V","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["O art. 2º está na Seção I do Capítulo I, que trata dos crimes praticados por particulares. Art. 2° Constitui crime da mesma natureza: […] V - utilizar ou divulgar programa de processamento de dados que permita ao sujeito passivo da obrigação tributária possuir informação contábil diversa daquela que é, por lei, fornecida à Fazenda Pública. Pena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."],"origin":"real","question":{"statement":"Em relação aos crimes praticados por funcionários públicos, constitui crime funcional contra a ordem tributária, utilizar ou divulgar programa de processamento de dados que permita ao sujeito passivo da obrigação tributária possuir informação contábil diversa daquela que é, por lei, fornecida à Fazenda Pública.","answer":false,"explanation":"O art. 2º está na Seção I do Capítulo I, que trata dos crimes praticados por particulares. Art. 2° Constitui crime da mesma natureza: […] V - utilizar ou divulgar programa de processamento de dados que permita ao sujeito passivo da obrigação tributária possuir informação contábil diversa daquela que é, por lei, fornecida à Fazenda Pública. Pena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.","source":"54.pdf · questão 20 · Art. 2º, V, Lei 8.137/90","meta":"VUNESP 2019 - Procurador Jurídico (Prefeitura de Poá - SP)","bank":"VUNESP","year":2019,"role":"Procurador Jurídico (Prefeitura de Poá - SP)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q022","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 3º da","number":"Art. 3º da","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal (Título XI, Capítulo I): III - patrocinar, direta ou indiretamente, interesse privado perante a administração fazendária, valendo-se da qualidade de funcionário público. Pena - reclusão, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"real","question":{"statement":"Tendo como base as disposições da Lei nº 8.137/1990, julgue o item a seguir Caso Tício, auditor fiscal da receita federal, patrocine interesse privado perante a administração fazendária, valendo-se da sua qualidade de funcionário público, estará cometendo crime funcional contra a ordem tributária, podendo ser apenado com reclusão, de um a quatro anos, e multa.","answer":true,"explanation":"Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal (Título XI, Capítulo I): III - patrocinar, direta ou indiretamente, interesse privado perante a administração fazendária, valendo-se da qualidade de funcionário público. Pena - reclusão, de 1 (um) a 4 (quatro) anos, e multa.","source":"54.pdf · questão 22 · Art. 3º da Lei nº 8.137/199","meta":"- INSTITUTO CONSULPLAN 2024 - Promotor de Justiça (MPE-SC)","bank":"- INSTITUTO CONSULPLAN","year":2024,"role":"Promotor de Justiça (MPE-SC)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q025","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 3º, I","number":"Art. 3º, I","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): I - extraviar livro oficial, processo fiscal ou qualquer documento, de que tenha a guarda em razão da função; sonegá-lo, ou inutilizá-lo, total ou parcialmente, acarretando pagamento indevido ou inexato de tributo ou contribuição social;"],"origin":"real","question":{"statement":"Constitui crime funcional contra a ordem tributária extraviar livro oficial, processo fiscal ou qualquer documento de que tenha a guarda em razão da função; sonegá-lo, ou inutilizá-lo, total ou parcialmente, acarretando pagamento indevido ou inexato de tributo ou contribuição social.","answer":true,"explanation":"Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): I - extraviar livro oficial, processo fiscal ou qualquer documento, de que tenha a guarda em razão da função; sonegá-lo, ou inutilizá-lo, total ou parcialmente, acarretando pagamento indevido ou inexato de tributo ou contribuição social;","source":"54.pdf · questão 25 · Art. 3º, I, Lei 8.137/90","meta":"VUNESP 2019 - Procurador Jurídico (Câmara de São Roque - SP)","bank":"VUNESP","year":2019,"role":"Procurador Jurídico (Câmara de São Roque - SP)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q028","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 3º, II","number":"Art. 3º, II","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): [...] II - exigir, solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de iniciar seu exercício, mas em razão dela, vantagem indevida; ou aceitar promessa de tal vantagem, para deixar de lançar ou cobrar tributo ou contribuição social, ou cobrá-los parcialmente. Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa."],"origin":"real","question":{"statement":"À luz da legislação penal brasileira, julgue o item a seguir. Auditor-fiscal que exigir vantagem indevida para deixar de lançar ou de cobrar tributo devido por contribuinte terá cometido o crime de concussão previsto no Código Penal.","answer":false,"explanation":"Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): [...] II - exigir, solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de iniciar seu exercício, mas em razão dela, vantagem indevida; ou aceitar promessa de tal vantagem, para deixar de lançar ou cobrar tributo ou contribuição social, ou cobrá-los parcialmente. Pena - reclusão, de 3 (três) a 8 (oito) anos, e multa.","source":"54.pdf · questão 28 · Art. 3º, II, Lei 8.137/90","meta":"CESPE/CEBRASPE 2020 - Auditor Fiscal da Receita Estadual (SEFAZ-AL)","bank":"CESPE/CEBRASPE","year":2020,"role":"Auditor Fiscal da Receita Estadual (SEFAZ-AL)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q030","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 3º, III","number":"Art. 3º, III","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): […] III - patrocinar, direta ou indiretamente, interesse privado perante a administração fazendária, valendo-se da qualidade de funcionário público. Pena - reclusão, de 1 (um) a 4 (quatro) anos, e multa."],"origin":"real","question":{"statement":"O particular que, conjuntamente com um funcionário público, sabendo da condição deste, patrocina diretamente interesse privado perante a administração fazendária pratica crime previsto na Lei n.º 8.137/1990.","answer":true,"explanation":"Art. 3° Constitui crime funcional contra a ordem tributária, além dos previstos no Decreto-Lei n° 2.848, de 7 de dezembro de 1940 - Código Penal (Título XI, Capítulo I): […] III - patrocinar, direta ou indiretamente, interesse privado perante a administração fazendária, valendo-se da qualidade de funcionário público. Pena - reclusão, de 1 (um) a 4 (quatro) anos, e multa.","source":"54.pdf · questão 30 · Art. 3º, III, Lei 8.137/90","meta":"CESPE/CEBRASPE 2022 - Promotor de Justiça (MPE-SE)","bank":"CESPE/CEBRASPE","year":2022,"role":"Promotor de Justiça (MPE-SE)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q032","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 4º","number":"Art. 4º","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 4° - Constitui crime contra a ordem econômica: I - abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante qualquer forma de ajuste ou acordo de empresas; II - formar acordo, convênio, ajuste ou aliança entre ofertantes, visando: a) à fixação artificial de preços ou quantidades vendidas ou produzidas; III - (revogado); IV - (revogado); V - (revogado); VI - (revogado); VII - (revogado). Pena - reclusão, de 2 (dois) a 5 (cinco) anos e multa."],"origin":"real","question":{"statement":"Julgue o item a seguir. Constitui crime contra a ordem econômica: (i) abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante ajuste ou acordo de empresas; (ii) formar acordo, convênio, ajuste ou aliança entre ofertantes, visando à fixação artificial de preços ou quantidades vendidas ou produzidas; (iii) discriminar preços de bens ou de prestação de serviços por ajustes ou acordo de grupo econômico, com o fim de estabelecer monopólio, ou de eliminar, total ou parcialmente, a concorrência; (iv) açambarcar, sonegar, destruir ou inutilizar bens de produção ou de consumo, com o fim de estabelecer monopólio ou de eliminar, total ou parcialmente, a concorrência; (v) provocar oscilação de preços em detrimento de empresa concorrente ou vendedor de matéria-prima, mediante ajuste ou acordo, ou por outro meio fraudulento; (vi) vender mercadorias abaixo do preço de custo, com o fim de impedir a concorrência; e (vii) elevar, sem justa causa, os preços de bens ou serviços, valendo-se de monopólio natural ou de fato. Pena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa.","answer":false,"explanation":"Art. 4° - Constitui crime contra a ordem econômica: I - abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante qualquer forma de ajuste ou acordo de empresas; II - formar acordo, convênio, ajuste ou aliança entre ofertantes, visando: a) à fixação artificial de preços ou quantidades vendidas ou produzidas; III - (revogado); IV - (revogado); V - (revogado); VI - (revogado); VII - (revogado). Pena - reclusão, de 2 (dois) a 5 (cinco) anos e multa.","source":"54.pdf · questão 32 · Art. 4º, Lei 8.137/90","meta":"FGV 2025 - Juiz Federal Substituto (TRF - 3ª Região)","bank":"FGV","year":2025,"role":"Juiz Federal Substituto (TRF - 3ª Região)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q034","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 4º, I","number":"Art. 4º, I","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Trata-se, na verdade, de crime contra a ordem econômica. Art. 4° Constitui crime contra a ordem econômica: I - abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante qualquer forma de ajuste ou acordo de empresas; Pena - reclusão, de 2 (dois) a 5 (cinco) anos e multa."],"origin":"real","question":{"statement":"De acordo com a Lei no 8.137/1990, constitui crime contra as relações de consumo abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante qualquer forma de ajuste ou acordo de empresas.","answer":false,"explanation":"Trata-se, na verdade, de crime contra a ordem econômica. Art. 4° Constitui crime contra a ordem econômica: I - abusar do poder econômico, dominando o mercado ou eliminando, total ou parcialmente, a concorrência mediante qualquer forma de ajuste ou acordo de empresas; Pena - reclusão, de 2 (dois) a 5 (cinco) anos e multa.","source":"54.pdf · questão 34 · Art. 4º, I, Lei 8.137/90","meta":"FCC 2018 - Auditor Fiscal (Prefeitura de São Luís - MA)","bank":"FCC","year":2018,"role":"Auditor Fiscal (Prefeitura de São Luís - MA)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q035","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 4º, II, a","number":"Art. 4º, II, a","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 4° Constitui crime contra a ordem econômica: […] II - formar acordo, convênio, ajuste ou aliança entre ofertantes, visando: a) à fixação artificial de preços ou quantidades vendidas ou produzidas;"],"origin":"real","question":{"statement":"É correto afirmar que constitui crime contra as relações de consumo, formar acordo, convênio, ajuste ou aliança entre ofertantes, visando à fixação artificial de preços ou quantidades vendidas ou produzidas.","answer":false,"explanation":"Art. 4° Constitui crime contra a ordem econômica: […] II - formar acordo, convênio, ajuste ou aliança entre ofertantes, visando: a) à fixação artificial de preços ou quantidades vendidas ou produzidas;","source":"54.pdf · questão 35 · Art. 4º, II, a, Lei 8.137/90","meta":"FUNCAB 2012 - Delegado de Polícia (PC-RJ)","bank":"FUNCAB","year":2012,"role":"Delegado de Polícia (PC-RJ)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q037","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 7º, I","number":"Art. 7º, I","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 7º. Constitui crime contra as relações de consumo: I - favorecer ou preferir, sem justa causa, comprador ou freguês, ressalvados os sistemas de entrega ao consumo por intermédio de distribuidores ou revendedores."],"origin":"real","question":{"statement":"Constitui crime contra as relações de consumo favorecer ou preferir, com ou sem justa causa, comprador ou freguês, ressalvados os sistemas de entrega ao consumo por intermédio de distribuidores ou revendedores.","answer":false,"explanation":"Art. 7º. Constitui crime contra as relações de consumo: I - favorecer ou preferir, sem justa causa, comprador ou freguês, ressalvados os sistemas de entrega ao consumo por intermédio de distribuidores ou revendedores.","source":"54.pdf · questão 37 · Art. 7º, I, Lei 8.137/90","meta":"CESPE 2016 - Juiz de Direito (TJ-AM)","bank":"CESPE","year":2016,"role":"Juiz de Direito (TJ-AM)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q038","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 7º, IV, b","number":"Art. 7º, IV, b","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 7° Constitui crime contra as relações de consumo: […] IV - fraudar preços por meio de: […] b) divisão em partes de bem ou serviço, habitualmente oferecido à venda em conjunto;"],"origin":"real","question":{"statement":"É correto afirmar que constitui crime contra as relações de consumo, fraudar preços por meio de divisão em partes de bem ou serviço, habitualmente oferecido à venda em conjunto.","answer":true,"explanation":"Art. 7° Constitui crime contra as relações de consumo: […] IV - fraudar preços por meio de: […] b) divisão em partes de bem ou serviço, habitualmente oferecido à venda em conjunto;","source":"54.pdf · questão 38 · Art. 7º, IV, b, Lei 8.137/90","meta":"FUNCAB 2012 - Delegado de Polícia (PC-RJ)","bank":"FUNCAB","year":2012,"role":"Delegado de Polícia (PC-RJ)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q039","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 7º, VIII","number":"Art. 7º, VIII","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 7° Constitui crime contra as relações de consumo: [...] VIII - destruir, inutilizar ou danificar matéria-prima ou mercadoria, com o fim de provocar alta de preço, em proveito próprio ou de terceiros;"],"origin":"real","question":{"statement":"Nos termos da legislação penal, a conduta de destruir mercadoria, com o fim de provocar alta de preços, constitui crime contra a ordem econômica.","answer":false,"explanation":"Art. 7° Constitui crime contra as relações de consumo: [...] VIII - destruir, inutilizar ou danificar matéria-prima ou mercadoria, com o fim de provocar alta de preço, em proveito próprio ou de terceiros;","source":"54.pdf · questão 39 · Art. 7º, VIII, Lei 8.137/90","meta":"FCC 2018 - Promotor de Justiça (MPE-PB)","bank":"FCC","year":2018,"role":"Promotor de Justiça (MPE-PB)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q040","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 7º, IX","number":"Art. 7º, IX","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 7° Constitui crime contra as relações de consumo: […] IX - vender, ter em depósito para vender ou expor à venda ou, de qualquer forma, entregar matéria-prima ou mercadoria, em condições impróprias ao consumo; Pena - detenção, de 2 (dois) a 5 (cinco) anos, ou multa. Parágrafo único. Nas hipóteses dos incisos II, III e IX pune-se a modalidade culposa, reduzindo-se a pena e a detenção de 1/3 (um terço) ou a de multa à quinta parte."],"origin":"real","question":{"statement":"O crime de vender mercadoria em condições impróprias ao consumo, previsto no artigo 7°, inciso IX, da Lei n° 8.137/90, é punido a título de dolo e de culpa.","answer":true,"explanation":"Art. 7° Constitui crime contra as relações de consumo: […] IX - vender, ter em depósito para vender ou expor à venda ou, de qualquer forma, entregar matéria-prima ou mercadoria, em condições impróprias ao consumo; Pena - detenção, de 2 (dois) a 5 (cinco) anos, ou multa. Parágrafo único. Nas hipóteses dos incisos II, III e IX pune-se a modalidade culposa, reduzindo-se a pena e a detenção de 1/3 (um terço) ou a de multa à quinta parte.","source":"54.pdf · questão 40 · Art. 7º, IX, Lei 8.137/90","meta":"MPE-SP 2019 - Promotor de Justiça","bank":"MPE-SP","year":2019,"role":"Promotor de Justiça","origin":"real"}},{"id":"pen-lei-8137-pdf54-q043","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 7º, § único","number":"Art. 7º, § único","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 7° Constitui crime contra as relações de consumo: […] Parágrafo único. Nas hipóteses dos incisos II, III e IX pune-se a modalidade culposa, reduzindo-se a pena e a detenção de 1/3 (um terço) ou a de multa à quinta parte."],"origin":"real","question":{"statement":"Os delitos previstos na Lei nº 8.137/90 somente se punem a título de dolo.","answer":false,"explanation":"Art. 7° Constitui crime contra as relações de consumo: […] Parágrafo único. Nas hipóteses dos incisos II, III e IX pune-se a modalidade culposa, reduzindo-se a pena e a detenção de 1/3 (um terço) ou a de multa à quinta parte.","source":"54.pdf · questão 43 · Art. 7º, § único, Lei 8.137/90","meta":"FUNDEP 2022 - Promotor de Justiça (MPE-MG)","bank":"FUNDEP","year":2022,"role":"Promotor de Justiça (MPE-MG)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q046","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 8º","number":"Art. 8º","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 8° Nos crimes definidos nos arts. 1° a 3° desta lei, a pena de multa será fixada entre 10 (dez) e 360 (trezentos e sessenta) dias-multa, conforme seja necessário e suficiente para reprovação e prevenção do crime."],"origin":"real","question":{"statement":"Em relação aos crimes contra a ordem tributária, é correto afirmar que a pena de multa será fixada entre 05 (cinco) e 365 (trezentos e sessenta e cinco) dias-multa, conforme seja necessário e suficiente para reprovação e prevenção do crime.","answer":false,"explanation":"Art. 8° Nos crimes definidos nos arts. 1° a 3° desta lei, a pena de multa será fixada entre 10 (dez) e 360 (trezentos e sessenta) dias-multa, conforme seja necessário e suficiente para reprovação e prevenção do crime.","source":"54.pdf · questão 46 · Art. 8º, Lei 8.137/90","meta":"VUNESP 2019 - Procurador Jurídico (Prefeitura de Poá - SP)","bank":"VUNESP","year":2019,"role":"Procurador Jurídico (Prefeitura de Poá - SP)","origin":"real"}},{"id":"pen-lei-8137-pdf54-q048","discipline":"penal","topicId":"pen-lei-8137","subtopic":"Lei 8.137/1990 · Art. 11","number":"Art. 11","title":"Lei 8.137/1990 — Crimes contra a Ordem Tributária","parts":["Art. 11. Quem, de qualquer modo, inclusive por meio de pessoa jurídica, concorre para os crimes definidos nesta lei, incide nas penas a estes cominadas, na medida de sua culpabilidade. Parágrafo único. Quando a venda ao consumidor for efetuada por sistema de entrega ao consumo ou por intermédio de outro em que o preço ao consumidor é estabelecido ou sugerido pelo fabricante ou concedente, o ato por este praticado não alcança o distribuidor ou revendedor."],"origin":"real","question":{"statement":"Quem, de qualquer modo, inclusive por meio de pessoa jurídica, concorre para os crimes definidos na Lei n. 8.137/1990, incide nas penas a estes cominadas, na medida de sua culpabilidade.","answer":true,"explanation":"Art. 11. Quem, de qualquer modo, inclusive por meio de pessoa jurídica, concorre para os crimes definidos nesta lei, incide nas penas a estes cominadas, na medida de sua culpabilidade. Parágrafo único. Quando a venda ao consumidor for efetuada por sistema de entrega ao consumo ou por intermédio de outro em que o preço ao consumidor é estabelecido ou sugerido pelo fabricante ou concedente, o ato por este praticado não alcança o distribuidor ou revendedor.","source":"54.pdf · questão 48 · Art. 11, Lei 8.137/90","meta":"IESES 2012 - Tabelião / Oficial de Registros (TJ-SC)","bank":"IESES","year":2012,"role":"Tabelião / Oficial de Registros (TJ-SC)","origin":"real"}},{"id":"pen-lei-13344-pdf29-q001","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 1º","number":"Art. 1º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 1° Esta Lei dispõe sobre o tráfico de pessoas cometido no território nacional contra vítima brasileira ou estrangeira e no exterior contra vítima brasileira."],"origin":"authorial","question":{"statement":"É correto afirmar que a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas) dispõe sobre o tráfico de pessoas cometido no território nacional e no exterior exclusivamente contra vítima brasileira.","answer":false,"explanation":"Art. 1° Esta Lei dispõe sobre o tráfico de pessoas cometido no território nacional contra vítima brasileira ou estrangeira e no exterior contra vítima brasileira.","source":"29.pdf · questão 1 · Art. 1°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q002","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 2º, IV","number":"Art. 2º, IV","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 2° O enfrentamento ao tráfico de pessoas atenderá aos seguintes princípios: [...] IV - não discriminação por motivo de gênero, orientação sexual, origem étnica ou social, procedência, nacionalidade, atuação profissional, raça, religião, faixa etária, situação migratória ou outro status;"],"origin":"authorial","question":{"statement":"Segundo a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que a não discriminação por motivo de gênero, orientação sexual, origem étnica ou social, procedência, nacionalidade, atuação profissional, raça, religião, faixa etária, situação migratória ou outro status, constitui um dos princípios do enfrentamento ao tráfico de pessoas.","answer":true,"explanation":"Art. 2° O enfrentamento ao tráfico de pessoas atenderá aos seguintes princípios: [...] IV - não discriminação por motivo de gênero, orientação sexual, origem étnica ou social, procedência, nacionalidade, atuação profissional, raça, religião, faixa etária, situação migratória ou outro status;","source":"29.pdf · questão 2 · Art. 2°, IV, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q003","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 3º, VI e VII","number":"Art. 3º, VI e VII","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 3º O enfrentamento ao tráfico de pessoas atenderá às seguintes diretrizes: [...] VI - estímulo à cooperação internacional; VII - incentivo à realização de estudos e pesquisas e ao seu compartilhamento;"],"origin":"authorial","question":{"statement":"Conforme a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que estímulo à cooperação internacional e incentivo à realização de estudos e pesquisas e ao seu compartilhamento são alguns dos princípios aos quais o enfrentamento ao tráfico de pessoas atenderá.","answer":false,"explanation":"Art. 3º O enfrentamento ao tráfico de pessoas atenderá às seguintes diretrizes: [...] VI - estímulo à cooperação internacional; VII - incentivo à realização de estudos e pesquisas e ao seu compartilhamento;","source":"29.pdf · questão 3 · Art. 3°, VI e VII, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q004","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 4º","number":"Art. 4º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 4° A prevenção ao tráfico de pessoas dar-se-á por meio: I - da implementação de medidas intersetoriais e integradas nas áreas de saúde, educação, trabalho, segurança pública, justiça, turismo, assistência social, desenvolvimento rural, esportes, comunicação, cultura e direitos humanos; II - de campanhas socioeducativas e de conscientização, considerando as diferentes realidades e linguagens; III - de incentivo à mobilização e à participação da sociedade civil; e IV - de incentivo a projetos de prevenção ao tráfico de pessoas."],"origin":"authorial","question":{"statement":"Acerca do que dispõe a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), julgue o item a seguir: A repressão ao tráfico de pessoas dar-se-á por meio da implementação de medidas intersetoriais e integradas nas áreas de saúde, educação, trabalho, segurança pública, justiça, turismo, assistência social, desenvolvimento rural, esportes, comunicação, cultura e direitos humanos; de campanhas socioeducativas e de conscientização, considerando as diferentes realidades e linguagens; de incentivo à mobilização e à participação da sociedade civil; e de incentivo a projetos de prevenção ao tráfico de pessoas.","answer":false,"explanation":"Art. 4° A prevenção ao tráfico de pessoas dar-se-á por meio: I - da implementação de medidas intersetoriais e integradas nas áreas de saúde, educação, trabalho, segurança pública, justiça, turismo, assistência social, desenvolvimento rural, esportes, comunicação, cultura e direitos humanos; II - de campanhas socioeducativas e de conscientização, considerando as diferentes realidades e linguagens; III - de incentivo à mobilização e à participação da sociedade civil; e IV - de incentivo a projetos de prevenção ao tráfico de pessoas.","source":"29.pdf · questão 4 · Art. 4°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q005","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 5º","number":"Art. 5º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 5° A repressão ao tráfico de pessoas dar-se-á por meio: I - da cooperação entre órgãos do sistema de justiça e segurança, nacionais e estrangeiros; II - da integração de políticas e ações de repressão aos crimes correlatos e da responsabilização dos seus autores; III - da formação de equipes conjuntas de investigação."],"origin":"authorial","question":{"statement":"Com base no disposto na Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que a repressão ao tráfico de pessoas dar-se-á por meio da cooperação entre órgãos do sistema de justiça e segurança, nacionais e estrangeiros; da integração de políticas e ações de repressão aos crimes correlatos e da responsabilização dos seus autores; e da formação de equipes conjuntas de investigação.","answer":true,"explanation":"Art. 5° A repressão ao tráfico de pessoas dar-se-á por meio: I - da cooperação entre órgãos do sistema de justiça e segurança, nacionais e estrangeiros; II - da integração de políticas e ações de repressão aos crimes correlatos e da responsabilização dos seus autores; III - da formação de equipes conjuntas de investigação.","source":"29.pdf · questão 5 · Art. 5°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q006","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 6º","number":"Art. 6º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 6° A proteção e o atendimento à vítima direta ou indireta do tráfico de pessoas compreendem: I - assistência jurídica, social, de trabalho e emprego e de saúde; II - acolhimento e abrigo provisório; [...] VI - atendimento humanizado; VII - informação sobre procedimentos administrativos e judiciais."],"origin":"authorial","question":{"statement":"Conforme a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que a proteção e o atendimento à vítima direta ou indireta do tráfico de pessoas compreendem, dentre outras atribuições, a assistência jurídica, social, de trabalho e emprego e de saúde; o acolhimento e abrigo provisório; atendimento humanizado; e informação sobre procedimentos administrativos e judiciais.","answer":true,"explanation":"Art. 6° A proteção e o atendimento à vítima direta ou indireta do tráfico de pessoas compreendem: I - assistência jurídica, social, de trabalho e emprego e de saúde; II - acolhimento e abrigo provisório; [...] VI - atendimento humanizado; VII - informação sobre procedimentos administrativos e judiciais.","source":"29.pdf · questão 6 · Art. 6°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q007","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 6º, § 1º","number":"Art. 6º, § 1º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 6° [...] § 1° A atenção às vítimas dar-se-á com a interrupção da situação de exploração ou violência, a sua reinserção social, a garantia de facilitação do acesso à educação, à cultura, à formação profissional e ao trabalho e, no caso de crianças e adolescentes, a busca de sua reinserção familiar e comunitária."],"origin":"authorial","question":{"statement":"Segundo a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que a atenção às vítimas darse-á com a interrupção da situação de exploração ou violência, a sua reinserção social, a garantia de facilitação do acesso à educação, à cultura, à formação profissional e ao trabalho e, no caso de crianças e adolescentes, a busca de sua inserção em programas de acolhimento familiar ou institucional.","answer":false,"explanation":"Art. 6° [...] § 1° A atenção às vítimas dar-se-á com a interrupção da situação de exploração ou violência, a sua reinserção social, a garantia de facilitação do acesso à educação, à cultura, à formação profissional e ao trabalho e, no caso de crianças e adolescentes, a busca de sua reinserção familiar e comunitária.","source":"29.pdf · questão 7 · Art. 6°, § 1°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q008","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 8º","number":"Art. 8º","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 8° O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias relacionadas a bens, direitos ou valores pertencentes ao investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito do crime de tráfico de pessoas, procedendo-se na forma dos arts. 125 a 144-A do Decreto-Lei n° 3.689, de 3 de outubro de 1941 (Código de Processo Penal)."],"origin":"authorial","question":{"statement":"Com base que dispõe a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), julgue o item a seguir: O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias relacionadas a bens, direitos ou valores pertencentes ao investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito do crime de tráfico de pessoas.","answer":true,"explanation":"Art. 8° O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias relacionadas a bens, direitos ou valores pertencentes ao investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito do crime de tráfico de pessoas, procedendo-se na forma dos arts. 125 a 144-A do Decreto-Lei n° 3.689, de 3 de outubro de 1941 (Código de Processo Penal).","source":"29.pdf · questão 8 · Art. 8°, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q009","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 14","number":"Art. 14","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 14. É instituído o Dia Nacional de Enfrentamento ao Tráfico de Pessoas, a ser comemorado, anualmente, em 30 de julho."],"origin":"authorial","question":{"statement":"Acerca do que dispõe a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que é instituído o Dia Nacional de Enfrentamento ao Tráfico de Pessoas, a ser comemorado, anualmente, em 30 de junho.","answer":false,"explanation":"Art. 14. É instituído o Dia Nacional de Enfrentamento ao Tráfico de Pessoas, a ser comemorado, anualmente, em 30 de julho.","source":"29.pdf · questão 9 · Art. 14, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13344-pdf29-q010","discipline":"penal","topicId":"pen-lei-13344","subtopic":"Lei 13.344/2016 · Art. 15","number":"Art. 15","title":"Lei 13.344/2016 — Tráfico de Pessoas","parts":["Art. 15. Serão adotadas campanhas nacionais de enfrentamento ao tráfico de pessoas, a serem divulgadas em veículos de comunicação, visando à conscientização da sociedade sobre todas as modalidades de tráfico de pessoas."],"origin":"authorial","question":{"statement":"Acerca do que dispõe a Lei 13.344/2016 (Prevenção e Repressão ao Tráfico Interno e Internacional de Pessoas e Medidas de atenção às Vítimas), é correto afirmar que serão adotadas campanhas nacionais de enfrentamento ao tráfico de pessoas, a serem divulgadas em veículos de comunicação, visando à conscientização da sociedade sobre todas as modalidades de tráfico de pessoas.","answer":true,"explanation":"Art. 15. Serão adotadas campanhas nacionais de enfrentamento ao tráfico de pessoas, a serem divulgadas em veículos de comunicação, visando à conscientização da sociedade sobre todas as modalidades de tráfico de pessoas.","source":"29.pdf · questão 10 · Art. 15, Lei 13.344/2016","meta":"Exercício importado · Lei 13.344/2016","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"pen-lei-13869-pdf33-q002","discipline":"penal","topicId":"pen-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º","number":"Art. 1º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º - Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído."],"origin":"real","question":{"statement":"Acerca do crime de abuso de autoridade e das definições constantes da Lei n.º 13.869/2019, julgue o item subsequente. Para a caracterização do crime de abuso de autoridade, é preciso que o agente esteja no exercício de suas funções públicas.","answer":false,"explanation":"Art. 1º - Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído.","source":"33.pdf · questão 2 · Art. 1º, Lei 13.869/2019","meta":"CESPE/CEBRASPE 2025 - Especialista em Recursos Minerais - Engenharia de Minas - Correcional (ANM)","bank":"CESPE/CEBRASPE","year":2025,"role":"Especialista em Recursos Minerais - Engenharia de Minas - Correcional (ANM)","origin":"real"}},{"id":"pen-lei-13869-pdf33-q006","discipline":"penal","topicId":"pen-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º, § 1º","number":"Art. 1º, § 1º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído. § 1º As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal."],"origin":"real","question":{"statement":"De acordo com o que dispõe a Lei Federal nº 13.869/2019 (crimes de abuso de autoridade), é correto afirmar que as condutas descritas nesta lei constituem crime de abuso de autoridade quando praticadas pelo agente ainda que por mero capricho ou satisfação pessoal.","answer":true,"explanation":"Art. 1º Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído. § 1º As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal.","source":"33.pdf · questão 6 · Art. 1º, § 1º, Lei 13.869/2019","meta":"FCC 2026 - Auditor Fiscal da Receita Estadual (SEFAZ-GO)","bank":"FCC","year":2026,"role":"Auditor Fiscal da Receita Estadual (SEFAZ-GO)","origin":"real"}},{"id":"pen-lei-13869-pdf33-q036","discipline":"penal","topicId":"pen-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º, § 2º","number":"Art. 1º, § 2º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º, § 2º - A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade."],"origin":"real","question":{"statement":"Sobre a Lei de Abuso de Autoridade (Lei nº 13.869/2019), julgue o item a seguir. A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.","answer":true,"explanation":"Art. 1º, § 2º - A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.","source":"33.pdf · questão 36 · Art. 1º, § 2º, Lei 13.869/2019","meta":"Instituto AOCP 2026 - Policial Penal (SEJUSP-MG)","bank":"Instituto AOCP","year":2026,"role":"Policial Penal (SEJUSP-MG)","origin":"real"}},{"id":"pen-lei-13869-pdf33-q037","discipline":"penal","topicId":"pen-lei-13869","subtopic":"Lei 13.869/2019 · Art. 2º","number":"Art. 2º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 2º É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo, mas não se limitando a: [...]"],"origin":"real","question":{"statement":"De acordo com a Lei n.º 13.869/2019, que dispõe sobre os crimes de abuso de autoridade, o sujeito ativo dos crimes de abuso de autoridade, em regra, pode ser qualquer pessoa, independentemente do exercício de função pública.","answer":false,"explanation":"Art. 2º É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo, mas não se limitando a: [...]","source":"33.pdf · questão 37 · Art. 2º, Lei 13.869/2019","meta":"CESPE/CEBRASPE 2026 - Auditor Fiscal da Receita Estadual (SEFAZ-RN)","bank":"CESPE/CEBRASPE","year":2026,"role":"Auditor Fiscal da Receita Estadual (SEFAZ-RN)","origin":"real"}},{"id":"pen-lei-1079-pdf7-q001","discipline":"penal","topicId":"pen-lei-1079","subtopic":"Lei 1.079/1950 · Art. 4º, V","number":"Art. 4º, V","title":"Lei 1.079/1950 — Crimes de Responsabilidade","parts":["Art. 4º São crimes de responsabilidade os atos do Presidente da República que atentarem contra a Constituição Federal, e, especialmente, contra: […] V - A probidade na administração;"],"origin":"real","question":{"statement":"A respeito da organização dos poderes da República, julgue o item que se segue. Ato do presidente da República que atente contra a probidade na administração pública configurará crime de responsabilidade, cujas normas de processo e de julgamento são de competência legislativa privativa da União.","answer":true,"explanation":"Art. 4º São crimes de responsabilidade os atos do Presidente da República que atentarem contra a Constituição Federal, e, especialmente, contra: […] V - A probidade na administração;","source":"7.pdf · questão 1 · Art. 4º, V, Lei 1.079/1950","meta":"CESPE/CEBRASPE 2017 - Analista Judiciário (TRF - 1ª Região)","bank":"CESPE/CEBRASPE","year":2017,"role":"Analista Judiciário (TRF - 1ª Região)","origin":"real"}},{"id":"pen-lei-1079-pdf7-q002","discipline":"penal","topicId":"pen-lei-1079","subtopic":"Lei 1.079/1950 · Art. 5º, 7","number":"Art. 5º, 7","title":"Lei 1.079/1950 — Crimes de Responsabilidade","parts":["Art. 5º São crimes de responsabilidade contra a existência política da União: […] 7 - violar a imunidade dos embaixadores ou ministros estrangeiros acreditados no país;"],"origin":"real","question":{"statement":"A Lei n° 1.079/1950 define os crimes de responsabilidade e regula o respectivo processo de julgamento. Nesse sentido, violar a imunidade dos embaixadores ou ministros estrangeiros acreditados no país apresenta um crime de responsabilidade contra a existência política da União.","answer":true,"explanation":"Art. 5º São crimes de responsabilidade contra a existência política da União: […] 7 - violar a imunidade dos embaixadores ou ministros estrangeiros acreditados no país;","source":"7.pdf · questão 2 · Art. 5º, 7, Lei 1.079/1950","meta":"IBFC 2020 - Analista Judiciário (TRE-PA)","bank":"IBFC","year":2020,"role":"Analista Judiciário (TRE-PA)","origin":"real"}},{"id":"pen-lei-1079-pdf7-q003","discipline":"penal","topicId":"pen-lei-1079","subtopic":"Lei 1.079/1950 · Art. 7º, 6","number":"Art. 7º, 6","title":"Lei 1.079/1950 — Crimes de Responsabilidade","parts":["Art. 7º São crimes de responsabilidade contra o livre exercício dos direitos políticos, individuais e sociais: […] 6 - subverter ou tentar subverter por meios violentos a ordem política e social;"],"origin":"real","question":{"statement":"Nos termos da Lei 1.079/50, é crime de responsabilidade contra o livre exercício dos poderes legislativo e judiciário e dos poderes constitucionais dos Estados subverter ou tentar subverter por meios violentos a ordem política e social.","answer":false,"explanation":"Art. 7º São crimes de responsabilidade contra o livre exercício dos direitos políticos, individuais e sociais: […] 6 - subverter ou tentar subverter por meios violentos a ordem política e social;","source":"7.pdf · questão 3 · Art. 7º, 6, Lei 1.079/1950","meta":"MPE-PR 2021 - Promotor de Justiça","bank":"MPE-PR","year":2021,"role":"Promotor de Justiça","origin":"real"}},{"id":"pen-lei-1079-pdf7-q004","discipline":"penal","topicId":"pen-lei-1079","subtopic":"Lei 1.079/1950 · Art. 79-A, I","number":"Art. 79-A, I","title":"Lei 1.079/1950 — Crimes de Responsabilidade","parts":["Art. 79-A. São crimes de responsabilidade do Presidente do CGIBS: I - omitir ou retardar dolosamente a publicação dos atos do CGIBS; (Incluído pela Lei Complementar nº 227, de 2026) [...["],"origin":"authorial","question":{"statement":"De acordo com a Lei Complementar 1.079/1950 (Define os crimes de responsabilidade e regula o respectivo processo de julgamento), é correto afirmar que omitir ou retardar dolosamente a publicação dos atos do CGIBS não é considerado crime de responsabilidade do Presidente do CGIBS.","answer":false,"explanation":"Art. 79-A. São crimes de responsabilidade do Presidente do CGIBS: I - omitir ou retardar dolosamente a publicação dos atos do CGIBS; (Incluído pela Lei Complementar nº 227, de 2026) [...[","source":"7.pdf · questão 4 · Art. 79-A, I, Lei 1.079/50","meta":"Exercício importado · Lei 1.079/1950","bank":"Exercício da fonte fornecida","year":null,"role":"","origin":"authorial"}},{"id":"cpp-lei-12830-pdf21-q001","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º","number":"Art. 2º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado."],"origin":"real","question":{"statement":"Sobre a Lei nº 12.830/2013 – investigação criminal conduzida pelo delegado de polícia, julgue o seguinte item. As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia não são de natureza jurídica, pois são de natureza administrativa, mas são essenciais e exclusivas de Estado.","answer":false,"explanation":"Art. 2º As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado.","source":"21.pdf · questão 1 · Art. 2º, Lei 12.830/2013","meta":"VUNESP 2022 - Delegado de Polícia (PC-RR)","bank":"VUNESP","year":2022,"role":"Delegado de Polícia (PC-RR)","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q006","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º, § 1º","number":"Art. 2º, § 1º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado. § 1º Ao delegado de polícia, na qualidade de autoridade policial, cabe a condução da investigação criminal por meio de inquérito policial ou outro procedimento previsto em lei, que tem como objetivo a apuração das circunstâncias, da materialidade e da autoria das infrações penais. [...]"],"origin":"real","question":{"statement":"Ao delegado de polícia, na qualidade de autoridade policial, cabe a condução da investigação criminal por meio de inquérito policial ou outro procedimento previsto em lei, que tem como objetivo a apuração das circunstâncias, da materialidade e da autoria das infrações penais.","answer":true,"explanation":"Art. 2º As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado. § 1º Ao delegado de polícia, na qualidade de autoridade policial, cabe a condução da investigação criminal por meio de inquérito policial ou outro procedimento previsto em lei, que tem como objetivo a apuração das circunstâncias, da materialidade e da autoria das infrações penais. [...]","source":"21.pdf · questão 6 · Art. 2º, § 1º, Lei 12.830/2013","meta":"MP-DFT 2021 - Promotor de Justiça","bank":"MP-DFT","year":2021,"role":"Promotor de Justiça","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q008","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º, § 2º","number":"Art. 2º, § 2º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º […] § 2º Durante a investigação criminal, cabe ao delegado de polícia a requisição de perícia, informações, documentos e dados que interessem à apuração dos fatos."],"origin":"real","question":{"statement":"Nos termos da Lei no 12.830/2013 (Investigação Criminal Conduzida pelo Delegado), é correto afirmar que, durante a investigação criminal, cabe ao Escrivão de Polícia a requisição de documentos e dados que interessem à apuração dos fatos.","answer":false,"explanation":"Art. 2º […] § 2º Durante a investigação criminal, cabe ao delegado de polícia a requisição de perícia, informações, documentos e dados que interessem à apuração dos fatos.","source":"21.pdf · questão 8 · Art. 2º, § 2º, Lei 12.830/2013","meta":"VUNESP 2018 - Delegado de Polícia (PC-SP)","bank":"VUNESP","year":2018,"role":"Delegado de Polícia (PC-SP)","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q010","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º, § 4º","number":"Art. 2º, § 4º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º […] § 4º O inquérito policial ou outro procedimento previsto em lei em curso somente poderá ser avocado ou redistribuído por superior hierárquico, mediante despacho fundamentado, por motivo de interesse público ou nas hipóteses de inobservância dos procedimentos previstos em regulamento da corporação que prejudique a eficácia da investigação."],"origin":"real","question":{"statement":"O inquérito policial ou outro procedimento previsto em lei em curso somente poderá ser avocado ou redistribuído por superior hierárquico, mediante despacho fundamentado, por motivo de interesse público ou nas hipóteses de inobservância dos procedimentos previstos em regulamento da corporação que prejudique a eficácia da investigação.","answer":true,"explanation":"Art. 2º […] § 4º O inquérito policial ou outro procedimento previsto em lei em curso somente poderá ser avocado ou redistribuído por superior hierárquico, mediante despacho fundamentado, por motivo de interesse público ou nas hipóteses de inobservância dos procedimentos previstos em regulamento da corporação que prejudique a eficácia da investigação.","source":"21.pdf · questão 10 · Art. 2º, § 4º, Lei 12.830/2013","meta":"FUNDATEC 2026 - Escrivão de Polícia (PC-RS)","bank":"FUNDATEC","year":2026,"role":"Escrivão de Polícia (PC-RS)","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q017","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º, § 5º","number":"Art. 2º, § 5º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º […] § 5º A remoção do delegado de polícia dar-se-á somente por ato fundamentado."],"origin":"real","question":{"statement":"Sobre a Lei nº 12.830/2013 – investigação criminal conduzida pelo delegado de polícia, julgue o seguinte item. A remoção do delegado de polícia dar-se-á somente por ato fundamentado de autoridade judiciária competente.","answer":false,"explanation":"Art. 2º […] § 5º A remoção do delegado de polícia dar-se-á somente por ato fundamentado.","source":"21.pdf · questão 17 · Art. 2º, § 5º, Lei 12.830/2013","meta":"VUNESP 2022 - Delegado de Polícia (PC-RR)","bank":"VUNESP","year":2022,"role":"Delegado de Polícia (PC-RR)","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q020","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 2º, § 6º","number":"Art. 2º, § 6º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 2º […] § 6º O indiciamento, privativo do delegado de polícia, dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato, que deverá indicar a autoria, materialidade e suas circunstâncias."],"origin":"real","question":{"statement":"Após tomar posse no cargo de Delegado de Polícia, Lucas participou, na qualidade de ouvinte, de palestra versando sobre as investigações criminais conduzidas pela Polícia Civil. Nesse cenário, considerando as disposições da Lei nº 12.830/2013, avalie a afirmativa a seguir. O indiciamento, exclusivo dos policiais civis, dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato, que deverá indicar a autoria, materialidade e suas circunstâncias.","answer":false,"explanation":"Art. 2º […] § 6º O indiciamento, privativo do delegado de polícia, dar-se-á por ato fundamentado, mediante análise técnico-jurídica do fato, que deverá indicar a autoria, materialidade e suas circunstâncias.","source":"21.pdf · questão 20 · Art. 2º, § 6º, Lei 12.830/2013","meta":"FGV 2026 - Delegado de Polícia (PC-PI)","bank":"FGV","year":2026,"role":"Delegado de Polícia (PC-PI)","origin":"real"}},{"id":"cpp-lei-12830-pdf21-q031","discipline":"cpp","topicId":"cpp-lei-12830","subtopic":"Lei 12.830/2013 · Art. 3º","number":"Art. 3º","title":"Lei 12.830/2013 — Investigação Criminal pelo Delegado","parts":["Art. 3º O cargo de delegado de polícia é privativo de bacharel em Direito, devendolhe ser dispensado o mesmo tratamento protocolar que recebem os magistrados, os membros da Defensoria Pública e do Ministério Público e os advogados."],"origin":"real","question":{"statement":"Após tomar posse no cargo de Delegado de Polícia, Lucas participou, na qualidade de ouvinte, de palestra versando sobre as investigações criminais conduzidas pela Polícia Civil. Nesse cenário, considerando as disposições da Lei nº 12.830/2013, avalie a afirmativa a seguir. O cargo de delegado de polícia é privativo de bacharel em Direito, devendo-lhe ser dispensado o mesmo tratamento protocolar que recebem os magistrados, os membros da Defensoria Pública e do Ministério Público e os advogados.","answer":true,"explanation":"Art. 3º O cargo de delegado de polícia é privativo de bacharel em Direito, devendolhe ser dispensado o mesmo tratamento protocolar que recebem os magistrados, os membros da Defensoria Pública e do Ministério Público e os advogados.","source":"21.pdf · questão 31 · Art. 3º, Lei 12.830/2013","meta":"FGV 2026 - Delegado de Polícia (PC-PI)","bank":"FGV","year":2026,"role":"Delegado de Polícia (PC-PI)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q001","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 1º","number":"Art. 1º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 1º Esta Lei institui o Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas e define crimes."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006 é a atual Lei sobre drogas. Tendo por base os ditames do citado diploma, é correto afirmar que o referido diploma legal institui o Sistema Nacional de Políticas Públicas sobre Drogas.","answer":true,"explanation":"Art. 1º Esta Lei institui o Sistema Nacional de Políticas Públicas sobre Drogas - Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas e define crimes.","source":"14.pdf · questão 1 · Art. 1º, Lei 11.343/2006","meta":"FUNDATEC 2018 - Escrivão de Polícia (PC-RS) - Adaptada","bank":"FUNDATEC","year":2018,"role":"Escrivão de Polícia (PC-RS) - Adaptada","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q004","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 1º, § único","number":"Art. 1º, § único","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 1º. [...] Parágrafo único. Para fins desta Lei, consideram-se como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006 prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e define crimes relacionados a essa questão, entre outras prescrições. Para fins dessa Lei, o artigo 1º (parágrafo único) considera como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União.","answer":true,"explanation":"Art. 1º. [...] Parágrafo único. Para fins desta Lei, consideram-se como drogas as substâncias ou os produtos capazes de causar dependência, assim especificados em lei ou relacionados em listas atualizadas periodicamente pelo Poder Executivo da União.","source":"14.pdf · questão 4 · Art. 1º, § único, Lei 11.343/2006","meta":"VUNESP 2025 - Cuidador Social (Prefeitura de Sertãozinho - SP)","bank":"VUNESP","year":2025,"role":"Cuidador Social (Prefeitura de Sertãozinho - SP)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q007","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 2º","number":"Art. 2º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso."],"origin":"real","question":{"statement":"Julgue o item subsecutivo, com relação ao Sistema Nacional de Políticas Públicas sobre Drogas. No Brasil, há proibição de plantio, cultura, colheita e exploração de vegetais dos quais possam ser extraídas drogas, salvo na hipótese, por exemplo, do previsto na Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971.","answer":true,"explanation":"Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso.","source":"14.pdf · questão 7 · Art. 2º, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2022 – Assistente Social (FUB)","bank":"CESPE/CEBRASPE","year":2022,"role":"Assistente Social (FUB)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q012","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 2º, § único","number":"Art. 2º, § único","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso. Parágrafo único. Pode a União autorizar o plantio, a cultura e a colheita dos vegetais referidos no caput deste artigo, exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização, respeitadas as ressalvas supramencionadas."],"origin":"real","question":{"statement":"A Lei nº 11.343/2006, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad; prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas; estabelece normas para repressão à produção não autorizada e ao tráfico ilícito de drogas; define crimes e dá outras providências. Essa lei, “proíbe em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar e pela União, respectivamente, em situações estritamente ritualístico-religioso e exclusivamente para fins medicinais ou científicos.","answer":true,"explanation":"Art. 2º Ficam proibidas, em todo o território nacional, as drogas, bem como o plantio, a cultura, a colheita e a exploração de vegetais e substratos dos quais possam ser extraídas ou produzidas drogas, ressalvada a hipótese de autorização legal ou regulamentar, bem como o que estabelece a Convenção de Viena, das Nações Unidas, sobre Substâncias Psicotrópicas, de 1971, a respeito de plantas de uso estritamente ritualístico-religioso. Parágrafo único. Pode a União autorizar o plantio, a cultura e a colheita dos vegetais referidos no caput deste artigo, exclusivamente para fins medicinais ou científicos, em local e prazo predeterminados, mediante fiscalização, respeitadas as ressalvas supramencionadas.","source":"14.pdf · questão 12 · Art. 2º, § único, Lei 11.343/2006","meta":"VUNESP 2025 - Cuidador Social (Prefeitura de Itapevi - SP)","bank":"VUNESP","year":2025,"role":"Cuidador Social (Prefeitura de Itapevi - SP)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q014","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º","number":"Art. 3º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas; II - a repressão da produção não autorizada e do tráfico ilícito de drogas."],"origin":"real","question":{"statement":"Considerando o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), instituído pela Lei n.º 11.343/2006, julgue o item que se segue. O SISNAD tem como finalidade articular, integrar, organizar e coordenar as atividades relacionadas com a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas, assim como a repressão da produção não autorizada e do tráfico ilícito de drogas.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas; II - a repressão da produção não autorizada e do tráfico ilícito de drogas.","source":"14.pdf · questão 14 · Art. 3º, Lei 11.343/2006","meta":"CESPE 2018 - Analista Judiciário - Serviço Social (STM)","bank":"CESPE","year":2018,"role":"Analista Judiciário - Serviço Social (STM)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q016","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º, I","number":"Art. 3º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas;"],"origin":"real","question":{"statement":"O Sistema Nacional de Políticas Públicas sobre Drogas prescreve medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas. De acordo com a Lei nº 11.343, de 23 de agosto de 2006, é correto afirmar que o SISNAD articula, integra, organiza e coordena as atividades relacionadas com a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: I - a prevenção do uso indevido, a atenção e a reinserção social de usuários e dependentes de drogas;","source":"14.pdf · questão 16 · Art. 3º, I, Lei 11.343/2006","meta":"FGV 2023 - Técnico de Gestão Administrativa (ALEMA)","bank":"FGV","year":2023,"role":"Técnico de Gestão Administrativa (ALEMA)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q019","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 3º, § 2º","number":"Art. 3º, § 2º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: [...] § 2º O Sisnad atuará em articulação com o Sistema Único de Saúde - SUS, e com o Sistema Único de Assistência Social - SUAS."],"origin":"real","question":{"statement":"Criado em 2006, o Sistema Nacional de Políticas sobre Drogas (SISNAD) é responsável por elaborar medidas de atenção reinserção social de usuários e dependentes de drogas, medidas de prevenção do uso indevido e as normas para repressão ao tráfico ilícito de drogas. Esse sistema, de acordo com a lei, está articulado com o Sistema Único de Saúde e o Sistema Único de Assistência Social.","answer":true,"explanation":"Art. 3º O Sisnad tem a finalidade de articular, integrar, organizar e coordenar as atividades relacionadas com: [...] § 2º O Sisnad atuará em articulação com o Sistema Único de Saúde - SUS, e com o Sistema Único de Assistência Social - SUAS.","source":"14.pdf · questão 19 · Art. 3º, § 2º, Lei 11.343/2006","meta":"FCC 2023 - Analista Judiciário (TJ-BA)","bank":"FCC","year":2023,"role":"Analista Judiciário (TJ-BA)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q022","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º","number":"Art. 4º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: […] VII - a integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito;"],"origin":"real","question":{"statement":"A Lei no 11.343, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas - SISNAD, prescrevendo medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, bem como estabelecendo normas para repressão à produção não autorizada e ao tráfico ilícito de drogas. Sobre isso, considere: A integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, diz respeito a um dos princípios estabelecidos na Lei.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: […] VII - a integração das estratégias nacionais e internacionais de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito;","source":"14.pdf · questão 22 · Art. 4º, Lei 11.343/2006","meta":"FCC 2015 - Analista Judiciário - Serviço Social (TRT - 3ª Região)","bank":"FCC","year":2015,"role":"Analista Judiciário - Serviço Social (TRT - 3ª Região)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q023","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, I","number":"Art. 4º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: I - o respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade;"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. O respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: I - o respeito aos direitos fundamentais da pessoa humana, especialmente quanto à sua autonomia e à sua liberdade;","source":"14.pdf · questão 23 · Art. 4º, I, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q026","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, III","number":"Art. 4º, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] III - a promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados;"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. A promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: [...] III - a promoção dos valores éticos, culturais e de cidadania do povo brasileiro, reconhecendo-os como fatores de proteção para o uso indevido de drogas e outros comportamentos correlacionados;","source":"14.pdf · questão 26 · Art. 4º, III, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q027","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, II","number":"Art. 4º, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] II - o respeito à diversidade e às especificidades populacionais existentes; [...]"],"origin":"real","question":{"statement":"Considerando os princípios do Sistema Nacional de Políticas Públicas sobre Drogas (Sisnad) e as disposições da Lei no 11.343/2006 julgue o item. O respeito à diversidade e às especificidades populacionais existentes.","answer":true,"explanation":"Art. 4º São princípios do Sisnad: [...] II - o respeito à diversidade e às especificidades populacionais existentes; [...]","source":"14.pdf · questão 27 · Art. 4º, II, Lei 11.343/2006","meta":"FGV 2024 - Agente Penitenciário (SEAP-BA)","bank":"FGV","year":2024,"role":"Agente Penitenciário (SEAP-BA)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q029","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, V","number":"Art. 4º, V","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] V - a promoção da responsabilidade compartilhada entre Estado e Sociedade, reconhecendo a importância da participação social nas atividades do Sisnad;"],"origin":"real","question":{"statement":"A Lei n.º 11.343/2006, que instituiu o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), reconhece, entre os princípios desse sistema, a supremacia do Estado nas questões do enfretamento ao uso indevido de drogas.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] V - a promoção da responsabilidade compartilhada entre Estado e Sociedade, reconhecendo a importância da participação social nas atividades do Sisnad;","source":"14.pdf · questão 29 · Art. 4º, V, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2021 - Analista Ministerial (MPEAP)","bank":"CESPE/CEBRASPE","year":2021,"role":"Analista Ministerial (MPEAP)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q031","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, VIII","number":"Art. 4º, VIII","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] VIII - a articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad;"],"origin":"real","question":{"statement":"A Lei Federal nº 11.343 de 23 de agosto de 2006 institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad e disciplina, no artigo 5º como objetivos do referido sistema aqueles que: A articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] VIII - a articulação com os órgãos do Ministério Público e dos Poderes Legislativo e Judiciário visando à cooperação mútua nas atividades do Sisnad;","source":"14.pdf · questão 31 · Art. 4º, VIII, Lei 11.343/2006","meta":"IBFC 2022 - Analista Judiciário (TJ-MG)","bank":"IBFC","year":2022,"role":"Analista Judiciário (TJ-MG)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q032","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, IX","number":"Art. 4º, IX","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: […] IX - a adoção de abordagem multidisciplinar que reconheça a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas;"],"origin":"real","question":{"statement":"A Lei n 11.343, de 23 de agosto de 2006, institui o Sistema Nacional de Políticas Públicas sobre Drogas - SISNAD, prescrevendo medidas para prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, bem como estabelecendo normas para repressão à produção não autorizada e ao tráfico ilícito de drogas. Sobre isso, considere: A adoção de abordagem interdisciplinar que reconhece a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas é uma das premissas da legislação vigente.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: […] IX - a adoção de abordagem multidisciplinar que reconheça a interdependência e a natureza complementar das atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas, repressão da produção não autorizada e do tráfico ilícito de drogas;","source":"14.pdf · questão 32 · Art. 4º, IX, Lei 11.343/2006","meta":"FCC 2015 - Analista Judiciário - Serviço Social (TRT - 3ª Região)","bank":"FCC","year":2015,"role":"Analista Judiciário - Serviço Social (TRT - 3ª Região)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q033","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 4º, X","number":"Art. 4º, X","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 4º São princípios do Sisnad: [...] X - a observância do equilíbrio entre as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, visando a garantir a estabilidade e o bem-estar social;"],"origin":"real","question":{"statement":"A Lei n.º 11.343/2006, que instituiu o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD), reconhece, entre os princípios desse sistema, a priorização das políticas de prevenção do uso indevido de drogas, de atenção e de reinserção social de usuários em detrimento da política de repressão à produção não autorizada dessas substâncias.","answer":false,"explanation":"Art. 4º São princípios do Sisnad: [...] X - a observância do equilíbrio entre as atividades de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao seu tráfico ilícito, visando a garantir a estabilidade e o bem-estar social;","source":"14.pdf · questão 33 · Art. 4º, X, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2021 - Analista Ministerial (MPEAP)","bank":"CESPE/CEBRASPE","year":2021,"role":"Analista Ministerial (MPEAP)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q034","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, I","number":"Art. 5º, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: I - contribuir para a inclusão social do cidadão, visando a torná-lo menos vulnerável a assumir comportamentos de risco para o uso indevido de drogas, seu tráfico ilícito e outros comportamentos correlacionados;"],"origin":"real","question":{"statement":"Julgue o item a seguir, relativos ao Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD). O SISNAD visa, principalmente, contribuir para a inclusão social da família, de modo a torná-la menos vulnerável a assumir comportamentos de risco que contribuam para o uso indevido de drogas.","answer":false,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: I - contribuir para a inclusão social do cidadão, visando a torná-lo menos vulnerável a assumir comportamentos de risco para o uso indevido de drogas, seu tráfico ilícito e outros comportamentos correlacionados;","source":"14.pdf · questão 34 · Art. 5º, I, Lei 11.343/2006","meta":"CESPE/CEBRASPE 2025 – Assistente Social (Polícia Federal)","bank":"CESPE/CEBRASPE","year":2025,"role":"Assistente Social (Polícia Federal)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q036","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, II","number":"Art. 5º, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: [...] II - promover a construção e a socialização do conhecimento sobre drogas no país;"],"origin":"real","question":{"statement":"Sobre a Lei de Drogas (Lei nº 11.343/2006), julgue o item. Promover a construção e a socialização do conhecimento sobre drogas no país é um dos princípios do Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad.","answer":false,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: [...] II - promover a construção e a socialização do conhecimento sobre drogas no país;","source":"14.pdf · questão 36 · Art. 5º, II, Lei 11.343/2006","meta":"Instituto AOCP 2024 - Soldado (PM-PE)","bank":"Instituto AOCP","year":2024,"role":"Soldado (PM-PE)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q039","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 5º, III","number":"Art. 5º, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 5º O Sisnad tem os seguintes objetivos: [...] III - promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios;"],"origin":"real","question":{"statement":"A Lei Federal nº 11.343 de 23 de agosto de 2006 destaca em seu artigo 5º que o Sistema Nacional de Políticas Públicas sobre Drogas (SISNAD) possui como objetivo: Promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios.","answer":true,"explanation":"Art. 5º O Sisnad tem os seguintes objetivos: [...] III - promover a integração entre as políticas de prevenção do uso indevido, atenção e reinserção social de usuários e dependentes de drogas e de repressão à sua produção não autorizada e ao tráfico ilícito e as políticas públicas setoriais dos órgãos do Poder Executivo da União, Distrito Federal, Estados e Municípios;","source":"14.pdf · questão 39 · Art. 5º, III, Lei 11.343/2006","meta":"IBFC 2022 - Orientador Social (Prefeitura de Dourados - MS)","bank":"IBFC","year":2022,"role":"Orientador Social (Prefeitura de Dourados - MS)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q040","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º, § 1º","number":"Art. 8º, § 1º","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: [...] § 1º O plano de que trata o caput terá duração de 5 (cinco) anos a contar de sua aprovação."],"origin":"real","question":{"statement":"O Plano Nacional de Políticas sobre Drogas terá duração de 15 anos a contar de sua aprovação.","answer":false,"explanation":"Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: [...] § 1º O plano de que trata o caput terá duração de 5 (cinco) anos a contar de sua aprovação.","source":"14.pdf · questão 40 · Art. 8º, § 1º, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC) - Adaptada","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC) - Adaptada","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q041","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, I","number":"Art. 8º-A, I","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A Compete à União: I - formular e coordenar a execução da Política Nacional sobre Drogas; *O inciso NÃO menciona a parceria da União com Estados, Distrito Federal, Municípios e Sociedade!"],"origin":"real","question":{"statement":"Compete à União, em parceria com Estados, Distrito Federal, Municípios e a sociedade, formular e coordenar a execução da Política Nacional sobre Drogas.","answer":false,"explanation":"Art. 8º-A Compete à União: I - formular e coordenar a execução da Política Nacional sobre Drogas; *O inciso NÃO menciona a parceria da União com Estados, Distrito Federal, Municípios e Sociedade!","source":"14.pdf · questão 41 · Art. 8º-A, I, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q042","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, II","number":"Art. 8º-A, II","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A. Compete à União: [...] II - elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade;"],"origin":"real","question":{"statement":"Compete à União elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade.","answer":true,"explanation":"Art. 8º-A. Compete à União: [...] II - elaborar o Plano Nacional de Políticas sobre Drogas, em parceria com Estados, Distrito Federal, Municípios e a sociedade;","source":"14.pdf · questão 42 · Art. 8º-A, II, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q043","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, III","number":"Art. 8º-A, III","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A Compete à União: [...] III - coordenar o Sisnad;"],"origin":"real","question":{"statement":"Compete à União, com Estados, Distrito Federal e Municípios, coordenar o Sisnad.","answer":false,"explanation":"Art. 8º-A Compete à União: [...] III - coordenar o Sisnad;","source":"14.pdf · questão 43 · Art. 8º-A, III, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q044","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-A, IX","number":"Art. 8º-A, IX","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-A. Compete à União: [...] IX - financiar, com Estados, Distrito Federal e Municípios, a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad;"],"origin":"real","question":{"statement":"Compete exclusivamente à União financiar a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad.","answer":false,"explanation":"Art. 8º-A. Compete à União: [...] IX - financiar, com Estados, Distrito Federal e Municípios, a execução das políticas sobre drogas, observadas as obrigações dos integrantes do Sisnad;","source":"14.pdf · questão 44 · Art. 8º-A, IX, Lei 11.343/2006","meta":"FEPESE 2019 - Agente Penitenciário (SJC-SC)","bank":"FEPESE","year":2019,"role":"Agente Penitenciário (SJC-SC)","origin":"real"}},{"id":"cpp-lei-11343-pdf14-q048","discipline":"cpp","topicId":"cpp-lei-11343","subtopic":"Lei 11.343/2006 · Art. 8º-D, IV","number":"Art. 8º-D, IV","title":"Lei 11.343/2006 — Lei de Drogas","parts":["Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: I - promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer, visando à prevenção do uso de drogas, atenção e reinserção social dos usuários ou dependentes de drogas;"],"origin":"real","question":{"statement":"A Lei nº 13.840 de 5 de junho de 2019, trata do Sistema Nacional de Políticas Públicas sobre Drogas, definindo as condições de atenção aos usuários ou dependentes de drogas e trata do financiamento das políticas sobre drogas. O Plano Nacional de Políticas sobre Drogas propõe certos objetivos. A partir disso, julgue o item levando em consideração os objetivos propostos pela Lei. Um dos objetivos é promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas.","answer":true,"explanation":"Art. 8º-D. São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros: I - promover a interdisciplinaridade e integração dos programas, ações, atividades e projetos dos órgãos e entidades públicas e privadas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer, visando à prevenção do uso de drogas, atenção e reinserção social dos usuários ou dependentes de drogas;","source":"14.pdf · questão 48 · Art. 8º-D, IV, Lei 11.343/2006","meta":"IBFC 2022 - Analista (DPE-MT)","bank":"IBFC","year":2022,"role":"Analista (DPE-MT)","origin":"real"}},{"id":"cpp-lei-12850-pdf23-q022","discipline":"cpp","topicId":"cpp-lei-12850","subtopic":"Lei 12.850/2013 · Art. 1º, § 1º","number":"Art. 1º, § 1º","title":"Lei 12.850/2013 — Organizações Criminosas","parts":["Art. 1º. […] § 1º Considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas máximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional."],"origin":"real","question":{"statement":"No julgamento da ADI 5.567, o STF pontuou que \"a criminalidade organizada é, hoje, um dos maiores problemas do mundo moderno. Apesar de não se tratar de fenômeno recente, o crescimento das organizações criminosas representa uma grave ameaça à sociedade, especialmente pelo grau de lesividade dos crimes por ela praticados e pela influência negativa que exercem dentro do próprio Estado. Dentro desse contexto de criminalidade organizada, a implementação de instrumentos processuais penais modernos, com mecanismos de ação controlada, punições mais severas e isolamento de lideranças criminosas são medidas para que o Estado equilibre forças com as referidas organizações criminosas, sob pena de tornar inócua grande parte das investigações criminais, principalmente no que tange à obtenção de provas\". (Fonte: https://portal.stf.jus.br/processos/downloadPeca.asp?id= 15364039995&ext=.pdf) Quanto ao conceito de organizações criminosas e os instrumentos processuais penais, no contexto da Lei nº 12.850, de 2 de agosto de 2013, é correto afirmar que considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas mãximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional.","answer":true,"explanation":"Art. 1º. […] § 1º Considera-se organização criminosa a associação de 4 (quatro) ou mais pessoas estruturalmente ordenada e caracterizada pela divisão de tarefas, ainda que informalmente, com objetivo de obter, direta ou indiretamente, vantagem de qualquer natureza, mediante a prática de infrações penais cujas penas máximas sejam superiores a 4 (quatro) anos, ou que sejam de caráter transnacional.","source":"23.pdf · questão 22 · Art. 1º, § 1º, Lei 12.850/2013","meta":"CETAP 2025 - Guarda Civil Municipal (Prefeitura de Marituba-PA)","bank":"CETAP","year":2025,"role":"Guarda Civil Municipal (Prefeitura de Marituba-PA)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q001","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Ementa da Lei 11.340/2006","number":"Ementa da Lei 11.340/2006","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["LEI Nº 11.340, DE 7 DE AGOSTO DE 2006 Cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências."],"origin":"real","question":{"statement":"A Lei Federal nº 11.340, de 7 de agosto de 2006, cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências.","answer":true,"explanation":"LEI Nº 11.340, DE 7 DE AGOSTO DE 2006 Cria mecanismos para coibir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra as Mulheres e da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; altera o Código de Processo Penal, o Código Penal e a Lei de Execução Penal; e dá outras providências.","source":"13.pdf · questão 1 · Lei 11.340/2006","meta":"IBFC 2022 - Delegado de Polícia - Prova Anulada (PC-BA)","bank":"IBFC","year":2022,"role":"Delegado de Polícia - Prova Anulada (PC-BA)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q004","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 1º","number":"Art. 1º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 1º - Esta Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher e de outros tratados internacionais ratificados pela República Federativa do Brasil; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; e estabelece medidas de assistência e proteção às mulheres em situação de violência doméstica e familiar."],"origin":"real","question":{"statement":"Sobre a Lei Maria da Penha, Lei nº 11.340/2006, que completou 18 anos em agosto de 2024, julgue o item a seguir. A legislação combate somente a violência doméstica e não a familiar.","answer":false,"explanation":"Art. 1º - Esta Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher e de outros tratados internacionais ratificados pela República Federativa do Brasil; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; e estabelece medidas de assistência e proteção às mulheres em situação de violência doméstica e familiar.","source":"13.pdf · questão 4 · Art. 1º, Lei 11.340/2006","meta":"Instituto Consulplan 2025 - Auxiliar - Serviços Públicos (Prefeitura de Carangola - MG)","bank":"Instituto Consulplan","year":2025,"role":"Auxiliar - Serviços Públicos (Prefeitura de Carangola - MG)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q006","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 2º","number":"Art. 2º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 2º - Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social."],"origin":"real","question":{"statement":"Conforme o art. 2º da Lei nº 11.340/2006, julgue o item a seguir sobre os direitos garantidos às mulheres. Toda mulher, independentemente de sua orientação sexual ou religião, tem direito a viver sem violência.","answer":true,"explanation":"Art. 2º - Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social.","source":"13.pdf · questão 6 · Art. 2º, Lei 11.340/2006","meta":"IGEDUC 2025 - Assistente Social (Prefeitura de Japaratinga - AL)","bank":"IGEDUC","year":2025,"role":"Assistente Social (Prefeitura de Japaratinga - AL)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q008","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 3º","number":"Art. 3º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 3º - Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, representa um marco legal no combate à violência doméstica e familiar contra a mulher no Brasil. Ela se fundamenta em normas para assegurar proteção efetiva. No que se refere as disposições preliminares da Lei Maria da Penha, julgue o item a seguir. Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária.","answer":true,"explanation":"Art. 3º - Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária.","source":"13.pdf · questão 8 · Art. 3º, Lei 11.340/2006","meta":"AMEOSC 2025 - Assistente Social (Prefeitura de Guaraciaba - SC)","bank":"AMEOSC","year":2025,"role":"Assistente Social (Prefeitura de Guaraciaba - SC)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q009","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 3º, § 1º","number":"Art. 3º, § 1º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 3º, § 1º - O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares no sentido de resguardá-las de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão."],"origin":"real","question":{"statement":"Com base na Lei n.º 11.340/2006, relativa aos mecanismos para coibir a violência doméstica e familiar contra a mulher, julgue o item a seguir. Cabe ao poder público o desenvolvimento de políticas públicas voltadas à garantia dos direitos humanos da mulher no âmbito das relações domésticas e familiares, com o intuito de resguardá-la de todas as formas de violência, discriminação e opressão.","answer":true,"explanation":"Art. 3º, § 1º - O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares no sentido de resguardá-las de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.","source":"13.pdf · questão 9 · Art. 3º, § 1º, Lei 11.340/2006","meta":"CESPE/CEBRASPE 2023 - Analista - Apoio Jurídico (CNMP)","bank":"CESPE/CEBRASPE","year":2023,"role":"Analista - Apoio Jurídico (CNMP)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q010","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 4º","number":"Art. 4º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 4º - Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, representa um marco legal no combate à violência doméstica e familiar contra a mulher no Brasil. Ela se fundamenta em normas para assegurar proteção efetiva. No que se refere as disposições preliminares da Lei Maria da Penha, julgue o item a seguir. Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar.","answer":true,"explanation":"Art. 4º - Na interpretação desta Lei, serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar.","source":"13.pdf · questão 10 · Art. 4º, Lei 11.340/2006","meta":"AMEOSC 2025 - Assistente Social (Prefeitura de Guaraciaba - SC)","bank":"AMEOSC","year":2025,"role":"Assistente Social (Prefeitura de Guaraciaba - SC)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q015","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º","number":"Art. 5º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação."],"origin":"real","question":{"statement":"Julgue o item a seguir, considerando as disposições da Lei Maria da Penha (Lei n.º 11.340/2006). Configura violência doméstica e familiar contra a mulher ação baseada no gênero que lhe cause dano patrimonial em relação íntima de afeto na qual o agressor tenha convivido com a ofendida, independentemente de coabitação.","answer":true,"explanation":"Art. 5º Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação.","source":"13.pdf · questão 15 · Art. 5º, Lei 11.340/2006","meta":"CESPE/CEBRASPE 2025 - Agente Administrativo (PCDF)","bank":"CESPE/CEBRASPE","year":2025,"role":"Agente Administrativo (PCDF)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q019","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, I","number":"Art. 5º, I","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340, de 7 de agosto de 2006, conhecida como Lei Maria da Penha, institui, em seu Art. 5º, que a violência doméstica e familiar contra a mulher é qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial. Avalie se este artigo se aplica à seguinte situação: No âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas.","answer":true,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: I - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas; [...]","source":"13.pdf · questão 19 · Art. 5º, I, Lei 11.340/2006","meta":"FGV 2023 - Analista de Promotoria - Assistente Social (MPE-SP)","bank":"FGV","year":2023,"role":"Analista de Promotoria - Assistente Social (MPE-SP)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q021","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, II","number":"Art. 5º, II","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340, de 7 de agosto de 2006, conhecida como Lei Maria da Penha, institui, em seu Art. 5º, que a violência doméstica e familiar contra a mulher é qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial. Avalie se este artigo se aplica à seguinte situação: No âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa.","answer":true,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] II - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa; [...]","source":"13.pdf · questão 21 · Art. 5º, II, Lei 11.340/2006","meta":"FGV 2023 - Analista de Promotoria - Assistente Social (MPE-SP)","bank":"FGV","year":2023,"role":"Analista de Promotoria - Assistente Social (MPE-SP)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q027","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, III","number":"Art. 5º, III","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação. [...]"],"origin":"real","question":{"statement":"A Lei nº 11.340/2006 leva o nome da farmacêutica Maria da Penha Maia Fernandes, vítima de duas tentativas de feminicídio e que tornou-se símbolo da luta contra a violência de gênero. Quanto à essa norma é correto afirmar que a incidência da Lei Maria da Penha exige convivência doméstica atual entre agressor e vítima, sendo inviável a sua aplicação quando a relação afetiva tiver cessado antes do fato.","answer":false,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] III - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação. [...]","source":"13.pdf · questão 27 · Art. 5º, III, Lei 11.340/2006","meta":"MPDFT 2025 - Promotor de Justiça (MP-DFT)","bank":"MPDFT","year":2025,"role":"Promotor de Justiça (MP-DFT)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q033","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 5º, § único","number":"Art. 5º, § único","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] Parágrafo único - As relações pessoais enunciadas neste artigo independem de orientação sexual."],"origin":"real","question":{"statement":"A Lei nº 11.340/2006, conhecida como Lei Maria da Penha, estabelece: Configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial, desde que constatado que as relações entre os envolvidos são de natureza exclusivamente heterossexual.","answer":false,"explanation":"Art. 5º - Para os efeitos desta Lei, configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial: [...] Parágrafo único - As relações pessoais enunciadas neste artigo independem de orientação sexual.","source":"13.pdf · questão 33 · Art. 5º, § único, Lei 11.340/2006","meta":"FCC 2023 - Técnico Ministerial (MPE-PB)","bank":"FCC","year":2023,"role":"Técnico Ministerial (MPE-PB)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q039","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 6º","number":"Art. 6º","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 6º - A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos."],"origin":"real","question":{"statement":"A respeito da Lei nº 11.340/2006, mais conhecida como Lei Maria da Penha, julgue o item a seguir. A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos.","answer":true,"explanation":"Art. 6º - A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos.","source":"13.pdf · questão 39 · Art. 6º, Lei 11.340/2006","meta":"FAFIPA 2025 - Guarda Municipal (Prefeitura de Araucária - PR)","bank":"FAFIPA","year":2025,"role":"Guarda Municipal (Prefeitura de Araucária - PR)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q040","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 7º, I","number":"Art. 7º, I","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 7º São formas de violência doméstica e familiar contra a mulher, entre outras: I - a violência física, entendida como qualquer conduta que ofenda sua integridade ou saúde corporal; […]"],"origin":"real","question":{"statement":"A Lei Maria da Penha é uma legislação brasileira que cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, estabelecendo medidas protetivas de urgência, como afastamento do agressor e proibição de contato, além de punições mais severas para agressores. Conforme a referida Lei, é correto afirmar que a conduta que ofenda a integridade ou a saúde corporal da mulher é classificada como violência física.","answer":true,"explanation":"Art. 7º São formas de violência doméstica e familiar contra a mulher, entre outras: I - a violência física, entendida como qualquer conduta que ofenda sua integridade ou saúde corporal; […]","source":"13.pdf · questão 40 · Art. 7º, I, Lei 11.340/2006","meta":"FUNDATEC 2026 - Auditor Fiscal de Tributos (Prefeitura de Três Passos-RS)","bank":"FUNDATEC","year":2026,"role":"Auditor Fiscal de Tributos (Prefeitura de Três Passos-RS)","origin":"real"}},{"id":"cpp-lei-11340-pdf13-q044","discipline":"cpp","topicId":"cpp-lei-11340","subtopic":"Lei 11.340/2006 · Art. 7º, II","number":"Art. 7º, II","title":"Lei 11.340/2006 — Lei Maria da Penha","parts":["Art. 7º - São formas de violência doméstica e familiar contra a mulher, entre outras: [...] II - a violência psicológica, entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação; [...]"],"origin":"real","question":{"statement":"Com base na Lei 11.340/2006, em relação à mulher, a violência entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação denominase violência psicológica.","answer":true,"explanation":"Art. 7º - São formas de violência doméstica e familiar contra a mulher, entre outras: [...] II - a violência psicológica, entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação; [...]","source":"13.pdf · questão 44 · Art. 7º, II, Lei 11.340/2006","meta":"Instituto ACCESS 2023 - Guarda Civil Metropolitano (Prefeitura de Ribeirão Preto - SP)","bank":"Instituto ACCESS","year":2023,"role":"Guarda Civil Metropolitano (Prefeitura de Ribeirão Preto - SP)","origin":"real"}},{"id":"cpp-lei-13869-pdf33-q002","discipline":"cpp","topicId":"cpp-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º","number":"Art. 1º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º - Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído."],"origin":"real","question":{"statement":"Acerca do crime de abuso de autoridade e das definições constantes da Lei n.º 13.869/2019, julgue o item subsequente. Para a caracterização do crime de abuso de autoridade, é preciso que o agente esteja no exercício de suas funções públicas.","answer":false,"explanation":"Art. 1º - Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído.","source":"33.pdf · questão 2 · Art. 1º, Lei 13.869/2019","meta":"CESPE/CEBRASPE 2025 - Especialista em Recursos Minerais - Engenharia de Minas - Correcional (ANM)","bank":"CESPE/CEBRASPE","year":2025,"role":"Especialista em Recursos Minerais - Engenharia de Minas - Correcional (ANM)","origin":"real"}},{"id":"cpp-lei-13869-pdf33-q006","discipline":"cpp","topicId":"cpp-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º, § 1º","number":"Art. 1º, § 1º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído. § 1º As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal."],"origin":"real","question":{"statement":"De acordo com o que dispõe a Lei Federal nº 13.869/2019 (crimes de abuso de autoridade), é correto afirmar que as condutas descritas nesta lei constituem crime de abuso de autoridade quando praticadas pelo agente ainda que por mero capricho ou satisfação pessoal.","answer":true,"explanation":"Art. 1º Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído. § 1º As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal.","source":"33.pdf · questão 6 · Art. 1º, § 1º, Lei 13.869/2019","meta":"FCC 2026 - Auditor Fiscal da Receita Estadual (SEFAZ-GO)","bank":"FCC","year":2026,"role":"Auditor Fiscal da Receita Estadual (SEFAZ-GO)","origin":"real"}},{"id":"cpp-lei-13869-pdf33-q036","discipline":"cpp","topicId":"cpp-lei-13869","subtopic":"Lei 13.869/2019 · Art. 1º, § 2º","number":"Art. 1º, § 2º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 1º, § 2º - A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade."],"origin":"real","question":{"statement":"Sobre a Lei de Abuso de Autoridade (Lei nº 13.869/2019), julgue o item a seguir. A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.","answer":true,"explanation":"Art. 1º, § 2º - A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.","source":"33.pdf · questão 36 · Art. 1º, § 2º, Lei 13.869/2019","meta":"Instituto AOCP 2026 - Policial Penal (SEJUSP-MG)","bank":"Instituto AOCP","year":2026,"role":"Policial Penal (SEJUSP-MG)","origin":"real"}},{"id":"cpp-lei-13869-pdf33-q037","discipline":"cpp","topicId":"cpp-lei-13869","subtopic":"Lei 13.869/2019 · Art. 2º","number":"Art. 2º","title":"Lei 13.869/2019 — Abuso de Autoridade","parts":["Art. 2º É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo, mas não se limitando a: [...]"],"origin":"real","question":{"statement":"De acordo com a Lei n.º 13.869/2019, que dispõe sobre os crimes de abuso de autoridade, o sujeito ativo dos crimes de abuso de autoridade, em regra, pode ser qualquer pessoa, independentemente do exercício de função pública.","answer":false,"explanation":"Art. 2º É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo, mas não se limitando a: [...]","source":"33.pdf · questão 37 · Art. 2º, Lei 13.869/2019","meta":"CESPE/CEBRASPE 2026 - Auditor Fiscal da Receita Estadual (SEFAZ-RN)","bank":"CESPE/CEBRASPE","year":2026,"role":"Auditor Fiscal da Receita Estadual (SEFAZ-RN)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q002","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 2º","number":"Art. 2º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 2º - O processo orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, buscando, sempre que possível, a conciliação ou a transação."],"origin":"real","question":{"statement":"Em relação aos Juizados Especiais Criminais (Lei nº 9.099/95) e sua interpretação pelos Tribunais Superiores, julgue o item a seguir. Economia processual, oralidade, formalidade e celeridade são princípios que regem o procedimento nos Juizados Especiais Criminais.","answer":false,"explanation":"Art. 2º - O processo orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, buscando, sempre que possível, a conciliação ou a transação.","source":"61.pdf · questão 2 · Art. 2º, Lei 9.099/95","meta":"INSTITUTO AOCP 2022 - Promotor de Justiça Substituto (MPE-MS)","bank":"INSTITUTO AOCP","year":2022,"role":"Promotor de Justiça Substituto (MPE-MS)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q005","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 4º, III","number":"Art. 4º, III","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 4º É competente, para as causas previstas nesta Lei, o Juizado do foro: […] III - do domicílio do autor ou do local do ato ou fato, nas ações para reparação de dano de qualquer natureza."],"origin":"real","question":{"statement":"Considere, hipoteticamente, que João Batista reside no município de Belo Horizonte e tem interesse em ajuizar uma ação de indenização por dano moral e material contra uma determinada instituição financeira, cujo valor total da ação é de quarenta salários mínimos, referente a um fato que ocorreu na cidade de Juiz de Fora, onde autor da ação exerce as suas atividades profissionais. Diante de tal cenário, é correto afirmar que a referida ação judicial poderá ser distribuída no Juizado Especial Cível da comarca Juiz de Fora ou de Belo Horizonte, de acordo com a escolha do autor da ação.","answer":true,"explanation":"Art. 4º É competente, para as causas previstas nesta Lei, o Juizado do foro: […] III - do domicílio do autor ou do local do ato ou fato, nas ações para reparação de dano de qualquer natureza.","source":"61.pdf · questão 5 · Art. 4º, III, Lei 9.099/95","meta":"CONSULPLAN 2024 - Estagiário (TJ-MG)","bank":"CONSULPLAN","year":2024,"role":"Estagiário (TJ-MG)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q006","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º","number":"Art. 3º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] IV - as ações possessórias sobre bens imóveis de valor não excedente ao fixado no inciso I deste artigo."],"origin":"real","question":{"statement":"Nos Juizados Especiais Cíveis só se admitem ações possessórias sobre bens móveis, mas não sobre bens imóveis.","answer":false,"explanation":"Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] IV - as ações possessórias sobre bens imóveis de valor não excedente ao fixado no inciso I deste artigo.","source":"61.pdf · questão 6 · Art. 3º, Lei 9.099/95","meta":"FCC 2019 - Juiz Substituto (TJ-AL)","bank":"FCC","year":2019,"role":"Juiz Substituto (TJ-AL)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q010","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, I","number":"Art. 3º, I","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: I - as causas cujo valor não exceda a quarenta vezes o salário mínimo; […]"],"origin":"real","question":{"statement":"Em relação ao valor das causas, o Juizado Especial tem competência para conciliação, processo e Julgamento das causas cíveis de menor complexidade, assim consideradas aquelas cujo valor não exceda a 80 vezes o salário mínimo.","answer":false,"explanation":"Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: I - as causas cujo valor não exceda a quarenta vezes o salário mínimo; […]","source":"61.pdf · questão 10 · Art. 3º, I, Lei 9.099/95","meta":"FCC 2023 - Técnico Judiciário (TRT - 12ª Região)","bank":"FCC","year":2023,"role":"Técnico Judiciário (TRT - 12ª Região)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q016","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, III","number":"Art. 3º, III","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: […] III - a ação de despejo para uso próprio; […]"],"origin":"real","question":{"statement":"Sobre os Juizados Especiais Cíveis, é correto afirmar que pode ser utilizado para ação de despejo para uso próprio. Entretanto, não pode ser utilizado para causas de natureza alimentar.","answer":true,"explanation":"Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: […] III - a ação de despejo para uso próprio; […]","source":"61.pdf · questão 16 · Art. 3º, III, Lei 9.099/95","meta":"Instituto Consulplan 2025 - Técnico Judiciário (TJ-RO)","bank":"Instituto Consulplan","year":2025,"role":"Técnico Judiciário (TJ-RO)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q022","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, IV","number":"Art. 3º, IV","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] IV - as ações possessórias sobre bens imóveis de valor não excedente ao fixado no inciso I deste artigo."],"origin":"real","question":{"statement":"Em tema de valor da causa no âmbito dos Juizados Especiais, avalie a assertiva a seguir. O Juizado Especial Cível não tem competência para conciliação, processo e julgamento das ações possessórias sobre bens imóveis, qualquer que seja o valor.","answer":false,"explanation":"Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] IV - as ações possessórias sobre bens imóveis de valor não excedente ao fixado no inciso I deste artigo.","source":"61.pdf · questão 22 · Art. 3º, IV, Lei 9.099/95","meta":"FGV 2026 – Juiz de Direito (TJ-PR)","bank":"FGV","year":2026,"role":"Juiz de Direito (TJ-PR)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q023","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, § 1º, I","number":"Art. 3º, § 1º, I","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º. […] § 1º Compete ao Juizado Especial promover a execução: I - dos seus julgados; […]"],"origin":"real","question":{"statement":"Acerca da competência dos Juizados Especiais Cíveis, nos termos da lei, é correto afirmar que o Juizado Especial não possui competência para execução dos seus julgados.","answer":false,"explanation":"Art. 3º. […] § 1º Compete ao Juizado Especial promover a execução: I - dos seus julgados; […]","source":"61.pdf · questão 23 · Art. 3º, § 1º, I, Lei 9.099/95","meta":"Instituto ACCESS 2022 - Juiz Leigo (TJ-PB)","bank":"Instituto ACCESS","year":2022,"role":"Juiz Leigo (TJ-PB)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q024","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, § 1º, II","number":"Art. 3º, § 1º, II","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º […] § 1º Compete ao Juizado Especial promover a execução: […] II - dos títulos executivos extrajudiciais, no valor de até quarenta vezes o salário mínimo, observado o disposto no § 1º do art. 8º desta Lei."],"origin":"real","question":{"statement":"No que concerne aos procedimentos dos Juizados Especiais Cíveis, é correto afirmar que não podem ser promovidas execuções fundadas em títulos executivos extrajudiciais, ainda que relativas a valor igual ou inferior a quarenta salários mínimos.","answer":false,"explanation":"Art. 3º […] § 1º Compete ao Juizado Especial promover a execução: […] II - dos títulos executivos extrajudiciais, no valor de até quarenta vezes o salário mínimo, observado o disposto no § 1º do art. 8º desta Lei.","source":"61.pdf · questão 24 · Art. 3º, § 1º, II, Lei 9.099/95","meta":"FGV 2024 - Analista Judiciário (TJ-MS)","bank":"FGV","year":2024,"role":"Analista Judiciário (TJ-MS)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q028","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, § 2º","number":"Art. 3º, § 2º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º. […] § 2º Ficam excluídas da competência do Juizado Especial as causas de natureza alimentar, falimentar, fiscal e de interesse da Fazenda Pública, e também as relativas a acidentes de trabalho, a resíduos e ao estado e capacidade das pessoas, ainda que de cunho patrimonial."],"origin":"real","question":{"statement":"De acordo com o que dispõe a Lei nº 9.099/95, que dispõe sobre os Juizados Especiais Cíveis e Criminais e dá outras providências, é correto afirmar que ficam excluídas da competência do Juizado Especial as causas de natureza alimentar, falimentar, fiscal e de interesse da Fazenda Pública, e também as relativas a acidentes de trabalho, a resíduos e ao estado e capacidade das pessoas, ainda que de cunho patrimonial.","answer":true,"explanation":"Art. 3º. […] § 2º Ficam excluídas da competência do Juizado Especial as causas de natureza alimentar, falimentar, fiscal e de interesse da Fazenda Pública, e também as relativas a acidentes de trabalho, a resíduos e ao estado e capacidade das pessoas, ainda que de cunho patrimonial.","source":"61.pdf · questão 28 · Art. 3º, § 2º, Lei 9.099/95","meta":"FAFIPA 2023 - Advogado (FAZPREV)","bank":"FAFIPA","year":2023,"role":"Advogado (FAZPREV)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q033","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 3º, § 3º","number":"Art. 3º, § 3º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] § 3º A opção pelo procedimento previsto nesta Lei importará em renúncia ao crédito excedente ao limite estabelecido neste artigo, excetuada a hipótese de conciliação."],"origin":"real","question":{"statement":"Em tema de valor da causa no âmbito dos Juizados Especiais, avalie a assertiva a seguir. A opção pelo procedimento previsto na Lei nº 9.099/95 importa em renúncia ao crédito excedente ao limite estabelecido nesta lei, incluída a hipótese de conciliação, que não pode ultrapassar tal limite.","answer":false,"explanation":"Art. 3º O Juizado Especial Cível tem competência para conciliação, processo e julgamento das causas cíveis de menor complexidade, assim consideradas: [...] § 3º A opção pelo procedimento previsto nesta Lei importará em renúncia ao crédito excedente ao limite estabelecido neste artigo, excetuada a hipótese de conciliação.","source":"61.pdf · questão 33 · Art. 3º, § 3º, Lei 9.099/95","meta":"FGV 2026 – Juiz de Direito (TJ-PR)","bank":"FGV","year":2026,"role":"Juiz de Direito (TJ-PR)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q034","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 4º, I","number":"Art. 4º, I","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 4º - É competente, para as causas previstas nesta Lei, o Juizado do foro: I - do domicílio do réu ou, a critério do autor, do local onde aquele exerça atividades profissionais ou econômicas ou mantenha estabelecimento, filial, agência, sucursal ou escritório; [...]"],"origin":"real","question":{"statement":"Sobre o que dispõe a Lei nº 9.099/1995, em seu Capítulo II (Dos Juizados Especiais Cíveis), julgue o item a seguir. É competente, para as causas sujeitas ao rito da Lei nº 9.099/1995, o foro do domicílio do réu ou, a critério do autor, do local onde aquele exerça atividades profissionais ou econômicas ou mantenha estabelecimento, filial, agência, sucursal ou escritório.","answer":true,"explanation":"Art. 4º - É competente, para as causas previstas nesta Lei, o Juizado do foro: I - do domicílio do réu ou, a critério do autor, do local onde aquele exerça atividades profissionais ou econômicas ou mantenha estabelecimento, filial, agência, sucursal ou escritório; [...]","source":"61.pdf · questão 34 · Art. 4º, I, Lei 9.099/95","meta":"Instituto Consulplan 2022 - Juiz Leigo (TJ-CE)","bank":"Instituto Consulplan","year":2022,"role":"Juiz Leigo (TJ-CE)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q035","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 5º","number":"Art. 5º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 5º O Juiz dirigirá o processo com liberdade para determinar as provas a serem produzidas, para apreciá-las e para dar especial valor às regras de experiência comum ou técnica."],"origin":"real","question":{"statement":"Acerca dos juizados especiais cíveis, é correto afirmar que o Juiz dirigirá o processo com liberdade para determinar as provas a serem produzidas, para apreciá-las e para dar especial valor às regras de experiência comum ou técnica.","answer":true,"explanation":"Art. 5º O Juiz dirigirá o processo com liberdade para determinar as provas a serem produzidas, para apreciá-las e para dar especial valor às regras de experiência comum ou técnica.","source":"61.pdf · questão 35 · Art. 5º, Lei 9.099/95","meta":"VUNESP 2023 - Advogado (CIJUN)","bank":"VUNESP","year":2023,"role":"Advogado (CIJUN)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q036","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 7º","number":"Art. 7º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 7º Os conciliadores e Juízes leigos são auxiliares da Justiça, recrutados, os primeiros, preferentemente, entre os bacharéis em Direito, e os segundos, entre advogados com mais de cinco anos de experiência."],"origin":"real","question":{"statement":"Acerca da atuação dos juízes leigos e das partes em sede de Juizados Especiais, não é necessário, aos juízes leigos, que sejam bacharéis em Direito, bastando curso superior.","answer":false,"explanation":"Art. 7º Os conciliadores e Juízes leigos são auxiliares da Justiça, recrutados, os primeiros, preferentemente, entre os bacharéis em Direito, e os segundos, entre advogados com mais de cinco anos de experiência.","source":"61.pdf · questão 36 · Art. 7º, Lei 9.099/95","meta":"Instituto ACCESS 2022 - Juiz Leigo (TJ-PB)","bank":"Instituto ACCESS","year":2022,"role":"Juiz Leigo (TJ-PB)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q037","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 7º, § único","number":"Art. 7º, § único","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 7º. […] Parágrafo único. Os Juízes leigos ficarão impedidos de exercer a advocacia perante os Juizados Especiais, enquanto no desempenho de suas funções."],"origin":"real","question":{"statement":"Acerca dos juizados especiais cíveis, é correto afirmar que os Juízes leigos ficarão impedidos de exercer a advocacia perante os Juizados Especiais pelo prazo de dois anos após o término do desempenho de suas funções.","answer":false,"explanation":"Art. 7º. […] Parágrafo único. Os Juízes leigos ficarão impedidos de exercer a advocacia perante os Juizados Especiais, enquanto no desempenho de suas funções.","source":"61.pdf · questão 37 · Art. 7º, parágrafo único, Lei 9.099/95","meta":"VUNESP 2023 - Advogado (CIJUN)","bank":"VUNESP","year":2023,"role":"Advogado (CIJUN)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q046","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 8º","number":"Art. 8º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 8º Não poderão ser partes, no processo instituído por esta Lei, o incapaz, o preso, as pessoas jurídicas de direito público, as empresas públicas da União, a massa falida e o insolvente civil."],"origin":"real","question":{"statement":"Segundo o disposto na Lei nº 9.099/1995, podem figurar como parte autora no Juizado Especial Cível os menores de 16 anos.","answer":false,"explanation":"Art. 8º Não poderão ser partes, no processo instituído por esta Lei, o incapaz, o preso, as pessoas jurídicas de direito público, as empresas públicas da União, a massa falida e o insolvente civil.","source":"61.pdf · questão 46 · Art. 8º, Lei 9.099/95","meta":"FCC 2024 - Analista Judiciário - Área Administrativa (TRT - 11ª Região - AM e RR)","bank":"FCC","year":2024,"role":"Analista Judiciário - Área Administrativa (TRT - 11ª Região - AM e RR)","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q049","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 8º, §1º","number":"Art. 8º, §1º","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 8º [...] § 1º Somente serão admitidas a propor ação perante o Juizado Especial: […] III - as pessoas jurídicas qualificadas como Organização da Sociedade Civil de Interesse Público, nos termos da Lei n o 9.790, de 23 de março de 1999;"],"origin":"real","question":{"statement":"Sobre os Juizados Especiais Cíveis, instituídos pela Lei nº 9.099/95, é correto afirmar que as pessoas jurídicas qualificadas como organização da sociedade civil de interesse público, nos termos da Lei nº 9.790/99, são admitidas a propor ação perante o Juizado Especial.","answer":true,"explanation":"Art. 8º [...] § 1º Somente serão admitidas a propor ação perante o Juizado Especial: […] III - as pessoas jurídicas qualificadas como Organização da Sociedade Civil de Interesse Público, nos termos da Lei n o 9.790, de 23 de março de 1999;","source":"61.pdf · questão 49 · Art. 8º, §1º, Lei 9.099/95","meta":"CONSULPLAN 2017 - Tabelião / Oficial de Registros - Provimento (TJ-MG) - Adaptada","bank":"CONSULPLAN","year":2017,"role":"Tabelião / Oficial de Registros - Provimento (TJ-MG) - Adaptada","origin":"real"}},{"id":"cpc-lei-9099-pdf61-q050","discipline":"cpc","topicId":"cpc-lei-9099","subtopic":"Lei 9.099/1995 · Art. 8º, § 1º, I","number":"Art. 8º, § 1º, I","title":"Lei 9.099/1995 — Juizados Especiais Cíveis","parts":["Art. 8º. […] § 1o Somente serão admitidas a propor ação perante o Juizado Especial: I - as pessoas físicas capazes, excluídos os cessionários de direito de pessoas jurídicas; […]"],"origin":"real","question":{"statement":"De acordo com a Lei nº 9.099/1995, no âmbito dos Juizados Especiais Cíveis, não podem ser parte as pessoas físicas cessionárias de direito de pessoas jurídicas.","answer":true,"explanation":"Art. 8º. […] § 1o Somente serão admitidas a propor ação perante o Juizado Especial: I - as pessoas físicas capazes, excluídos os cessionários de direito de pessoas jurídicas; […]","source":"61.pdf · questão 50 · Art. 8º, § 1º, I, Lei 9.099/95","meta":"FCC 2023 - Técnico Judiciário (TRT-21ª Região)","bank":"FCC","year":2023,"role":"Técnico Judiciário (TRT-21ª Região)","origin":"real"}}];
